INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-1', 0, '[{"n":1,"start":0,"end":1.68,"parts":[{"zh":"你好！"}],"pinyin":"Nǐ hǎo!","vi":"Chào bạn!"},{"n":2,"start":1.68,"end":5.13,"parts":[{"zh":"你好！请问，你叫什么名字？"}],"pinyin":"Nǐ hǎo! Qǐngwèn, nǐ jiào shénme míngzi?","vi":"Chào bạn! Cho hỏi, bạn tên là gì?"},{"n":3,"start":5.13,"end":7.51,"parts":[{"zh":"我叫王小美。你呢？"}],"pinyin":"Wǒ jiào Wáng Xiǎoměi. Nǐ ne?","vi":"Tôi gọi là Vương Tiểu Mỹ. Còn bạn?"},{"n":4,"start":7.51,"end":11.16,"parts":[{"zh":"我叫李大伟。这位是王先生。"}],"pinyin":"Wǒ jiào Lǐ Dàwěi. Zhè wèi shì Wáng xiānsheng.","vi":"Tôi tên Lý Đại Vỹ. Vị này là ông Vương."},{"n":5,"start":11.16,"end":13.51,"parts":[{"zh":"王先生，你好！"}],"pinyin":"Wáng xiānsheng, nǐ hǎo!","vi":"Chào ông Vương!"},{"n":6,"start":13.51,"end":16.71,"parts":[{"zh":"你好，你好！请进，请坐。"}],"pinyin":"Nǐ hǎo, nǐ hǎo! Qǐng jìn, qǐng zuò.","vi":"Chào chào! Mời vào, mời ngồi."},{"n":7,"start":16.71,"end":19.26,"parts":[{"zh":"谢谢！她们是谁？"}],"pinyin":"Xièxie! Tāmen shì shéi?","vi":"Cảm ơn! Họ là ai vậy?"},{"n":8,"start":19.26,"end":22.96,"parts":[{"zh":"她们是我的朋友们。小姐，你好吗？"}],"pinyin":"Tāmen shì wǒ de péngyǒumen. Xiǎojiě, nǐ hǎo ma?","vi":"Họ là bạn của tôi. Cô gái, bạn khỏe không?"},{"n":9,"start":22.96,"end":26.44,"parts":[{"zh":"我很好，谢谢。对不起，我要走了。"}],"pinyin":"Wǒ hěn hǎo, xièxie. Duìbuqǐ, wǒ yào zǒu le.","vi":"Tôi khỏe, cảm ơn. Xin lỗi, tôi phải đi rồi."},{"n":10,"start":26.44,"end":28.96,"parts":[{"zh":"没关系。再见！"}],"pinyin":"Méi guānxi. Zàijiàn!","vi":"Không sao đâu. Tạm biệt!"},{"n":11,"start":28.96,"end":31.29,"parts":[{"zh":"再见！明天见。"}],"pinyin":"Zàijiàn! Míngtiān jiàn.","vi":"Tạm biệt! Hẹn gặp ngày mai."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-2';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-2', 0, '[{"n":1,"start":0,"end":3.12,"parts":[{"zh":"老师，您好！这是我的朋友。"}],"pinyin":"Lǎoshī, nín hǎo! Zhè shì wǒ de péngyǒu.","vi":"Thưa thầy, chào thầy! Đây là bạn của em."},{"n":2,"start":3.12,"end":6.17,"parts":[{"zh":"你好！请你介绍一下。"}],"pinyin":"Nǐ hǎo! Qǐng nǐ jièshào yíxià.","vi":"Chào em! Em hãy giới thiệu nhé."},{"n":3,"start":6.17,"end":9.05,"parts":[{"zh":"他叫马克，他是外国人。"}],"pinyin":"Tā jiào Mǎkè, tā shì wàiguórén.","vi":"Anh ấy tên Mã Khắc, anh ấy là người nước ngoài."},{"n":4,"start":9.05,"end":12.15,"parts":[{"zh":"你好，马克！你是哪国人？"}],"pinyin":"Nǐ hǎo, Mǎkè! Nǐ shì nǎ guó rén?","vi":"Chào Mã Khắc! Bạn là người nước nào?"},{"n":5,"start":12.15,"end":15.05,"parts":[{"zh":"我是美国人。这是哪儿？"}],"pinyin":"Wǒ shì Měiguórén. Zhè shì nǎr?","vi":"Tôi là người Mỹ. Đây là đâu vậy?"},{"n":6,"start":15.05,"end":18.95,"parts":[{"zh":"这里是我们学校，那边是图书馆。"}],"pinyin":"Zhèlǐ shì wǒmen xuéxiào, nàbiān shì túshūguǎn.","vi":"Đây là trường của chúng tôi, kia là thư viện."},{"n":7,"start":18.95,"end":22.3,"parts":[{"zh":"谁在那边？他们在这里做什么？"}],"pinyin":"Shéi zài nàbiān? Tāmen zài zhèlǐ zuò shénme?","vi":"Ai ở đằng kia vậy? Họ đang làm gì ở đây?"},{"n":8,"start":22.3,"end":26.700000000000003,"parts":[{"zh":"那边是我的同学们，他们在这儿学习汉语。"}],"pinyin":"Nàbiān shì wǒ de tóngxuémen, tāmen zài zhèr xuéxí Hànyǔ.","vi":"Kia là các bạn cùng lớp của tôi, họ đang học tiếng Trung ở đây."},{"n":9,"start":26.700000000000003,"end":29.250000000000004,"parts":[{"zh":"哪些人也是学生？"}],"pinyin":"Nǎxiē rén yě shì xuésheng?","vi":"Những ai cũng là học sinh vậy?"},{"n":10,"start":29.250000000000004,"end":34.28,"parts":[{"zh":"这些都是学生。你不要开玩笑，快去认识他们！"}],"pinyin":"Zhèxiē dōu shì xuésheng. Nǐ búyào kāi wánxiào, kuài qù rènshi tāmen!","vi":"Tất cả những người này đều là học sinh. Đừng đùa nữa, mau đi làm quen với họ đi!"},{"n":11,"start":34.28,"end":36.78,"parts":[{"zh":"好，我现在就过去。"}],"pinyin":"Hǎo, wǒ xiànzài jiù guòqù.","vi":"Được, tôi sẽ qua đó ngay bây giờ."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-3';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-3', 0, '[{"n":1,"start":0,"end":2.52,"parts":[{"zh":"请进！这是我的家。"}],"pinyin":"Qǐng jìn! Zhè shì wǒ de jiā.","vi":"Mời vào! Đây là nhà của tôi."},{"n":2,"start":2.52,"end":6.02,"parts":[{"zh":"谢谢！你的家人都在家里吗？"}],"pinyin":"Xièxie! Nǐ de jiārén dōu zài jiālǐ ma?","vi":"Cảm ơn! Gia đình bạn có ai ở nhà hết không?"},{"n":3,"start":6.02,"end":9.54,"parts":[{"zh":"他们在客厅。这是我爸爸和妈妈。"}],"pinyin":"Tāmen zài kètīng. Zhè shì wǒ bàba hé māma.","vi":"Họ ở phòng khách. Đây là bố và mẹ của tôi."},{"n":4,"start":9.54,"end":12.94,"parts":[{"zh":"叔叔阿姨好！这几位是谁？"}],"pinyin":"Shūshu āyí hǎo! Zhè jǐ wèi shì shéi?","vi":"Chào chú và dì! Mấy người này là ai vậy?"},{"n":5,"start":12.94,"end":16.919999999999998,"parts":[{"zh":"这是我哥哥，这是我姐姐，那是我妹妹。"}],"pinyin":"Zhè shì wǒ gēge, zhè shì wǒ jiějie, nà shì wǒ mèimei.","vi":"Đây là anh trai tôi, đây là chị gái tôi, còn kia là em gái tôi."},{"n":6,"start":16.919999999999998,"end":19.65,"parts":[{"zh":"你的爷爷和奶奶呢？"}],"pinyin":"Nǐ de yéye hé nǎinai ne?","vi":"Ông và bà của bạn đâu?"},{"n":7,"start":19.65,"end":22.68,"parts":[{"zh":"他们不在，他们去儿子家了。"}],"pinyin":"Tāmen bú zài, tāmen qù érzi jiā le.","vi":"Họ không ở đây, họ đi nhà con trai rồi."},{"n":8,"start":22.68,"end":24.8,"parts":[{"zh":"你有儿子吗？"}],"pinyin":"Nǐ yǒu érzi ma?","vi":"Bạn có con trai không?"},{"n":9,"start":24.8,"end":27.650000000000002,"parts":[{"zh":"没有儿子，我有一个女儿。"}],"pinyin":"Méiyǒu érzi, wǒ yǒu yí ge nǚ''ér.","vi":"Không có con trai, tôi có một con gái."},{"n":10,"start":27.650000000000002,"end":30.880000000000003,"parts":[{"zh":"她真可爱！你女儿几岁了？"}],"pinyin":"Tā zhēn kě''ài! Nǐ nǚ''ér jǐ suì le?","vi":"Cô bé đáng yêu thật! Con gái bạn mấy tuổi rồi?"},{"n":11,"start":30.880000000000003,"end":33.800000000000004,"parts":[{"zh":"她五岁了。来，我们喝茶吧。"}],"pinyin":"Tā wǔ suì le. Lái, wǒmen hē chá ba.","vi":"Nó năm tuổi rồi. Nào, mình uống trà đi."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-4';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-4', 0, '[{"n":1,"start":0,"end":2.48,"parts":[{"zh":"今天是我的生日！"}],"pinyin":"Jīntiān shì wǒ de shēngrì!","vi":"Hôm nay là sinh nhật của tôi!"},{"n":2,"start":2.48,"end":5.3100000000000005,"parts":[{"zh":"真的吗？生日快乐！"}],"pinyin":"Zhēn de ma? Shēngrì kuàilè!","vi":"Thật sao? Chúc mừng sinh nhật!"},{"n":3,"start":5.3100000000000005,"end":8.31,"parts":[{"zh":"谢谢！我请了很多朋友。"}],"pinyin":"Xièxie! Wǒ qǐng le hěn duō péngyǒu.","vi":"Cảm ơn! Tôi mời rất nhiều bạn bè."},{"n":4,"start":8.31,"end":11.89,"parts":[{"zh":"有小朋友吗？我的孩子想去。"}],"pinyin":"Yǒu xiǎopéngyǒu ma? Wǒ de háizi xiǎng qù.","vi":"Có trẻ con không? Con của tôi muốn đi."},{"n":5,"start":11.89,"end":14.89,"parts":[{"zh":"有，他们都是我的小同学。"}],"pinyin":"Yǒu, tāmen dōu shì wǒ de xiǎo tóngxué.","vi":"Có, các bạn ấy đều là bạn học nhỏ của tôi."},{"n":6,"start":14.89,"end":18.490000000000002,"parts":[{"zh":"你们班的男生多还是女生多？"}],"pinyin":"Nǐmen bān de nánshēng duō háishì nǚshēng duō?","vi":"Lớp của bạn nam nhiều hay nữ nhiều?"},{"n":7,"start":18.490000000000002,"end":21.520000000000003,"parts":[{"zh":"男生多，女生只有四个。"}],"pinyin":"Nánshēng duō, nǚshēng zhǐyǒu sì ge.","vi":"Nam nhiều hơn, nữ chỉ có bốn bạn."},{"n":8,"start":21.520000000000003,"end":24.570000000000004,"parts":[{"zh":"我女儿也是你的同学吗？"}],"pinyin":"Wǒ nǚ''ér yě shì nǐ de tóngxué ma?","vi":"Con gái tôi cũng là bạn cùng lớp của bạn à?"},{"n":9,"start":24.570000000000004,"end":28.200000000000003,"parts":[{"zh":"是，她是我的好朋友，我们都喜欢她。"}],"pinyin":"Shì, tā shì wǒ de hǎo péngyǒu, wǒmen dōu xǐhuan tā.","vi":"Vâng, bạn ấy là bạn thân của tôi, ai cũng thích bạn ấy."},{"n":10,"start":28.200000000000003,"end":31.53,"parts":[{"zh":"太好了！现在我们去看她吧。"}],"pinyin":"Tài hǎo le! Xiànzài wǒmen qù kàn tā ba.","vi":"Tốt quá! Bây giờ chúng ta đi thăm cô bé nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-5';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-5', 0, '[{"n":1,"start":0,"end":2.65,"parts":[{"zh":"老板，这个多少钱？"}],"pinyin":"Lǎobǎn, zhège duōshao qián?","vi":"Chủ cửa hàng, cái này bao nhiêu tiền?"},{"n":2,"start":2.65,"end":4.38,"parts":[{"zh":"十块。"}],"pinyin":"Shí kuài.","vi":"Mười tệ."},{"n":3,"start":4.38,"end":6.93,"parts":[{"zh":"太贵了，八块可以吗？"}],"pinyin":"Tài guì le, bā kuài kěyǐ ma?","vi":"Đắt quá, tám tệ được không?"},{"n":4,"start":6.93,"end":9.629999999999999,"parts":[{"zh":"可以。你还要别的吗？"}],"pinyin":"Kěyǐ. Nǐ hái yào bié de ma?","vi":"Được. Bạn còn muốn mua gì nữa không?"},{"n":5,"start":9.629999999999999,"end":13.229999999999999,"parts":[{"zh":"我要三本书，一个杯子，两包茶。"}],"pinyin":"Wǒ yào sān běn shū, yí ge bēizi, liǎng bāo chá.","vi":"Tôi muốn ba cuốn sách, một cái cốc, hai gói trà."},{"n":6,"start":13.229999999999999,"end":15.959999999999999,"parts":[{"zh":"一共一百零八块。"}],"pinyin":"Yígòng yìbǎi líng bā kuài.","vi":"Cộng lại là một trăm lẻ tám tệ."},{"n":7,"start":15.959999999999999,"end":18.34,"parts":[{"zh":"这里是两百元。"}],"pinyin":"Zhèlǐ shì liǎngbǎi yuán.","vi":"Đây là hai trăm tệ."},{"n":8,"start":18.34,"end":20.99,"parts":[{"zh":"找你九十二块。"}],"pinyin":"Zhǎo nǐ jiǔshí''èr kuài.","vi":"Tôi trả lại bạn chín mươi hai tệ."},{"n":9,"start":20.99,"end":23.639999999999997,"parts":[{"zh":"这些钱是对的。再见！"}],"pinyin":"Zhèxiē qián shì duì de. Zàijiàn!","vi":"Tiền này là đúng rồi. Tạm biệt!"},{"n":10,"start":23.639999999999997,"end":26.309999999999995,"parts":[{"zh":"再见！明天再来。"}],"pinyin":"Zàijiàn! Míngtiān zài lái.","vi":"Tạm biệt! Mai quay lại nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-6';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-6', 0, '[{"n":1,"start":0,"end":3.08,"parts":[{"zh":"请问，今天是几月几号？"}],"pinyin":"Qǐngwèn, jīntiān shì jǐ yuè jǐ hào?","vi":"Cho hỏi, hôm nay là ngày mấy tháng mấy?"},{"n":2,"start":3.08,"end":6.08,"parts":[{"zh":"今天是十月十五号。"}],"pinyin":"Jīntiān shì shí yuè shíwǔ hào.","vi":"Hôm nay là ngày mười lăm tháng mười."},{"n":3,"start":6.08,"end":8.66,"parts":[{"zh":"明天是你的生日吗？"}],"pinyin":"Míngtiān shì nǐ de shēngrì ma?","vi":"Mai là sinh nhật của bạn à?"},{"n":4,"start":8.66,"end":12.24,"parts":[{"zh":"不是，我的生日是十二月一日。"}],"pinyin":"Bú shì, wǒ de shēngrì shì shí''èr yuè yí rì.","vi":"Không phải, sinh nhật tôi là ngày một tháng mười hai."},{"n":5,"start":12.24,"end":15.72,"parts":[{"zh":"你前天去哪儿了？我昨天找你。"}],"pinyin":"Nǐ qiántiān qù nǎr le? Wǒ zuótiān zhǎo nǐ.","vi":"Hôm kia bạn đi đâu vậy? Tôi tìm bạn hôm qua."},{"n":6,"start":15.72,"end":19.62,"parts":[{"zh":"我昨天在家里，前天在朋友家。"}],"pinyin":"Wǒ zuótiān zài jiālǐ, qiántiān zài péngyǒu jiā.","vi":"Hôm qua tôi ở nhà, hôm kia ở nhà bạn tôi."},{"n":7,"start":19.62,"end":22.450000000000003,"parts":[{"zh":"下个星期天你有空吗？"}],"pinyin":"Xià ge xīngqītiān nǐ yǒu kòng ma?","vi":"Chủ nhật tới bạn có rảnh không?"},{"n":8,"start":22.450000000000003,"end":25.480000000000004,"parts":[{"zh":"星期日我有点儿事。"}],"pinyin":"Xīngqīrì wǒ yǒudiǎnr shì.","vi":"Chủ nhật tôi hơi có việc."},{"n":9,"start":25.480000000000004,"end":27.530000000000005,"parts":[{"zh":"那后天呢？"}],"pinyin":"Nà hòutiān ne?","vi":"Vậy mốt thì sao?"},{"n":10,"start":27.530000000000005,"end":30.700000000000003,"parts":[{"zh":"后天可以。我们晚上见。"}],"pinyin":"Hòutiān kěyǐ. Wǒmen wǎnshang jiàn.","vi":"Mốt thì được. Tối chúng ta gặp nhau nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-7';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-7', 0, '[{"n":1,"start":0,"end":2.17,"parts":[{"zh":"现在几点了？"}],"pinyin":"Xiànzài jǐ diǎn le?","vi":"Bây giờ là mấy giờ rồi?"},{"n":2,"start":2.17,"end":5.17,"parts":[{"zh":"现在是上午九点。"}],"pinyin":"Xiànzài shì shàngwǔ jiǔ diǎn.","vi":"Bây giờ là chín giờ sáng."},{"n":3,"start":5.17,"end":8.57,"parts":[{"zh":"我早上六点就起床了，很累。"}],"pinyin":"Wǒ zǎoshang liù diǎn jiù qǐchuáng le, hěn lèi.","vi":"Tôi sáu giờ sáng đã dậy rồi, rất mệt."},{"n":4,"start":8.57,"end":11.95,"parts":[{"zh":"你昨天晚上几点睡觉？"}],"pinyin":"Nǐ zuótiān wǎnshang jǐ diǎn shuìjiào?","vi":"Tối qua bạn mấy giờ đi ngủ?"},{"n":5,"start":11.95,"end":15.28,"parts":[{"zh":"十二点半，我睡的时间太少了。"}],"pinyin":"Shí''èr diǎn bàn, wǒ shuì de shíjiān tài shǎo le.","vi":"Mười hai giờ rưỡi, thời gian tôi ngủ quá ít."},{"n":6,"start":15.28,"end":18.8,"parts":[{"zh":"今晚你要工作到什么时候？"}],"pinyin":"Jīnwǎn nǐ yào gōngzuò dào shénme shíhou?","vi":"Tối nay bạn sẽ làm việc đến mấy giờ?"},{"n":7,"start":18.8,"end":21.75,"parts":[{"zh":"中午十二点我就下班了。"}],"pinyin":"Zhōngwǔ shí''èr diǎn wǒ jiù xiàbān le.","vi":"Mười hai giờ trưa tôi đã tan làm rồi."},{"n":8,"start":21.75,"end":25.13,"parts":[{"zh":"那下午我们一起去学校吧。"}],"pinyin":"Nà xiàwǔ wǒmen yìqǐ qù xuéxiào ba.","vi":"Vậy chiều chúng ta cùng đến trường nhé."},{"n":9,"start":25.13,"end":28.18,"parts":[{"zh":"好，我马上来。你等我一会儿。"}],"pinyin":"Hǎo, wǒ mǎshàng lái. Nǐ děng wǒ yíhuìr.","vi":"Được, tôi đến ngay. Bạn chờ tôi một lát."},{"n":10,"start":28.18,"end":31.18,"parts":[{"zh":"今年的新年你回家吗？"}],"pinyin":"Jīnnián de xīnnián nǐ huí jiā ma?","vi":"Năm nay ngày Tết bạn có về nhà không?"},{"n":11,"start":31.18,"end":35.68,"parts":[{"zh":"我们学校明年一月放假，我今年不能回家。"}],"pinyin":"Wǒmen xuéxiào míngnián yí yuè fàngjià, wǒ jīnnián bù néng huí jiā.","vi":"Trường tôi nghỉ hè tháng Một năm sau, năm nay tôi không về được."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-8';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-8', 0, '[{"n":1,"start":0,"end":2.6,"parts":[{"zh":"你在哪儿学习汉语？"}],"pinyin":"Nǐ zài nǎr xuéxí Hànyǔ?","vi":"Bạn học tiếng Trung ở đâu?"},{"n":2,"start":2.6,"end":5.98,"parts":[{"zh":"我在语言学院学习中文。"}],"pinyin":"Wǒ zài yǔyán xuéyuàn xuéxí Zhōngwén.","vi":"Tôi học tiếng Trung ở Học viện ngôn ngữ."},{"n":3,"start":5.98,"end":8.780000000000001,"parts":[{"zh":"你们班有多少个学生？"}],"pinyin":"Nǐmen bān yǒu duōshao ge xuésheng?","vi":"Lớp của bạn có bao nhiêu học sinh?"},{"n":4,"start":8.780000000000001,"end":11.760000000000002,"parts":[{"zh":"十个学生，两个老师。"}],"pinyin":"Shí ge xuésheng, liǎng ge lǎoshī.","vi":"Mười học sinh, hai giáo viên."},{"n":5,"start":11.760000000000002,"end":15.510000000000002,"parts":[{"zh":"我们今天读课文，明天听写汉字。"}],"pinyin":"Wǒmen jīntiān dú kèwén, míngtiān tīngxiě Hànzì.","vi":"Hôm nay chúng tôi đọc bài học."},{"n":6,"start":15.510000000000002,"end":18.130000000000003,"parts":[{"zh":"今天的课文难吗？"}],"pinyin":"Jīntiān de kèwén nán ma?","vi":"Bài học hôm nay khó không?"},{"n":7,"start":18.130000000000003,"end":22.21,"parts":[{"zh":"不太难，可是我的书包里有二十个生字。"}],"pinyin":"Bú tài nán, kěshì wǒ de shūbāo lǐ yǒu èrshí ge shēngzì.","vi":"Không quá khó, nhưng cặp của tôi có hai mươi chữ mới."},{"n":8,"start":22.21,"end":24.46,"parts":[{"zh":"你的课本呢？"}],"pinyin":"Nǐ de kèběn ne?","vi":"Sách giáo khoa của bạn đâu?"},{"n":9,"start":24.46,"end":27.46,"parts":[{"zh":"书和本子都在桌子上。"}],"pinyin":"Shū hé běnzi dōu zài zhuōzi shang.","vi":"Sách và vở đều ở trên bàn."},{"n":10,"start":27.46,"end":30.73,"parts":[{"zh":"放学以后，我们一起读书吧。"}],"pinyin":"Fàngxué yǐhòu, wǒmen yìqǐ dúshū ba.","vi":"Sau giờ học, mình cùng đọc sách nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-9';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-9', 0, '[{"n":1,"start":0,"end":2.9,"parts":[{"zh":"明天我们考试，你记得吗？"}],"pinyin":"Míngtiān wǒmen kǎoshì, nǐ jìde ma?","vi":"Ngày mai chúng ta kiểm tra, bạn nhớ không?"},{"n":2,"start":2.9,"end":5.73,"parts":[{"zh":"哎呀！我忘了！考什么？"}],"pinyin":"Āiyā! Wǒ wàng le! Kǎo shénme?","vi":"Trời ơi, tôi quên mất rồi! Thi cái gì vậy?"},{"n":3,"start":5.73,"end":9.38,"parts":[{"zh":"考汉字和课文。你不应该忘记！"}],"pinyin":"Kǎo Hànzì hé kèwén. Nǐ bù yīnggāi wàngjì!","vi":"Thi chữ Hán và bài học. Bạn không nên quên chứ!"},{"n":4,"start":9.38,"end":13.530000000000001,"parts":[{"zh":"我晚上在图书馆复习，你别担心。"}],"pinyin":"Wǒ wǎnshang zài túshūguǎn fùxí, nǐ bié dānxīn.","vi":"Tối tôi ôn bài ở thư viện, bạn đừng lo."},{"n":5,"start":13.530000000000001,"end":16.98,"parts":[{"zh":"我早上八点上课，中午下课。"}],"pinyin":"Wǒ zǎoshang bā diǎn shàngkè, zhōngwǔ xiàkè.","vi":"Tôi tám giờ sáng vào lớp, trưa thì tan học."},{"n":6,"start":16.98,"end":20.23,"parts":[{"zh":"你女儿在哪个小学上学？"}],"pinyin":"Nǐ nǚ''ér zài nǎ ge xiǎoxué shàngxué?","vi":"Con gái bạn học tiểu học nào?"},{"n":7,"start":20.23,"end":24.310000000000002,"parts":[{"zh":"她在第五小学，她每天走路去上学。"}],"pinyin":"Tā zài dì-wǔ xiǎoxué, tā měitiān zǒulù qù shàngxué.","vi":"Nó học tiểu học số năm, ngày nào cũng đi bộ đến trường."},{"n":8,"start":24.310000000000002,"end":27.080000000000002,"parts":[{"zh":"中学生也考试吗？"}],"pinyin":"Zhōngxuéshēng yě kǎoshì ma?","vi":"Học sinh trung học cũng có thi không?"},{"n":9,"start":27.080000000000002,"end":30.98,"parts":[{"zh":"当然，他们考试很多，知识也很多。"}],"pinyin":"Dāngrán, tāmen kǎoshì hěn duō, zhīshi yě hěn duō.","vi":"Đương nhiên rồi, họ thi rất nhiều, kiến thức cũng nhiều."},{"n":10,"start":30.98,"end":35.480000000000004,"parts":[{"zh":"那我们快去教学楼吧！要记住明天的考试！"}],"pinyin":"Nà wǒmen kuài qù jiàoxué lóu ba! Yào jìzhù míngtiān de kǎoshì!","vi":"Vậy mình mau đến tòa nhà học đi! Phải nhớ kỳ thi ngày mai đó!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-10';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-10', 0, '[{"n":1,"start":0,"end":2.33,"parts":[{"zh":"喂，你在干什么？"}],"pinyin":"Wéi, nǐ zài gàn shénme?","vi":"A-lô, bạn đang làm gì vậy?"},{"n":2,"start":2.33,"end":5.1,"parts":[{"zh":"我在上网，你在忙吗？"}],"pinyin":"Wǒ zài shàngwǎng, nǐ zài máng ma?","vi":"Tôi đang lướt mạng, bạn có bận không?"},{"n":3,"start":5.1,"end":8.73,"parts":[{"zh":"很忙。我在开会，我的手机要没电了。"}],"pinyin":"Hěn máng. Wǒ zài kāihuì, wǒ de shǒujī yào méi diàn le.","vi":"Bận lắm. Tôi đang họp, điện thoại sắp hết pin rồi."},{"n":4,"start":8.73,"end":11.850000000000001,"parts":[{"zh":"那你晚上给我打电话吧。"}],"pinyin":"Nà nǐ wǎnshang gěi wǒ dǎ diànhuà ba.","vi":"Vậy tối bạn gọi điện cho tôi nhé."},{"n":5,"start":11.850000000000001,"end":15.150000000000002,"parts":[{"zh":"好。我六点下班，七点到家。"}],"pinyin":"Hǎo. Wǒ liù diǎn xiàbān, qī diǎn dào jiā.","vi":"Được. Sáu giờ tôi tan làm, bảy giờ về đến nhà."},{"n":6,"start":15.150000000000002,"end":17.950000000000003,"parts":[{"zh":"你今天上班累吗？"}],"pinyin":"Nǐ jīntiān shàngbān lèi ma?","vi":"Hôm nay đi làm bạn có mệt không?"},{"n":7,"start":17.950000000000003,"end":21.800000000000004,"parts":[{"zh":"很累，工人叔叔们从早工作到晚。"}],"pinyin":"Hěn lèi, gōngrén shūshumen cóng zǎo gōngzuò dào wǎn.","vi":"Mệt lắm, các chú công nhân làm việc từ sáng đến tối."},{"n":8,"start":21.800000000000004,"end":25.380000000000003,"parts":[{"zh":"晚上看看电视吧，别工作了。"}],"pinyin":"Wǎnshang kànkan diànshì ba, bié gōngzuò le.","vi":"Tối thì xem tivi đi, đừng làm việc nữa."},{"n":9,"start":25.380000000000003,"end":28.71,"parts":[{"zh":"好主意！我买了一个新电视机。"}],"pinyin":"Hǎo zhǔyi! Wǒ mǎi le yí ge xīn diànshìjī.","vi":"Ý hay đấy! Tôi mới mua một cái tivi mới."},{"n":10,"start":28.71,"end":32.59,"parts":[{"zh":"太好了，晚上见！别忘了打电话！"}],"pinyin":"Tài hǎo le, wǎnshang jiàn! Bié wàngle dǎ diànhuà!","vi":"Tốt quá, tối gặp nhau nhé! Đừng quên gọi điện đó!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-11';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-11', 0, '[{"n":1,"start":0,"end":2.92,"parts":[{"zh":"我累了，我们休息一下吧。"}],"pinyin":"Wǒ lèi le, wǒmen xiūxi yíxià ba.","vi":"Tôi mệt rồi, mình nghỉ một chút nhé."},{"n":2,"start":2.92,"end":6.57,"parts":[{"zh":"好。你看，前面有一个大商场。"}],"pinyin":"Hǎo. Nǐ kàn, qiánmiàn yǒu yí ge dà shāngchǎng.","vi":"Được đấy. Nhìn kìa, phía trước có một trung tâm thương mại to."},{"n":3,"start":6.57,"end":10.09,"parts":[{"zh":"我们去书店，我要买一本汉语书。"}],"pinyin":"Wǒmen qù shūdiàn, wǒ yào mǎi yì běn Hànyǔ shū.","vi":"Chúng ta đến nhà sách đi, tôi muốn mua một cuốn sách tiếng Trung."},{"n":4,"start":10.09,"end":13.44,"parts":[{"zh":"好，再买些东西吃吧，我饿了。"}],"pinyin":"Hǎo, zài mǎi xiē dōngxi chī ba, wǒ è le.","vi":"Được, rồi mua thêm đồ ăn nhé, tôi đói rồi."},{"n":5,"start":13.44,"end":16.689999999999998,"parts":[{"zh":"我带了我的钱包，我来拿钱。"}],"pinyin":"Wǒ dài le wǒ de qiánbāo, wǒ lái ná qián.","vi":"Tôi mang ví rồi, để tôi lấy tiền."},{"n":6,"start":16.689999999999998,"end":19.939999999999998,"parts":[{"zh":"这个书店的东西很贵吗？"}],"pinyin":"Zhège shūdiàn de dōngxi hěn guì ma?","vi":"Đồ ở nhà sách này có đắt không?"},{"n":7,"start":19.939999999999998,"end":22.319999999999997,"parts":[{"zh":"不贵，书也很好。"}],"pinyin":"Bú guì, shū yě hěn hǎo.","vi":"Không đắt, sách cũng hay nữa."},{"n":8,"start":22.319999999999997,"end":24.519999999999996,"parts":[{"zh":"那快走吧！"}],"pinyin":"Nà kuài zǒu ba!","vi":"Vậy mau đi thôi!"},{"n":9,"start":24.519999999999996,"end":28.149999999999995,"parts":[{"zh":"等等，你的钱包在桌子上，别忘了！"}],"pinyin":"Děngdeng, nǐ de qiánbāo zài zhuōzi shang, bié wàngle!","vi":"Khoan đã, ví của bạn trên bàn kìa, đừng quên!"},{"n":10,"start":28.149999999999995,"end":32.17999999999999,"parts":[{"zh":"谢谢！走，我们先去上边儿的书店。"}],"pinyin":"Xièxie! Zǒu, wǒmen xiān qù shàngbiānr de shūdiàn.","vi":"Cảm ơn! Đi thôi, mình lên nhà sách ở tầng trên trước."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-12';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-12', 0, '[{"n":1,"start":0,"end":2.8,"parts":[{"zh":"请问，车站在这边吗？"}],"pinyin":"Qǐngwèn, chēzhàn zài zhè biān ma?","vi":"Cho hỏi, bến xe ở phía này phải không?"},{"n":2,"start":2.8,"end":6.699999999999999,"parts":[{"zh":"不是，车站在东边，饭店的旁边。"}],"pinyin":"Bú shì, chēzhàn zài dōngbiān, fàndiàn de pángbiān.","vi":"Không phải đâu, bến xe ở phía đông, cạnh khách sạn."},{"n":3,"start":6.699999999999999,"end":9.03,"parts":[{"zh":"那银行在哪儿？"}],"pinyin":"Nà yínháng zài nǎr?","vi":"Vậy ngân hàng ở đâu?"},{"n":4,"start":9.03,"end":12.059999999999999,"parts":[{"zh":"银行在饭店的西边。"}],"pinyin":"Yínháng zài fàndiàn de xībiān.","vi":"Ngân hàng ở phía tây của khách sạn."},{"n":5,"start":12.059999999999999,"end":14.729999999999999,"parts":[{"zh":"楼上是什么？楼下呢？"}],"pinyin":"Lóushàng shì shénme? Lóuxià ne?","vi":"Tầng trên là gì vậy? Tầng dưới thì sao?"},{"n":6,"start":14.729999999999999,"end":18.479999999999997,"parts":[{"zh":"楼上是教室，楼下是图书馆。"}],"pinyin":"Lóushàng shì jiàoshì, lóuxià shì túshūguǎn.","vi":"Tầng trên là phòng học, tầng dưới là thư viện."},{"n":7,"start":18.479999999999997,"end":22.559999999999995,"parts":[{"zh":"桌子里边有个杯子，杯子后边有个书包。"}],"pinyin":"Zhuōzi lǐbian yǒu ge bēizi, bēizi hòubiān yǒu ge shūbāo.","vi":"Trong bàn có một cái cốc, sau cái cốc có một cái cặp."},{"n":8,"start":22.559999999999995,"end":26.939999999999994,"parts":[{"zh":"你的左边是学校，右边是医院，明白了？"}],"pinyin":"Nǐ de zuǒbiān shì xuéxiào, yòubiān shì yīyuàn, míngbai le?","vi":"Bên trái bạn là trường, bên phải là bệnh viện, hiểu chưa?"},{"n":9,"start":26.939999999999994,"end":30.769999999999996,"parts":[{"zh":"明白了！中间的那个大房子是什么？"}],"pinyin":"Míngbai le! Zhōngjiān de nà ge dà fángzi shì shénme?","vi":"Rồi! Ngôi nhà to ở giữa là gì vậy?"},{"n":10,"start":30.769999999999996,"end":35.44,"parts":[{"zh":"那是学校，从北边走路来，五分钟就到了。"}],"pinyin":"Nà shì xuéxiào, cóng běibiān zǒulù lái, wǔ fēnzhōng jiù dào le.","vi":"Đó là trường, đi bộ từ phía bắc, năm phút là đến."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-13';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-13', 0, '[{"n":1,"start":0,"end":3.15,"parts":[{"zh":"你们好！请进来，请进来！"}],"pinyin":"Nǐmen hǎo! Qǐng jìnlái, qǐng jìnlái!","vi":"Chào các bạn! Mời vào, mời vào!"},{"n":2,"start":3.15,"end":6.1,"parts":[{"zh":"谢谢！你的房子真大。"}],"pinyin":"Xièxie! Nǐ de fángzi zhēn dà.","vi":"Cảm ơn! Nhà bạn rộng thật."},{"n":3,"start":6.1,"end":9.2,"parts":[{"zh":"这是我的房间，门在门口。"}],"pinyin":"Zhè shì wǒ de fángjiān, mén zài ménkǒu.","vi":"Đây là phòng của tôi, cửa ở ngay cửa vào."},{"n":4,"start":9.2,"end":12.049999999999999,"parts":[{"zh":"你的书都放在哪儿？"}],"pinyin":"Nǐ de shū dōu fàng zài nǎr?","vi":"Sách của bạn để ở đâu hết vậy?"},{"n":5,"start":12.049999999999999,"end":16.38,"parts":[{"zh":"书在楼上，本子在桌子上，书包在地上。"}],"pinyin":"Shū zài lóushàng, běnzi zài zhuōzi shang, shūbāo zài dìshang.","vi":"Sách ở tầng trên, vở trên bàn, cặp sách dưới đất."},{"n":6,"start":16.38,"end":19.93,"parts":[{"zh":"我们走吧，飞机票在身上吗？"}],"pinyin":"Wǒmen zǒu ba, fēijīpiào zài shēnshang ma?","vi":"Mình đi thôi, vé máy bay mang theo người chưa?"},{"n":7,"start":19.93,"end":23.05,"parts":[{"zh":"在身上。机场离这儿远吗？"}],"pinyin":"Zài shēnshang. Jīchǎng lí zhèr yuǎn ma?","vi":"Rồi. Sân bay cách đây xa không?"},{"n":8,"start":23.05,"end":26.3,"parts":[{"zh":"不太远，车站就在楼下。"}],"pinyin":"Bú tài yuǎn, chēzhàn jiù zài lóuxià.","vi":"Không xa lắm, bến xe ngay dưới tầng."},{"n":9,"start":26.3,"end":28.78,"parts":[{"zh":"你住在哪个国家？"}],"pinyin":"Nǐ zhù zài nǎ ge guójiā?","vi":"Bạn sống ở quốc gia nào?"},{"n":10,"start":28.78,"end":32.480000000000004,"parts":[{"zh":"我住在中国，我的家就在这里。"}],"pinyin":"Wǒ zhù zài Zhōngguó, wǒ de jiā jiù zài zhèlǐ.","vi":"Tôi sống ở Trung Quốc, nhà tôi ở ngay đây."},{"n":11,"start":32.480000000000004,"end":36.900000000000006,"parts":[{"zh":"电影院在哪儿？我们出去的时候想看电影。"}],"pinyin":"Diànyǐngyuàn zài nǎr? Wǒmen chūqù de shíhou xiǎng kàn diànyǐng.","vi":"Rạp chiếu phim ở đâu? Lúc đi ra tụi mình muốn xem phim."},{"n":12,"start":36.900000000000006,"end":40.980000000000004,"parts":[{"zh":"从门口出来，往南走就是电影院。"}],"pinyin":"Cóng ménkǒu chūlái, wǎng nán zǒu jiù shì diànyǐngyuàn.","vi":"Ra khỏi cửa, đi về phía nam là tới rạp phim."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-14';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-14', 0, '[{"n":1,"start":0,"end":3.08,"parts":[{"zh":"明天我们去上海，怎么走？"}],"pinyin":"Míngtiān wǒmen qù Shànghǎi, zěnme zǒu?","vi":"Ngày mai chúng ta đi Thượng Hải, đi đường nào?"},{"n":2,"start":3.08,"end":6.25,"parts":[{"zh":"坐火车快，开车太慢了。"}],"pinyin":"Zuò huǒchē kuài, kāichē tài màn le.","vi":"Đi tàu hỏa thì nhanh, lái xe thì chậm quá."},{"n":3,"start":6.25,"end":9,"parts":[{"zh":"对，打车去火车站吧。"}],"pinyin":"Duì, dǎchē qù huǒchēzhàn ba.","vi":"Đúng đó, bắt taxi đến nhà ga nhé."},{"n":4,"start":9,"end":12.05,"parts":[{"zh":"好。上车的钱我来拿。"}],"pinyin":"Hǎo. Shàngchē de qián wǒ lái ná.","vi":"Được. Tiền xe để tôi trả."},{"n":5,"start":12.05,"end":15.57,"parts":[{"zh":"到了！下车吧，我们在这里买票。"}],"pinyin":"Dào le! Xiàchē ba, wǒmen zài zhèlǐ mǎi piào.","vi":"Đến rồi! Xuống xe đi, mình mua vé ở đây."},{"n":6,"start":15.57,"end":19.27,"parts":[{"zh":"两张去上海的票，多少钱？"}],"pinyin":"Liǎng zhāng qù Shànghǎi de piào, duōshao qián?","vi":"Hai vé đi Thượng Hải, bao nhiêu tiền?"},{"n":7,"start":19.27,"end":23.1,"parts":[{"zh":"二百元。飞机票很贵，火车票便宜。"}],"pinyin":"Èrbǎi yuán. Fēijīpiào hěn guì, huǒchēpiào piányi.","vi":"Hai trăm tệ. Vé máy bay đắt lắm, vé tàu thì rẻ."},{"n":8,"start":23.1,"end":24.900000000000002,"parts":[{"zh":"路远吗？"}],"pinyin":"Lù yuǎn ma?","vi":"Đường có xa không?"},{"n":9,"start":24.900000000000002,"end":28.700000000000003,"parts":[{"zh":"有点儿远，可是不飞，走路怎么行？"}],"pinyin":"Yǒudiǎnr yuǎn, kěshì bù fēi, zǒulù zěnme xíng?","vi":"Hơi xa, nhưng không bay được thì đi bộ làm sao nổi?"},{"n":10,"start":28.700000000000003,"end":34.03,"parts":[{"zh":"哈哈，火车跑得快！我们坐汽车再走一段路就到了。"}],"pinyin":"Hāhā, huǒchē pǎo de kuài! Wǒmen zuò qìchē zài zǒu yí duàn lù jiù dào le.","vi":"Haha, tàu chạy nhanh mà! Rồi đi ô tô tiếp một đoạn đường nữa là tới."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-15';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-15', 0, '[{"n":1,"start":0,"end":2.73,"parts":[{"zh":"我饿了，我们去吃饭吧。"}],"pinyin":"Wǒ è le, wǒmen qù chīfàn ba.","vi":"Tôi đói rồi, mình đi ăn cơm nhé."},{"n":2,"start":2.73,"end":5.96,"parts":[{"zh":"好，我想喝一杯茶。你渴吗？"}],"pinyin":"Hǎo, wǒ xiǎng hē yì bēi chá. Nǐ kě ma?","vi":"Được, tôi muốn uống một cốc trà. Bạn có khát không?"},{"n":3,"start":5.96,"end":8.23,"parts":[{"zh":"渴，我要一杯水。"}],"pinyin":"Kě, wǒ yào yì bēi shuǐ.","vi":"Khát lắm, tôi muốn một cốc nước."},{"n":4,"start":8.23,"end":11.98,"parts":[{"zh":"来两杯水，一杯牛奶，两碗米饭。"}],"pinyin":"Lái liǎng bēi shuǐ, yì bēi niúnǎi, liǎng wǎn mǐfàn.","vi":"Cho hai cốc nước, một cốc sữa, hai bát cơm."},{"n":5,"start":11.98,"end":14.23,"parts":[{"zh":"你们有什么菜？"}],"pinyin":"Nǐmen yǒu shénme cài?","vi":"Quán có những món gì vậy?"},{"n":6,"start":14.23,"end":17.71,"parts":[{"zh":"有鸡蛋、肉、面条儿和面包。"}],"pinyin":"Yǒu jīdàn, ròu, miàntiáor hé miànbāo.","vi":"Có trứng, thịt, mì và bánh mì."},{"n":7,"start":17.71,"end":21.79,"parts":[{"zh":"我要鸡蛋和肉，我想这里的菜很好吃。"}],"pinyin":"Wǒ yào jīdàn hé ròu, wǒ xiǎng zhèlǐ de cài hěn hǎochī.","vi":"Tôi muốn trứng và thịt, tôi nghĩ món ở đây rất ngon."},{"n":8,"start":21.79,"end":24.169999999999998,"parts":[{"zh":"早饭吃什么？"}],"pinyin":"Zǎofàn chī shénme?","vi":"Bữa sáng ăn gì?"},{"n":9,"start":24.169999999999998,"end":28.169999999999998,"parts":[{"zh":"早饭我常吃鸡蛋。晚上回家吃晚饭。"}],"pinyin":"Zǎofàn wǒ cháng chī jīdàn. Wǎnshang huí jiā chī wǎnfàn.","vi":"Sáng tôi thường ăn trứng. Tối về nhà ăn cơm."},{"n":10,"start":28.169999999999998,"end":32.199999999999996,"parts":[{"zh":"桌子上有水果，我们坐下，慢慢吃。"}],"pinyin":"Zhuōzi shang yǒu shuǐguǒ, wǒmen zuòxià, mànmàn chī.","vi":"Trên bàn có trái cây, mình ngồi xuống, ăn từ từ nhé."},{"n":11,"start":32.199999999999996,"end":35.12,"parts":[{"zh":"真好吃！我还要一杯茶。"}],"pinyin":"Zhēn hǎochī! Wǒ hái yào yì bēi chá.","vi":"Ngon thật! Tôi còn muốn thêm một cốc trà nữa."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-16';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-16', 0, '[{"n":1,"start":0,"end":2.75,"parts":[{"zh":"你怎么了？你生病了吗？"}],"pinyin":"Nǐ zěnme le? Nǐ shēngbìng le ma?","vi":"Bạn làm sao vậy? Bạn ốm à?"},{"n":2,"start":2.75,"end":6.17,"parts":[{"zh":"是的，我病了，我去医院看病。"}],"pinyin":"Shì de, wǒ bìng le, wǒ qù yīyuàn kànbìng.","vi":"Đúng vậy, tôi ốm rồi, tôi đến bệnh viện khám."},{"n":3,"start":6.17,"end":9.32,"parts":[{"zh":"医生怎么说？你的身体好吗？"}],"pinyin":"Yīshēng zěnme shuō? Nǐ de shēntǐ hǎo ma?","vi":"Bác sĩ nói sao? Sức khỏe của bạn có ổn không?"},{"n":4,"start":9.32,"end":13.49,"parts":[{"zh":"医生说没有大问题，我不用去医院了。"}],"pinyin":"Yīshēng shuō méiyǒu dà wèntí, wǒ búyòng qù yīyuàn le.","vi":"Bác sĩ nói không có vấn đề gì lớn, tôi không cần đến bệnh viện nữa."},{"n":5,"start":13.49,"end":17.04,"parts":[{"zh":"太好了！我很高兴！你的手怎么样？"}],"pinyin":"Tài hǎo le! Wǒ hěn gāoxìng! Nǐ de shǒu zěnmeyàng?","vi":"Tốt quá! Tôi rất vui! Cái tay của bạn thế nào rồi?"},{"n":6,"start":17.04,"end":20.939999999999998,"parts":[{"zh":"好多了。洗手的时候有一点儿疼。"}],"pinyin":"Hǎo duō le. Xǐshǒu de shíhou yǒu yìdiǎnr téng.","vi":"Khỏe hơn nhiều rồi. Lúc rửa tay còn hơi đau một chút."},{"n":7,"start":20.939999999999998,"end":23.56,"parts":[{"zh":"医院里有很多病人吗？"}],"pinyin":"Yīyuàn lǐ yǒu hěn duō bìngrén ma?","vi":"Trong bệnh viện có nhiều bệnh nhân không?"},{"n":8,"start":23.56,"end":27.84,"parts":[{"zh":"很多。有的病人生气了，有的病人在笑。"}],"pinyin":"Hěn duō. Yǒu de bìngrén shēngqì le, yǒu de bìngrén zài xiào.","vi":"Nhiều lắm. Có bệnh nhân thì đang giận, có người đang cười."},{"n":9,"start":27.84,"end":30.29,"parts":[{"zh":"你的爱好是什么？"}],"pinyin":"Nǐ de àihào shì shénme?","vi":"Sở thích của bạn là gì?"},{"n":10,"start":30.29,"end":34.24,"parts":[{"zh":"我的爱好是唱歌，唱歌让我高兴。"}],"pinyin":"Wǒ de àihào shì chànggē, chànggē ràng wǒ gāoxìng.","vi":"Sở thích của tôi là hát, hát khiến tôi vui."},{"n":11,"start":34.24,"end":38.04,"parts":[{"zh":"我知道洗手间在哪儿，我们一起去吧。"}],"pinyin":"Wǒ zhīdào xǐshǒujiān zài nǎr, wǒmen yìqǐ qù ba.","vi":"Tôi biết nhà vệ sinh ở đâu, mình cùng đi nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-17';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-17', 0, '[{"n":1,"start":0,"end":2.48,"parts":[{"zh":"今天天气真好！"}],"pinyin":"Jīntiān tiānqì zhēn hǎo!","vi":"Thời tiết hôm nay đẹp thật!"},{"n":2,"start":2.48,"end":5.779999999999999,"parts":[{"zh":"是啊，天上有太阳，没有雨。"}],"pinyin":"Shì a, tiānshang yǒu tàiyáng, méiyǒu yǔ.","vi":"Ừ mà, trời có nắng, không có mưa."},{"n":3,"start":5.779999999999999,"end":8.879999999999999,"parts":[{"zh":"昨天下午下雨了，风很大。"}],"pinyin":"Zuótiān xiàwǔ xià yǔ le, fēng hěn dà.","vi":"Chiều qua trời mưa, gió rất lớn."},{"n":4,"start":8.879999999999999,"end":11.709999999999999,"parts":[{"zh":"明天会不会下雨？"}],"pinyin":"Míngtiān huì bú huì xià yǔ?","vi":"Mai có mưa không nhỉ?"},{"n":5,"start":11.709999999999999,"end":14.91,"parts":[{"zh":"我希望明天还是好天气。"}],"pinyin":"Wǒ xīwàng míngtiān háishì hǎo tiānqì.","vi":"Tôi hy vọng mai vẫn là thời tiết đẹp."},{"n":6,"start":14.91,"end":18.740000000000002,"parts":[{"zh":"我们去公园玩儿吧，那里很好玩儿！"}],"pinyin":"Wǒmen qù gōngyuán wánr ba, nàlǐ hěn hǎowánr!","vi":"Mình đi công viên chơi nhé, ở đó vui lắm!"},{"n":7,"start":18.740000000000002,"end":22.860000000000003,"parts":[{"zh":"好！我妈妈说，认真读书，也要认真玩儿。"}],"pinyin":"Hǎo! Wǒ māma shuō, rènzhēn dúshū, yě yào rènzhēn wánr.","vi":"Hay đấy! Mẹ tôi nói, học nghiêm túc mà chơi cũng phải chơi nghiêm túc."},{"n":8,"start":22.860000000000003,"end":26.190000000000005,"parts":[{"zh":"你看那座山，真高真白！"}],"pinyin":"Nǐ kàn nà zuò shān, zhēn gāo zhēn bái!","vi":"Bạn nhìn ngọn núi kia kìa, cao và trắng thật!"},{"n":9,"start":26.190000000000005,"end":30.570000000000004,"parts":[{"zh":"那是雪。山上的树很小，山下的树很大。"}],"pinyin":"Nà shì xuě. Shānshang de shù hěn xiǎo, shānxià de shù hěn dà.","vi":"Đó là tuyết. Cây trên núi nhỏ lắm, cây dưới núi thì to."},{"n":10,"start":30.570000000000004,"end":34.800000000000004,"parts":[{"zh":"这棵老树真好看！快点走，别太慢了！"}],"pinyin":"Zhè kē lǎo shù zhēn hǎokàn! Kuàidiǎn zǒu, bié tài màn le!","vi":"Cây già này đẹp thật! Đi nhanh lên, đừng chậm thế!"},{"n":11,"start":34.800000000000004,"end":37.970000000000006,"parts":[{"zh":"我的新鞋太大了，我走得慢。"}],"pinyin":"Wǒ de xīn xié tài dà le, wǒ zǒu de màn.","vi":"Đôi giày mới của tôi rộng quá nên tôi đi chậm."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-18';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-18', 0, '[{"n":1,"start":0,"end":3.23,"parts":[{"zh":"这个杯子真好看！多少钱？"}],"pinyin":"Zhège bēizi zhēn hǎokàn! Duōshao qián?","vi":"Cái cốc này xinh thật! Bao nhiêu tiền?"},{"n":2,"start":3.23,"end":5.8100000000000005,"parts":[{"zh":"一百块，太贵了！"}],"pinyin":"Yìbǎi kuài, tài guì le!","vi":"Một trăm tệ, đắt quá!"},{"n":3,"start":5.8100000000000005,"end":8.89,"parts":[{"zh":"真的太贵了。那个新杯子呢？"}],"pinyin":"Zhēn de tài guì le. Nàge xīn bēizi ne?","vi":"Đắt thật đấy. Cái cốc mới kia thì sao?"},{"n":4,"start":8.89,"end":12.06,"parts":[{"zh":"那个很难看，还不好用。"}],"pinyin":"Nàge hěn nánkàn, hái bù hǎo yòng.","vi":"Cái kia xấu lắm, mà dùng cũng không tiện."},{"n":5,"start":12.06,"end":14.64,"parts":[{"zh":"你看，这两个一样吗？"}],"pinyin":"Nǐ kàn, zhè liǎng ge yíyàng ma?","vi":"Bạn xem, hai cái này giống nhau không?"},{"n":6,"start":14.64,"end":18.69,"parts":[{"zh":"不一样，一个大，一个小，一个重，一个轻。"}],"pinyin":"Bù yíyàng, yí ge dà, yí ge xiǎo, yí ge zhòng, yí ge qīng.","vi":"Không giống, một cái to một cái nhỏ, một cái nặng một cái nhẹ."},{"n":7,"start":18.69,"end":22.11,"parts":[{"zh":"今天真冷，明天会不会很热？"}],"pinyin":"Jīntiān zhēn lěng, míngtiān huì bú huì hěn rè?","vi":"Hôm nay lạnh thật, mai có nóng lắm không?"},{"n":8,"start":22.11,"end":24.91,"parts":[{"zh":"明天热，后天更热。"}],"pinyin":"Míngtiān rè, hòutiān gèng rè.","vi":"Mai nóng, mốt còn nóng hơn."},{"n":9,"start":24.91,"end":27.53,"parts":[{"zh":"你的答案对了没有？"}],"pinyin":"Nǐ de dá''àn duì le méiyǒu?","vi":"Câu trả lời của bạn đúng chưa?"},{"n":10,"start":27.53,"end":30.450000000000003,"parts":[{"zh":"对了。老师说我最棒！"}],"pinyin":"Duì le. Lǎoshī shuō wǒ zuì bàng!","vi":"Đúng rồi. Thầy cô nói tôi là giỏi nhất!"},{"n":11,"start":30.450000000000003,"end":33.7,"parts":[{"zh":"真棒！我答错了，我很不高兴。"}],"pinyin":"Zhēn bàng! Wǒ dácuò le, wǒ hěn bù gāoxìng.","vi":"Giỏi thật! Tôi trả lời sai, tôi không vui chút nào."},{"n":12,"start":33.7,"end":38.150000000000006,"parts":[{"zh":"没关系，你的成绩不差，真的非常不错！"}],"pinyin":"Méi guānxi, nǐ de chéngjì bú chà, zhēn de fēicháng búcuò!","vi":"Không sao, kết quả của bạn không tệ, thật sự rất ổn!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-19';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-19', 0, '[{"n":1,"start":0,"end":3.3,"parts":[{"zh":"今天晚上我们去看电影吧！"}],"pinyin":"Jīntiān wǎnshang wǒmen qù kàn diànyǐng ba!","vi":"Tối nay mình đi xem phim nhé!"},{"n":2,"start":3.3,"end":5.73,"parts":[{"zh":"好！什么电影？"}],"pinyin":"Hǎo! Shénme diànyǐng?","vi":"Được! Phim gì vậy?"},{"n":3,"start":5.73,"end":8.96,"parts":[{"zh":"一部新的中国电影，很有名。"}],"pinyin":"Yí bù xīn de Zhōngguó diànyǐng, hěn yǒumíng.","vi":"Một bộ phim Trung Quốc mới, nổi tiếng lắm."},{"n":4,"start":8.96,"end":12.06,"parts":[{"zh":"我看过了，我第二次看。"}],"pinyin":"Wǒ kànguò le, wǒ dì-èr cì kàn.","vi":"Tôi xem rồi, đây là lần thứ hai tôi xem."},{"n":5,"start":12.06,"end":14.64,"parts":[{"zh":"你在哪儿看见它的？"}],"pinyin":"Nǐ zài nǎr kànjiàn tā de?","vi":"Bạn xem nó ở đâu vậy?"},{"n":6,"start":14.64,"end":19.19,"parts":[{"zh":"我看到了电影的信息，马上就去买了票。"}],"pinyin":"Wǒ kàndào le diànyǐng de xìnxī, mǎshàng jiù qù mǎi le piào.","vi":"Tôi thấy thông tin phim, liền đi mua vé ngay."},{"n":7,"start":19.19,"end":22.11,"parts":[{"zh":"我们唱歌还是看电影？"}],"pinyin":"Wǒmen chànggē háishì kàn diànyǐng?","vi":"Mình hát hay xem phim đây?"},{"n":8,"start":22.11,"end":26.03,"parts":[{"zh":"先看电影，回家的时候再唱歌。"}],"pinyin":"Xiān kàn diànyǐng, huíjiā de shíhou zài chànggē.","vi":"Xem phim trước, về nhà thì hát sau."},{"n":9,"start":26.03,"end":29.700000000000003,"parts":[{"zh":"去山上的路上，我听到了一首歌。"}],"pinyin":"Qù shānshang de lùshang, wǒ tīngdào le yì shǒu gē.","vi":"Trên đường lên núi, tôi nghe được một bài hát."},{"n":10,"start":29.700000000000003,"end":34.25,"parts":[{"zh":"好好听！树上有很多鸟，地上有很多花。"}],"pinyin":"Hǎo hǎotīng! Shùshang yǒu hěn duō niǎo, dìshang yǒu hěn duō huā.","vi":"Hay thật! Trên cây có nhiều chim, dưới đất có nhiều hoa."},{"n":11,"start":34.25,"end":37.15,"parts":[{"zh":"这个国家的地方真美！"}],"pinyin":"Zhège guójiā de dìfang zhēn měi!","vi":"Đất nước này cảnh đẹp thật!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-20';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-20', 0, '[{"n":1,"start":0,"end":2.1,"parts":[{"zh":"你会打球吗？"}],"pinyin":"Nǐ huì dǎqiú ma?","vi":"Bạn chơi bóng được không?"},{"n":2,"start":2.1,"end":5.93,"parts":[{"zh":"会，我常常和朋友们一起打球。"}],"pinyin":"Huì, wǒ chángcháng hé péngyǒumen yìqǐ dǎqiú.","vi":"Được chứ, tôi thường chơi bóng cùng bạn bè."},{"n":3,"start":5.93,"end":9.16,"parts":[{"zh":"很好！我也是。我们一块儿去吧！"}],"pinyin":"Hěn hǎo! Wǒ yě shì. Wǒmen yíkuàir qù ba!","vi":"Tốt lắm! Tôi cũng vậy. Mình cùng đi thôi!"},{"n":4,"start":9.16,"end":11.780000000000001,"parts":[{"zh":"好，还是老地方。"}],"pinyin":"Hǎo, háishì lǎo dìfang.","vi":"Được, vẫn chỗ cũ nhé."},{"n":5,"start":11.780000000000001,"end":14.88,"parts":[{"zh":"先做运动，然后再吃饭。"}],"pinyin":"Xiān zuò yùndòng, ránhòu zài chīfàn.","vi":"Tập thể dục trước, rồi mới ăn cơm sau."},{"n":6,"start":14.88,"end":17.650000000000002,"parts":[{"zh":"今天你们都很忙吗？"}],"pinyin":"Jīntiān nǐmen dōu hěn máng ma?","vi":"Hôm nay các bạn đều bận à?"},{"n":7,"start":17.650000000000002,"end":21.07,"parts":[{"zh":"大家都想玩儿球，都很高兴。"}],"pinyin":"Dàjiā dōu xiǎng wánr qiú, dōu hěn gāoxìng.","vi":"Ai cũng muốn chơi bóng, ai cũng vui."},{"n":8,"start":21.07,"end":24.62,"parts":[{"zh":"我一边听音乐，一边走路来。"}],"pinyin":"Wǒ yìbiān tīng yīnyuè, yìbiān zǒulù lái.","vi":"Tôi vừa nghe nhạc vừa đi bộ đến đây."},{"n":9,"start":24.62,"end":26.92,"parts":[{"zh":"你走得很快！"}],"pinyin":"Nǐ zǒu de hěn kuài!","vi":"Bạn đi nhanh thật đấy!"},{"n":10,"start":26.92,"end":31.220000000000002,"parts":[{"zh":"是的，因为我还有事，我得早点儿回家。"}],"pinyin":"Shì de, yīnwèi wǒ hái yǒu shì, wǒ děi zǎodiǎnr huí jiā.","vi":"Đúng vậy, vì tôi còn việc, phải về nhà sớm một chút."},{"n":11,"start":31.220000000000002,"end":34.67,"parts":[{"zh":"没问题，就一会儿，马上就完了。"}],"pinyin":"Méi wèntí, jiù yíhuìr, mǎshàng jiù wán le.","vi":"Không sao đâu, chỉ một lát thôi, xong ngay mà."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-21';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-21', 0, '[{"n":1,"start":0,"end":2.2,"parts":[{"zh":"你会说中文吗？"}],"pinyin":"Nǐ huì shuō Zhōngwén ma?","vi":"Bạn nói được tiếng Trung không?"},{"n":2,"start":2.2,"end":5.550000000000001,"parts":[{"zh":"会说一点儿，我说得不好。"}],"pinyin":"Huì shuō yìdiǎnr, wǒ shuō de bù hǎo.","vi":"Nói được một chút, tôi nói chưa tốt."},{"n":3,"start":5.550000000000001,"end":8.47,"parts":[{"zh":"你想学吗？我可以教你。"}],"pinyin":"Nǐ xiǎng xué ma? Wǒ kěyǐ jiāo nǐ.","vi":"Bạn có muốn học không? Tôi có thể dạy bạn."},{"n":4,"start":8.47,"end":12.120000000000001,"parts":[{"zh":"太好了！给这本书，是给你的。"}],"pinyin":"Tài hǎo le! Gěi zhè běn shū, shì gěi nǐ de.","vi":"Tốt quá! Cầm cuốn sách này, là tặng bạn đấy."},{"n":5,"start":12.120000000000001,"end":15.240000000000002,"parts":[{"zh":"谢谢！这本书非常有用。"}],"pinyin":"Xièxie! Zhè běn shū fēicháng yǒuyòng.","vi":"Cảm ơn! Cuốn sách này rất hữu ích."},{"n":6,"start":15.240000000000002,"end":18.360000000000003,"parts":[{"zh":"你要怎么学？每天学吗？"}],"pinyin":"Nǐ yào zěnme xué? Měitiān xué ma?","vi":"Bạn định học thế nào? Học mỗi ngày à?"},{"n":7,"start":18.360000000000003,"end":22.440000000000005,"parts":[{"zh":"对，正学着呢。可是不知道为什么很难。"}],"pinyin":"Duì, zhèng xuézhe ne. Kěshì bù zhīdào wèishénme hěn nán.","vi":"Đúng rồi, đang học đây. Nhưng không biết sao nó khó quá."},{"n":8,"start":22.440000000000005,"end":26.940000000000005,"parts":[{"zh":"别担心！没有不会的学生，只有不会的老师。"}],"pinyin":"Bié dānxīn! Méiyǒu bú huì de xuésheng, zhǐyǒu bú huì de lǎoshī.","vi":"Đừng lo! Không có học sinh dốt, chỉ có thầy cô dạy dốt."},{"n":9,"start":26.940000000000005,"end":31.190000000000005,"parts":[{"zh":"哈哈，你真会说话！我是不是有很多问题？"}],"pinyin":"Hāhā, nǐ zhēn huì shuōhuà! Wǒ shì bú shì yǒu hěn duō wèntí?","vi":"Haha, bạn nói hay thật! Chắc tôi hỏi nhiều câu lắm nhỉ?"},{"n":10,"start":31.190000000000005,"end":34.07000000000001,"parts":[{"zh":"不多，还有别的问题吗？"}],"pinyin":"Bù duō, hái yǒu bié de wèntí ma?","vi":"Không nhiều đâu, còn câu hỏi nào nữa không?"},{"n":11,"start":34.07000000000001,"end":37.24000000000001,"parts":[{"zh":"没有了。我们喝着茶，慢慢说。"}],"pinyin":"Méiyǒu le. Wǒmen hēzhe chá, mànmàn shuō.","vi":"Hết rồi rồi. Mình vừa uống trà vừa nói chuyện từ từ nhé."},{"n":12,"start":37.24000000000001,"end":41.790000000000006,"parts":[{"zh":"好，从今天开始，我每天教你一个小时。"}],"pinyin":"Hǎo, cóng jīntiān kāishǐ, wǒ měitiān jiāo nǐ yí ge xiǎoshí.","vi":"Được, từ hôm nay, mỗi ngày tôi dạy bạn một tiếng."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-22';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-22', 0, '[{"n":1,"start":0,"end":3,"parts":[{"zh":"外面很冷，快把门关上！"}],"pinyin":"Wàimiàn hěn lěng, kuài bǎ mén guānshang!","vi":"Ngoài trời lạnh lắm, mau đóng cửa lại đi!"},{"n":2,"start":3,"end":5.83,"parts":[{"zh":"好。把窗户打开吗？"}],"pinyin":"Hǎo. Bǎ chuānghu dǎkāi ma?","vi":"Rồi. Có mở cửa sổ không?"},{"n":3,"start":5.83,"end":8.98,"parts":[{"zh":"不要，太冷了。请帮我一个忙。"}],"pinyin":"Bú yào, tài lěng le. Qǐng bāng wǒ yí ge máng.","vi":"Đừng, lạnh lắm. Giúp tôi một việc nhé."},{"n":4,"start":8.98,"end":11.9,"parts":[{"zh":"什么事？你说，我帮忙。"}],"pinyin":"Shénme shì? Nǐ shuō, wǒ bāngmáng.","vi":"Việc gì vậy? Bạn cứ nói, tôi giúp."},{"n":5,"start":11.9,"end":15.13,"parts":[{"zh":"请把我的衣服放回房间里。"}],"pinyin":"Qǐng bǎ wǒ de yīfu fàng huí fángjiān lǐ.","vi":"Hãy cầm quần áo của tôi đặt lại vào phòng giúp tôi."},{"n":6,"start":15.13,"end":17.330000000000002,"parts":[{"zh":"行，没问题。"}],"pinyin":"Xíng, méi wèntí.","vi":"Được, không sao."},{"n":7,"start":17.330000000000002,"end":20.1,"parts":[{"zh":"谢谢！你现在回去吗？"}],"pinyin":"Xièxie! Nǐ xiànzài huíqù ma?","vi":"Cảm ơn! Bây giờ bạn quay về à?"},{"n":8,"start":20.1,"end":23.200000000000003,"parts":[{"zh":"是的，我得回家了。再见！"}],"pinyin":"Shì de, wǒ děi huí jiā le. Zàijiàn!","vi":"Vâng, tôi phải về nhà rồi. Tạm biệt!"},{"n":9,"start":23.200000000000003,"end":26.500000000000004,"parts":[{"zh":"路上小心！到了给我打电话。"}],"pinyin":"Lùshang xiǎoxīn! Dào le gěi wǒ dǎ diànhuà.","vi":"Đi đường cẩn thận nhé! Đến nơi thì gọi điện cho tôi."},{"n":10,"start":26.500000000000004,"end":29.42,"parts":[{"zh":"好，我到家就打给你。"}],"pinyin":"Hǎo, wǒ dào jiā jiù dǎ gěi nǐ.","vi":"Được, về đến nhà tôi sẽ gọi cho bạn."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-23';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-23', 0, '[{"n":1,"start":0,"end":2.98,"parts":[{"zh":"早上好！你几点起床？"}],"pinyin":"Zǎoshang hǎo! Nǐ jǐ diǎn qǐchuáng?","vi":"Chào buổi sáng! Bạn mấy giờ dậy?"},{"n":2,"start":2.98,"end":6.83,"parts":[{"zh":"我六点起床，然后去找早饭。"}],"pinyin":"Wǒ liù diǎn qǐchuáng, ránhòu qù zhǎo zǎofàn.","vi":"Tôi sáu giờ dậy, rồi đi tìm đồ ăn sáng."},{"n":3,"start":6.83,"end":9.16,"parts":[{"zh":"你今天去哪儿？"}],"pinyin":"Nǐ jīntiān qù nǎr?","vi":"Hôm nay bạn đi đâu?"},{"n":4,"start":9.16,"end":12.14,"parts":[{"zh":"我回去学校，有课。"}],"pinyin":"Wǒ huíqù xuéxiào, yǒu kè.","vi":"Tôi quay lại trường, có tiết học."},{"n":5,"start":12.14,"end":15.14,"parts":[{"zh":"用我的书吧，非常有用。"}],"pinyin":"Yòng wǒ de shū ba, fēicháng yǒuyòng.","vi":"Dùng sách của tôi đi, rất hữu ích đấy."},{"n":6,"start":15.14,"end":17.740000000000002,"parts":[{"zh":"谢谢！找到它了！"}],"pinyin":"Xièxie! Zhǎodào tā le!","vi":"Cảm ơn! Tôi tìm thấy nó rồi!"},{"n":7,"start":17.740000000000002,"end":20.14,"parts":[{"zh":"你晚上做什么？"}],"pinyin":"Nǐ wǎnshang zuò shénme?","vi":"Buổi tối bạn làm gì?"},{"n":8,"start":20.14,"end":23.91,"parts":[{"zh":"睡觉以前看书，十一点睡觉。"}],"pinyin":"Shuìjiào yǐqián kànshū, shíyī diǎn shuìjiào.","vi":"Trước khi ngủ thì đọc sách, mười một giờ đi ngủ."},{"n":9,"start":23.91,"end":27.54,"parts":[{"zh":"真有规律！你的生活很有名吗？哈哈！"}],"pinyin":"Zhēn yǒu guīlǜ! Nǐ de shēnghuó hěn yǒumíng ma? Hāhā!","vi":"Đều đặn thật! Cuộc sống của bạn có nổi tiếng không? Haha!"},{"n":10,"start":27.54,"end":30.81,"parts":[{"zh":"别笑话我！我等你的答案。"}],"pinyin":"Bié xiàohua wǒ! Wǒ děng nǐ de dá''àn.","vi":"Đừng chọc tôi! Tôi đang chờ câu trả lời của bạn đấy."},{"n":11,"start":30.81,"end":32.98,"parts":[{"zh":"好了，我们来吧！"}],"pinyin":"Hǎo le, wǒmen lái ba!","vi":"Xong rồi, mình bắt đầu nhé!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-24';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-24', 0, '[{"n":1,"start":0,"end":2.3,"parts":[{"zh":"你好，我认识你吗？"}],"pinyin":"Nǐ hǎo, wǒ rènshi nǐ ma?","vi":"Chào bạn, tôi quen bạn nhỉ?"},{"n":2,"start":2.3,"end":5.6,"parts":[{"zh":"认识！上次我们见过面。"}],"pinyin":"Rènshi! Shàng cì wǒmen jiànguò miàn.","vi":"Quen chứ! Lần trước chúng ta đã gặp nhau rồi."},{"n":3,"start":5.6,"end":8.77,"parts":[{"zh":"啊，想起来了！你最近怎么样？"}],"pinyin":"A, xiǎng qǐlái le! Nǐ zuìjìn zěnmeyàng?","vi":"À, nhớ ra rồi! Dạo này bạn thế nào?"},{"n":4,"start":8.77,"end":12.57,"parts":[{"zh":"挺好的。我告诉你一个好消息。"}],"pinyin":"Tǐng hǎo de. Wǒ gàosu nǐ yí ge hǎo xiāoxi.","vi":"Vẫn tốt. Tôi báo cho bạn một tin vui nhé."},{"n":5,"start":12.57,"end":14.84,"parts":[{"zh":"什么事？请说！"}],"pinyin":"Shénme shì? Qǐng shuō!","vi":"Việc gì vậy? Bạn nói đi!"},{"n":6,"start":14.84,"end":18.509999999999998,"parts":[{"zh":"我考试最好，我妈妈很高兴。"}],"pinyin":"Wǒ kǎoshì zuì hǎo, wǒ māma hěn gāoxìng.","vi":"Tôi thi tốt nhất, mẹ tôi rất vui."},{"n":7,"start":18.509999999999998,"end":21.68,"parts":[{"zh":"真棒！你的朋友们也考得好吗？"}],"pinyin":"Zhēn bàng! Nǐ de péngyǒumen yě kǎo de hǎo ma?","vi":"Giỏi thật! Bạn bè của bạn cũng thi tốt không?"},{"n":8,"start":21.68,"end":25.08,"parts":[{"zh":"别人都很好，没有人觉得难。"}],"pinyin":"Biérén dōu hěn hǎo, méiyǒu rén juéde nán.","vi":"Mọi người đều làm tốt cả, không ai thấy khó cả."},{"n":9,"start":25.08,"end":27.659999999999997,"parts":[{"zh":"我问你一个问题，好吗？"}],"pinyin":"Wǒ wèn nǐ yí ge wèntí, hǎo ma?","vi":"Tôi hỏi bạn một câu nhé?"},{"n":10,"start":27.659999999999997,"end":31.109999999999996,"parts":[{"zh":"问吧，我明白的话就回答你。"}],"pinyin":"Wèn ba, wǒ míngbai de huà jiù huídá nǐ.","vi":"Hỏi đi, nếu tôi hiểu thì tôi sẽ trả lời."},{"n":11,"start":31.109999999999996,"end":34.809999999999995,"parts":[{"zh":"没关系，你不用回答。都是小事。"}],"pinyin":"Méi guānxi, nǐ búyòng huídá. Dōu shì xiǎoshì.","vi":"Không sao đâu, bạn không cần trả lời. Chỉ là chuyện nhỏ thôi."},{"n":12,"start":34.809999999999995,"end":38.85999999999999,"parts":[{"zh":"谢谢你的好意，朋友们都说我很好。"}],"pinyin":"Xièxie nǐ de hǎoyì, péngyǒumen dōu shuō wǒ hěn hǎo.","vi":"Cảm ơn tấm lòng của bạn, bạn bè ai cũng nói tôi dễ mến."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-25';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-25', 0, '[{"n":1,"start":0,"end":2.38,"parts":[{"zh":"你今年多大了？"}],"pinyin":"Nǐ jīnnián duō dà le?","vi":"Năm nay bạn bao nhiêu tuổi rồi?"},{"n":2,"start":2.38,"end":4.8100000000000005,"parts":[{"zh":"我二十岁。你呢？"}],"pinyin":"Wǒ èrshí suì. Nǐ ne?","vi":"Tôi hai mươi tuổi. Còn bạn?"},{"n":3,"start":4.8100000000000005,"end":7.760000000000001,"parts":[{"zh":"我比你大一岁，我二十一。"}],"pinyin":"Wǒ bǐ nǐ dà yí suì, wǒ èrshíyī.","vi":"Tôi hơn bạn một tuổi, tôi hai mươi một."},{"n":4,"start":7.760000000000001,"end":11.59,"parts":[{"zh":"白天你在学校学习几个小时？"}],"pinyin":"Báitiān nǐ zài xuéxiào xuéxí jǐ ge xiǎoshí?","vi":"Ban ngày bạn học mấy tiếng ở trường?"},{"n":5,"start":11.59,"end":15.620000000000001,"parts":[{"zh":"大概六个小时，有时候多，有时候少。"}],"pinyin":"Dàgài liù ge xiǎoshí, yǒushíhou duō, yǒushíhou shǎo.","vi":"Khoảng sáu tiếng, lúc thì nhiều, lúc thì ít."},{"n":6,"start":15.620000000000001,"end":19.79,"parts":[{"zh":"每天学那么久！你最好休息一下儿。"}],"pinyin":"Měitiān xué nàme jiǔ! Nǐ zuì hǎo xiūxi yíxiàr.","vi":"Mỗi ngày học lâu thế! Tốt nhất bạn nên nghỉ ngơi một chút."},{"n":7,"start":19.79,"end":23.99,"parts":[{"zh":"你说得对，我上学期就是这样累病的。"}],"pinyin":"Nǐ shuō de duì, wǒ shàngxuéqī jiù shì zhèyàng lèi bìng de.","vi":"Bạn nói đúng, học kỳ trước tôi đã mệt bệnh như thế đấy."},{"n":8,"start":23.99,"end":28.32,"parts":[{"zh":"今天几号？我们下次考试是什么时候？"}],"pinyin":"Jīntiān jǐ hào? Wǒmen xià cì kǎoshì shì shénme shíhou?","vi":"Hôm nay ngày mấy? Lần thi tới của chúng ta là khi nào?"},{"n":9,"start":28.32,"end":31.97,"parts":[{"zh":"今天是八号，考试在下星期一。"}],"pinyin":"Jīntiān shì bā hào, kǎoshì zài xià xīngqīyī.","vi":"Hôm nay là ngày mùng tám, thi vào thứ Hai tuần sau."},{"n":10,"start":31.97,"end":36.44,"parts":[{"zh":"最后，别忘了带笔！上次的笔忘在我家了。"}],"pinyin":"Zuìhòu, bié wàngle dài bǐ! Shàng cì de bǐ wàng zài wǒ jiā le.","vi":"Cuối cùng, đừng quên mang bút nhé! Cái bút lần trước bạn để quên ở nhà tôi."},{"n":11,"start":36.44,"end":39.71,"parts":[{"zh":"我记住了，这次一定不忘记。"}],"pinyin":"Wǒ jìzhù le, zhè cì yídìng bú wàngjì.","vi":"Tôi nhớ rồi, lần này nhất định không quên."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-26';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-26', 0, '[{"n":1,"start":0,"end":2.4,"parts":[{"zh":"你喜欢学汉语吗？"}],"pinyin":"Nǐ xǐhuan xué Hànyǔ ma?","vi":"Bạn có thích học tiếng Trung không?"},{"n":2,"start":2.4,"end":5.23,"parts":[{"zh":"喜欢！汉语很有意思。"}],"pinyin":"Xǐhuan! Hànyǔ hěn yǒu yìsi.","vi":"Thích chứ! Tiếng Trung rất thú vị."},{"n":3,"start":5.23,"end":8.06,"parts":[{"zh":"今天课上到第几页了？"}],"pinyin":"Jīntiān kè shàng dào dì-jǐ yè le?","vi":"Hôm nay học đến trang thứ mấy rồi?"},{"n":4,"start":8.06,"end":12.11,"parts":[{"zh":"第十页，老师说这篇课文很重要。"}],"pinyin":"Dì-shí yè, lǎoshī shuō zhè piān kèwén hěn zhòngyào.","vi":"Trang mười, thầy giáo nói bài học này rất quan trọng."},{"n":5,"start":12.11,"end":16.53,"parts":[{"zh":"我已经读了两遍。中间有几句话我不会。"}],"pinyin":"Wǒ yǐjīng dú le liǎng biàn. Zhōngjiān yǒu jǐ jù huà wǒ bú huì.","vi":"Tôi đã đọc hai lần rồi. Giữa bài có mấy câu tôi không biết."},{"n":6,"start":16.53,"end":19.61,"parts":[{"zh":"下课以后我教你说。"}],"pinyin":"Xiàkè yǐhòu wǒ jiāo nǐ shuō.","vi":"Sau giờ học tôi dạy bạn nói."},{"n":7,"start":19.61,"end":22.61,"parts":[{"zh":"谢谢！我想去北京看看。"}],"pinyin":"Xièxie! Wǒ xiǎng qù Běijīng kànkan.","vi":"Cảm ơn! Tôi muốn đi Bắc Kinh chơi."},{"n":8,"start":22.61,"end":26.09,"parts":[{"zh":"好啊！我来给你画一张地图。"}],"pinyin":"Hǎo a! Wǒ lái gěi nǐ huà yì zhāng dìtú.","vi":"Hay đấy! Để tôi vẽ cho bạn một tấm bản đồ."},{"n":9,"start":26.09,"end":30.07,"parts":[{"zh":"我还有很多事要做，我的床还没收拾呢。"}],"pinyin":"Wǒ hái yǒu hěn duō shì yào zuò, wǒ de chuáng hái méi shōushi ne.","vi":"Tôi còn nhiều việc phải làm, giường tôi còn chưa dọn nữa."},{"n":10,"start":30.07,"end":33.65,"parts":[{"zh":"别忙了，先去买两个包子吃吧！"}],"pinyin":"Bié máng le, xiān qù mǎi liǎng ge bāozi chī ba!","vi":"Đừng bận nữa, đi mua hai cái bánh bao ăn đã!"},{"n":11,"start":33.65,"end":36.42,"parts":[{"zh":"好主意！包子很好吃。"}],"pinyin":"Hǎo zhǔyi! Bāozi hěn hǎochī.","vi":"Ý hay đấy! Bánh bao ăn rất ngon."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk1/lesson-27';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk1/lesson-27', 0, '[{"n":1,"start":0,"end":2.52,"parts":[{"zh":"你今天请假了吗？"}],"pinyin":"Nǐ jīntiān qǐngjià le ma?","vi":"Hôm nay bạn xin nghỉ phép rồi à?"},{"n":2,"start":2.52,"end":5.79,"parts":[{"zh":"请了，我有很多事要准备。"}],"pinyin":"Qǐng le, wǒ yǒu hěn duō shì yào zhǔnbèi.","vi":"Xin rồi, tôi có nhiều việc phải chuẩn bị."},{"n":3,"start":5.79,"end":7.91,"parts":[{"zh":"你要干什么？"}],"pinyin":"Nǐ yào gàn shénme?","vi":"Bạn định làm gì vậy?"},{"n":4,"start":7.91,"end":11.61,"parts":[{"zh":"爸爸过生日，我要做一顿好饭。"}],"pinyin":"Bàba guò shēngrì, wǒ yào zuò yí dùn hǎofàn.","vi":"Bố tôi sắp sinh nhật, tôi định nấu một bữa cơm ngon."},{"n":5,"start":11.61,"end":14.44,"parts":[{"zh":"让我帮你吧。先买什么？"}],"pinyin":"Ràng wǒ bāng nǐ ba. Xiān mǎi shénme?","vi":"Để tôi giúp bạn. Mua gì trước?"},{"n":6,"start":14.44,"end":18.36,"parts":[{"zh":"买饭和菜，还要少买一点儿水果。"}],"pinyin":"Mǎi fàn hé cài, hái yào shǎo mǎi yìdiǎnr shuǐguǒ.","vi":"Mua cơm và rau, còn cần mua ít trái cây."},{"n":7,"start":18.36,"end":21.66,"parts":[{"zh":"这个动作真快！已经七点了。"}],"pinyin":"Zhège dòngzuò zhēn kuài! Yǐjīng qī diǎn le.","vi":"Vân tay lẹ thật! Đã bảy giờ rồi."},{"n":8,"start":21.66,"end":25.14,"parts":[{"zh":"时间过得真快，我们继续吧。"}],"pinyin":"Shíjiān guò de zhēn kuài, wǒmen jìxù ba.","vi":"Thời gian trôi nhanh thật, mình làm tiếp nhé."},{"n":9,"start":25.14,"end":28.14,"parts":[{"zh":"你的口渴了吧？喝点儿水。"}],"pinyin":"Nǐ de kǒu kě le ba? Hē diǎnr shuǐ.","vi":"Bạn khát rồi phải không? Uống chút nước đi."},{"n":10,"start":28.14,"end":32.52,"parts":[{"zh":"谢谢！对了，这句话怎么说：生日快乐？"}],"pinyin":"Xièxie! Duìle, zhè jù huà zěnme shuō: shēngrì kuàilè?","vi":"Cảm ơn! Này, câu này nói sao nhỉ: chúc mừng sinh nhật?"},{"n":11,"start":32.52,"end":36.42,"parts":[{"zh":"就说：生日快乐！爸爸一定很高兴。"}],"pinyin":"Jiù shuō: shēngrì kuàilè! Bàba yídìng hěn gāoxìng.","vi":"Chỉ cần nói: chúc mừng sinh nhật! Bố bạn nhất định sẽ rất vui."},{"n":12,"start":36.42,"end":40.4,"parts":[{"zh":"太好了，重要的事情都准备好了！"}],"pinyin":"Tài hǎo le, zhòngyào de shìqing dōu zhǔnbèi hǎo le!","vi":"Tốt quá, những việc quan trọng đều đã chuẩn bị xong rồi!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-1';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-1', 0, '[{"n":1,"start":0,"end":2.98,"parts":[{"zh":"喂，你好！请问您姓什么？"}],"pinyin":"Wèi, nǐ hǎo! Qǐngwèn nín xìng shénme?","vi":"Alo, xin chào! Cho hỏi anh họ gì?"},{"n":2,"start":2.98,"end":6.18,"parts":[{"zh":"我姓王。你叫什么姓名？"}],"pinyin":"Wǒ xìng Wáng. Nǐ jiào shénme xìngmíng?","vi":"Tôi họ Vương. Bạn tên gì?"},{"n":3,"start":6.18,"end":9.01,"parts":[{"zh":"我叫小明。欢迎欢迎！"}],"pinyin":"Wǒ jiào Xiǎomíng. Huānyíng huānyíng!","vi":"Tôi Tiểu Minh. Chào mừng chào mừng!"},{"n":4,"start":9.01,"end":12.24,"parts":[{"zh":"谢谢！这位是你太太吗？"}],"pinyin":"Xièxie! Zhè wèi shì nǐ tàitai ma?","vi":"Cảm ơn! Chị này là vợ anh à?"},{"n":5,"start":12.24,"end":16.01,"parts":[{"zh":"是啊，她是我的爱人，我们都是自己人。"}],"pinyin":"Shì a, tā shì wǒ de àiren, wǒmen dōu shì zìjǐ rén.","vi":"Đúng vậy, cô ấy là vợ tôi, chúng ta đều là người một nhà."},{"n":6,"start":16.01,"end":19.26,"parts":[{"zh":"太太你好！它是一只猫吗？"}],"pinyin":"Tàitai nǐ hǎo! Tā shì yī zhī māo ma?","vi":"Chào chị! Nó là con mèo à?"},{"n":7,"start":19.26,"end":22.060000000000002,"parts":[{"zh":"是啊，它们是我们家的猫。"}],"pinyin":"Shì a, tāmen shì wǒmen jiā de māo.","vi":"Đúng, chúng là mèo nhà tôi."},{"n":8,"start":22.060000000000002,"end":25.910000000000004,"parts":[{"zh":"咱们今天一起吃饭吧，大家都在。"}],"pinyin":"Zánmen jīntiān yīqǐ chīfàn ba, dàjiā dōu zài.","vi":"Chúng ta cùng ăn cơm hôm nay nhé, mọi người đều có mặt."},{"n":9,"start":25.910000000000004,"end":27.990000000000002,"parts":[{"zh":"好，咱们走吧。"}],"pinyin":"Hǎo, zánmen zǒu ba.","vi":"Được, mình đi thôi."},{"n":10,"start":27.990000000000002,"end":31.240000000000002,"parts":[{"zh":"你的笑话真有意思。晚安！"}],"pinyin":"Nǐ de xiàohuà zhēn yǒu yìsi. Wǎn''ān!","vi":"Chuyện cười của anh hay thật. Chúc ngủ ngon!"},{"n":11,"start":31.240000000000002,"end":33.510000000000005,"parts":[{"zh":"晚安，一路平安！"}],"pinyin":"Wǎn''ān, yīlù píng''ān!","vi":"Ngủ ngon, đi đường bình an!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-2';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-2', 0, '[{"n":1,"start":0,"end":2.15,"parts":[{"zh":"那个人是谁？"}],"pinyin":"Nàge rén shì shéi?","vi":"Người kia là ai?"},{"n":2,"start":2.15,"end":5.13,"parts":[{"zh":"他是我的老朋友，姓李。"}],"pinyin":"Tā shì wǒ de lǎopéngyou, xìng Lǐ.","vi":"Anh ấy là bạn cũ của tôi, họ Lý."},{"n":3,"start":5.13,"end":10.05,"parts":[{"zh":"这时候他来我们家做客，我们要欢迎这位客人。"}],"pinyin":"Zhè shíhou tā lái wǒmen jiā zuòkè, wǒmen yào huānyíng zhè wèi kèrén.","vi":"Lúc này anh ấy đến nhà tôi chơi, chúng ta phải chào mừng vị khách này."},{"n":4,"start":10.05,"end":12.670000000000002,"parts":[{"zh":"他做什么工作？"}],"pinyin":"Tā zuò shénme gōngzuò?","vi":"Anh ấy làm công việc gì?"},{"n":5,"start":12.670000000000002,"end":15.290000000000003,"parts":[{"zh":"他和我爸爸是同事。"}],"pinyin":"Tā hé wǒ bàba shì tóngshì.","vi":"Anh ấy đồng nghiệp với bố tôi."},{"n":6,"start":15.290000000000003,"end":18.320000000000004,"parts":[{"zh":"他的家是什么样子的？"}],"pinyin":"Tā de jiā shì shénme yàngzi de?","vi":"Nhà anh ấy thế nào?"},{"n":7,"start":18.320000000000004,"end":21.650000000000006,"parts":[{"zh":"他们全家四口人，家庭很好。"}],"pinyin":"Tāmen quánjiā sì kǒu rén, jiātíng hěn hǎo.","vi":"Nhà họ bốn người, gia đình rất hòa thuận."},{"n":8,"start":21.650000000000006,"end":24.130000000000006,"parts":[{"zh":"这样啊，这么好！"}],"pinyin":"Zhèyàng a, zhème hǎo!","vi":"Thế à, tốt quá!"},{"n":9,"start":24.130000000000006,"end":27.510000000000005,"parts":[{"zh":"那时候我们常常一起吃饭。"}],"pinyin":"Nà shíhou wǒmen chángcháng yīqǐ chīfàn.","vi":"Hồi đó chúng tôi thường hay cùng ăn cơm."},{"n":10,"start":27.510000000000005,"end":30.430000000000007,"parts":[{"zh":"好啊，那时候我也去。"}],"pinyin":"Hǎo a, nà shíhou wǒ yě qù.","vi":"Tốt, đến lúc đó tôi cũng đi."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-3';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-3', 0, '[{"n":1,"start":0,"end":3.1,"parts":[{"zh":"你知道中国有多少人口吗？"}],"pinyin":"Nǐ zhīdào Zhōngguó yǒu duōshǎo rénkǒu ma?","vi":"Bạn có biết Trung Quốc có bao nhiêu dân không?"},{"n":2,"start":3.1,"end":6.65,"parts":[{"zh":"我知道，有十四亿，人口很多。"}],"pinyin":"Wǒ zhīdào, yǒu shísì yì, rénkǒu hěn duō.","vi":"Tôi biết, có một tỷ bốn trăm, dân số rất đông."},{"n":3,"start":6.65,"end":10.75,"parts":[{"zh":"对，人们常说这是一个千万人的大城市。"}],"pinyin":"Duì, rénmen chángshuō zhè shì yī ge qiān wàn rén de dà chéngshì.","vi":"Đúng, người ta hay nói đây là thành phố lớn có cả nghìn vạn người."},{"n":4,"start":10.75,"end":14.2,"parts":[{"zh":"参加晚会的人数是多少？"}],"pinyin":"Cānjiā wǎnhuì de rénshù shì duōshǎo?","vi":"Số người dự tiệc tối là bao nhiêu?"},{"n":5,"start":14.2,"end":17.8,"parts":[{"zh":"大人二十个，青年学生十五个。"}],"pinyin":"Dàrén èrshí ge, qīngnián xuésheng shíwǔ ge.","vi":"Người lớn hai mươi, sinh viên trẻ mười lăm."},{"n":6,"start":17.8,"end":20.85,"parts":[{"zh":"主人准备了什么吃的？"}],"pinyin":"Zhǔrén zhǔnbèile shénme chī de?","vi":"Chủ nhà chuẩn bị món gì để ăn?"},{"n":7,"start":20.85,"end":24.05,"parts":[{"zh":"主人是我的爱人，她会做饭。"}],"pinyin":"Zhǔrén shì wǒ de àiren, tā huì zuòfàn.","vi":"Chủ nhà là vợ tôi, cô ấy nấu ăn ngon."},{"n":8,"start":24.05,"end":27.28,"parts":[{"zh":"那些年轻人都很年轻啊！"}],"pinyin":"Nàxiē niánqīng rén dōu hěn niánqīng a!","vi":"Những người trẻ đó trẻ thật!"},{"n":9,"start":27.28,"end":30.310000000000002,"parts":[{"zh":"是啊，我想和他们交朋友。"}],"pinyin":"Shì a, wǒ xiǎng hé tāmen jiāo péngyou.","vi":"Ừ, tôi muốn kết bạn với họ."},{"n":10,"start":30.310000000000002,"end":33.54,"parts":[{"zh":"好，咱们一起去交朋友吧。"}],"pinyin":"Hǎo, zánmen yīqǐ qù jiāo péngyou ba.","vi":"Được, mình cùng đi kết bạn nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-4';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-4', 0, '[{"n":1,"start":0,"end":2.73,"parts":[{"zh":"我要买两公斤苹果。"}],"pinyin":"Wǒ yào mǎi liǎng gōngjīn píngguǒ.","vi":"Tôi muốn mua hai cân táo."},{"n":2,"start":2.73,"end":6.18,"parts":[{"zh":"苹果一斤三块，你要几斤？"}],"pinyin":"Píngguǒ yī jīn sān kuài, nǐ yào jǐ jīn?","vi":"Táo một cân ba tệ, anh mua mấy cân?"},{"n":3,"start":6.18,"end":9.209999999999999,"parts":[{"zh":"四斤。我还想要一瓶水。"}],"pinyin":"Sì jīn. Wǒ hái xiǎng yào yī píng shuǐ.","vi":"Bốn cân. Tôi còn muốn một chai nước."},{"n":4,"start":9.209999999999999,"end":12.059999999999999,"parts":[{"zh":"一共十二块五角。"}],"pinyin":"Yīgòng shí''èr kuài wǔ jiǎo.","vi":"Cộng lại là mười hai tệ năm hào."},{"n":5,"start":12.059999999999999,"end":15.36,"parts":[{"zh":"给你钱。你看，门口有一辆车。"}],"pinyin":"Gěi nǐ qián. Nǐ kàn, ménkǒu yǒu yī liàng chē.","vi":"Tiền của anh. Nhìn kìa, trước cửa có một chiếc xe."},{"n":6,"start":15.36,"end":18.13,"parts":[{"zh":"那是一辆出租车。"}],"pinyin":"Nà shì yī liàng chūzūchē.","vi":"Đó là một chiếc taxi."},{"n":7,"start":18.13,"end":20.38,"parts":[{"zh":"今天多少度？"}],"pinyin":"Jīntiān duōshǎo dù?","vi":"Hôm nay bao nhiêu độ?"},{"n":8,"start":20.38,"end":23.18,"parts":[{"zh":"二十五度，很凉快。"}],"pinyin":"Èrshíwǔ dù, hěn liángkuai.","vi":"Hai mươi lăm độ, mát lắm."},{"n":9,"start":23.18,"end":26.759999999999998,"parts":[{"zh":"我中午吃了一碗面，还有一条鱼。"}],"pinyin":"Wǒ zhōngwǔ chīle yī wǎn miàn, hái yǒu yī tiáo yú.","vi":"Trưa tôi ăn một bát mì, còn có một con cá."},{"n":10,"start":26.759999999999998,"end":30.74,"parts":[{"zh":"我昨天买了一套书，还有一份报纸。"}],"pinyin":"Wǒ zuótiān mǎile yī tào shū, hái yǒu yī fèn bàozhǐ.","vi":"Hôm qua tôi mua một bộ sách, và một tờ báo."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-5';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-5', 0, '[{"n":1,"start":0,"end":2.65,"parts":[{"zh":"十月是很好的月份。"}],"pinyin":"Shíyuè shì hěn hǎo de yuèfèn.","vi":"Tháng Mười là một tháng rất đẹp."},{"n":2,"start":2.65,"end":6.55,"parts":[{"zh":"是啊，这个周我要完成全部工作。"}],"pinyin":"Shì a, zhège zhōu wǒ yào wánchéng quánbù gōngzuò.","vi":"Ừ, tuần này tôi phải hoàn thành hết công việc."},{"n":3,"start":6.55,"end":9.7,"parts":[{"zh":"所有的人都要参加活动吗？"}],"pinyin":"Suǒyǒu de rén dōu yào cānjiā huódòng ma?","vi":"Tất cả mọi người đều phải tham gia hoạt động à?"},{"n":4,"start":9.7,"end":13.649999999999999,"parts":[{"zh":"大多数人参加，只有少数人不在。"}],"pinyin":"Dàduōshù rén cānjiā, zhǐyǒu shǎoshù rén bú zài.","vi":"Đa số tham gia, chỉ có thiểu số vắng mặt."},{"n":5,"start":13.649999999999999,"end":16.169999999999998,"parts":[{"zh":"不少人喜欢秋天。"}],"pinyin":"Bù shǎo rén xǐhuan qiūtiān.","vi":"Không ít người thích mùa thu."},{"n":6,"start":16.169999999999998,"end":19.049999999999997,"parts":[{"zh":"我也是其中一部分。"}],"pinyin":"Wǒ yě shì qízhōng yī bùfen.","vi":"Tôi cũng là một phần trong đó."},{"n":7,"start":19.049999999999997,"end":22.22,"parts":[{"zh":"今天温度超过了三十度。"}],"pinyin":"Jīntiān wēndù chāoguòle sānshí dù.","vi":"Hôm nay nhiệt độ vượt quá ba mươi độ."},{"n":8,"start":22.22,"end":24.869999999999997,"parts":[{"zh":"我渴了，水不够了。"}],"pinyin":"Wǒ kěle, shuǐ bú gòule.","vi":"Tôi khát rồi, nước không đủ nữa."},{"n":9,"start":24.869999999999997,"end":27.349999999999998,"parts":[{"zh":"瓶子里的水还满吗？"}],"pinyin":"Píngzi lǐ de shuǐ hái mǎn ma?","vi":"Nước trong chai còn đầy không?"},{"n":10,"start":27.349999999999998,"end":31.099999999999998,"parts":[{"zh":"还满，大部分给你，我喝一点点。"}],"pinyin":"Hái mǎn, dà bùfen gěi nǐ, wǒ hē yīdiǎndiǎn.","vi":"Còn đầy, phần lớn cho bạn, tôi chỉ uống một chút."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-6';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-6', 0, '[{"n":1,"start":0,"end":2.33,"parts":[{"zh":"你周末做什么？"}],"pinyin":"Nǐ zhōumò zuò shénme?","vi":"Cuối tuần bạn làm gì?"},{"n":2,"start":2.33,"end":7.28,"parts":[{"zh":"平时我早晨七点起床，周末九点才起床。"}],"pinyin":"Píngshí wǒ zǎochén qī diǎn qǐchuáng, zhōumò jiǔ diǎn cái qǐchuáng.","vi":"Ngày thường tôi sáng bảy giờ dậy, cuối tuần đến chín giờ mới dậy."},{"n":3,"start":7.28,"end":10.18,"parts":[{"zh":"刚才我等了你十分钟。"}],"pinyin":"Gāngcái wǒ děngle nǐ shí fēnzhōng.","vi":"Vừa nãy tôi đợi bạn mười phút."},{"n":4,"start":10.18,"end":13.53,"parts":[{"zh":"对不起，以后我早点儿来。"}],"pinyin":"Duìbuqǐ, yǐhòu wǒ zǎo diǎnr lái.","vi":"Xin lỗi, sau này tôi đến sớm hơn."},{"n":5,"start":13.53,"end":16.53,"parts":[{"zh":"新学期什么时候开学？"}],"pinyin":"Xīn xuéqī shénme shíhou kāixué?","vi":"Học kỳ mới bao giờ khai giảng?"},{"n":6,"start":16.53,"end":20.51,"parts":[{"zh":"九月一号开学，假期还有一个月。"}],"pinyin":"Jiǔyuè yī hào kāixué, jiàqī hái yǒu yī ge yuè.","vi":"Ngày mùng một tháng Chín khai giảng, kỳ nghỉ còn một tháng."},{"n":7,"start":20.51,"end":24.060000000000002,"parts":[{"zh":"昨天夜里十二点，我还在工作。"}],"pinyin":"Zuótiān yèlǐ shí''èr diǎn, wǒ hái zài gōngzuò.","vi":"Tối qua mười hai giờ tôi còn đang làm việc."},{"n":8,"start":24.060000000000002,"end":27.980000000000004,"parts":[{"zh":"半夜工作太累了，你要好好休息。"}],"pinyin":"Bànyè gōngzuò tài lèile, nǐ yào hǎohǎo xiūxi.","vi":"Làm việc nửa đêm mệt quá, bạn phải nghỉ ngơi cho tốt."},{"n":9,"start":27.980000000000004,"end":31.280000000000005,"parts":[{"zh":"以前我不用电脑，后来我买了。"}],"pinyin":"Yǐqián wǒ bú yòng diànnǎo, hòulái wǒ mǎile.","vi":"Trước đây tôi không dùng máy tính, sau đó tôi mua rồi."},{"n":10,"start":31.280000000000005,"end":34.830000000000005,"parts":[{"zh":"现在用电脑工作方便多了。"}],"pinyin":"Xiànzài yòng diànnǎo gōngzuò fāngbiàn duōle.","vi":"Giờ làm việc bằng máy tính tiện hơn nhiều."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-7';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-7', 0, '[{"n":1,"start":0,"end":2.35,"parts":[{"zh":"最近你忙什么？"}],"pinyin":"Zuìjìn nǐ máng shénme?","vi":"Dạo này bạn bận gì?"},{"n":2,"start":2.35,"end":6.25,"parts":[{"zh":"春节快要到了，我要准备过年。"}],"pinyin":"Chūnjié kuài yào dàole, wǒ yào zhǔnbèi guònián.","vi":"Tết sắp đến rồi, tôi phải chuẩn bị đón Tết."},{"n":3,"start":6.25,"end":8.95,"parts":[{"zh":"这个节日有几天假？"}],"pinyin":"Zhège jiérì yǒu jǐ tiān jià?","vi":"Ngày lễ này nghỉ mấy ngày?"},{"n":4,"start":8.95,"end":12.07,"parts":[{"zh":"很长，从一号到七号。"}],"pinyin":"Hěn cháng, cóng yī hào dào qī hào.","vi":"Dài lắm, từ mùng một đến mùng bảy."},{"n":5,"start":12.07,"end":14.8,"parts":[{"zh":"你从小就说汉语吗？"}],"pinyin":"Nǐ cóng xiǎo jiù shuō Hànyǔ ma?","vi":"Bạn từ nhỏ đã nói tiếng Trung à?"},{"n":6,"start":14.8,"end":18.55,"parts":[{"zh":"对，我一直是留学生，学了四年。"}],"pinyin":"Duì, wǒ yīzhí shì liúxuésheng, xuéle sì nián.","vi":"Đúng, tôi vẫn là du học sinh suốt, học bốn năm rồi."},{"n":7,"start":18.55,"end":21.17,"parts":[{"zh":"我们的教室在三层。"}],"pinyin":"Wǒmen de jiàoshì zài sān céng.","vi":"Lớp học của chúng ta ở tầng ba."},{"n":8,"start":21.17,"end":25.17,"parts":[{"zh":"教师在办公室吗？我有问题要问。"}],"pinyin":"Jiàoshī zài bàngōngshì ma? Wǒ yǒu wèntí yào wèn.","vi":"Giáo viên ở văn phòng không? Tôi có câu hỏi."},{"n":9,"start":25.17,"end":28.87,"parts":[{"zh":"老师随时都可以回答你的问题。"}],"pinyin":"Lǎoshī suíshí dōu kěyǐ huídá nǐ de wèntí.","vi":"Thầy cô lúc nào cũng có thể trả lời câu hỏi của bạn."},{"n":10,"start":28.87,"end":32.57,"parts":[{"zh":"那我等一会儿，下课以后去问他。"}],"pinyin":"Nà wǒ děng yīhuìr, xiàkè yǐhòu qù wèn tā.","vi":"Vậy tôi đợi một lát, tan học rồi đi hỏi."},{"n":11,"start":32.57,"end":35.17,"parts":[{"zh":"不一会儿他就回来了。"}],"pinyin":"Bù yīhuìr tā jiù huílái le.","vi":"Không bao lâu anh ấy đã quay lại."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-8';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-8', 0, '[{"n":1,"start":0,"end":3.03,"parts":[{"zh":"明天有考试，你复习了吗？"}],"pinyin":"Míngtiān yǒu kǎoshì, nǐ fùxíle ma?","vi":"Mai có kiểm tra, bạn ôn bài chưa?"},{"n":2,"start":3.03,"end":6.279999999999999,"parts":[{"zh":"复习了，但是有几个难题。"}],"pinyin":"Fùxíle, dànshì yǒu jǐ ge nántí.","vi":"Rồi, nhưng có mấy câu khó."},{"n":3,"start":6.279999999999999,"end":9.549999999999999,"parts":[{"zh":"我帮你讲。第一个题是什么？"}],"pinyin":"Wǒ bāng nǐ jiǎng. Dì yī ge tí shì shénme?","vi":"Tôi giảng giúp. Câu thứ nhất là gì?"},{"n":4,"start":9.549999999999999,"end":12.469999999999999,"parts":[{"zh":"用“刚才”写一个句子。"}],"pinyin":"Yòng “gāngcái” xiě yī ge jùzi.","vi":"Dùng “gāngcái” viết một câu."},{"n":5,"start":12.469999999999999,"end":16.07,"parts":[{"zh":"这很容易：我刚才在教室看书。"}],"pinyin":"Zhè hěn róngyì: Wǒ gāngcái zài jiàoshì kànshū.","vi":"Cái này dễ lắm: vừa nãy tôi đọc sách trong lớp."},{"n":6,"start":16.07,"end":18.8,"parts":[{"zh":"谢谢！我的词典呢？"}],"pinyin":"Xièxie! Wǒ de cídiǎn ne?","vi":"Cảm ơn! Từ điển của tôi đâu?"},{"n":7,"start":18.8,"end":23.47,"parts":[{"zh":"在你的书包里。生词要常常读，读音很重要。"}],"pinyin":"Zài nǐ de shūbāo lǐ. Shēngcí yào chángcháng dú, dúyīn hěn zhòngyào.","vi":"Trong cặp bạn. Từ mới phải đọc thường xuyên, cách đọc rất quan trọng."},{"n":8,"start":23.47,"end":26.77,"parts":[{"zh":"对，普通话要说得清楚。"}],"pinyin":"Duì, pǔtōnghuà yào shuō de qīngchu.","vi":"Đúng, tiếng phổ thông phải nói cho rõ."},{"n":9,"start":26.77,"end":30.22,"parts":[{"zh":"上次的考试，你的成绩怎么样？"}],"pinyin":"Shàng cì de kǎoshì, nǐ de chéngjì zěnme yàng?","vi":"Bài kiểm tra lần trước kết quả thế nào?"},{"n":10,"start":30.22,"end":33.67,"parts":[{"zh":"分数是九十分，我很满意。"}],"pinyin":"Fēnshù shì jiǔshí fēn, wǒ hěn mǎnyì.","vi":"Được chín mươi điểm, tôi rất hài lòng."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-9';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-9', 0, '[{"n":1,"start":0,"end":2.67,"parts":[{"zh":"今天的作业是什么？"}],"pinyin":"Jīntiān de zuòyè shì shénme?","vi":"Bài tập hôm nay là gì?"},{"n":2,"start":2.67,"end":5.67,"parts":[{"zh":"练习三和一篇作文。"}],"pinyin":"Liànxí sān hé yī piān zuòwén.","vi":"Bài tập số ba và một bài văn."},{"n":3,"start":5.67,"end":7.87,"parts":[{"zh":"作文写什么？"}],"pinyin":"Zuòwén xiě shénme?","vi":"Viết văn về gì?"},{"n":4,"start":7.87,"end":10.39,"parts":[{"zh":"写我们的校园。"}],"pinyin":"Xiě wǒmen de xiàoyuán.","vi":"Viết về khuôn viên trường mình."},{"n":5,"start":10.39,"end":13.72,"parts":[{"zh":"班长说，作文要写三百字。"}],"pinyin":"Bānzhǎng shuō, zuòwén yào xiě sānbǎi zì.","vi":"Lớp trưởng nói bài văn phải viết ba trăm chữ."},{"n":6,"start":13.72,"end":17.47,"parts":[{"zh":"三百字太多了！你在哪个年级？"}],"pinyin":"Sānbǎi zì tài duōle! Nǐ zài nǎge niánjí?","vi":"Ba trăm chữ nhiều quá! Bạn học khối nào?"},{"n":7,"start":17.47,"end":20.14,"parts":[{"zh":"五年级。科学课难吗？"}],"pinyin":"Wǔ niánjí. Kēxué kè nán ma?","vi":"Khối năm. Môn khoa học khó không?"},{"n":8,"start":20.14,"end":24.04,"parts":[{"zh":"科学很有意思，老师讲得很好。"}],"pinyin":"Kēxué hěn yǒu yìsi, lǎoshī jiǎng de hěn hǎo.","vi":"Khoa học rất hay, cô giảng rất tốt."},{"n":9,"start":24.04,"end":26.79,"parts":[{"zh":"那你学习一定很努力。"}],"pinyin":"Nà nǐ xuéxí yīdìng hěn nǔlì.","vi":"Vậy chắc bạn học rất chăm."},{"n":10,"start":26.79,"end":30.24,"parts":[{"zh":"我每天练习汉语两个小时。"}],"pinyin":"Wǒ měitiān liànxí Hànyǔ liǎng ge xiǎoshí.","vi":"Tôi mỗi ngày luyện tiếng Trung hai tiếng."},{"n":11,"start":30.24,"end":33.66,"parts":[{"zh":"我们一起复习吧，你先讲，我听。"}],"pinyin":"Wǒmen yīqǐ fùxí ba, nǐ xiān jiǎng, wǒ tīng.","vi":"Chúng ta cùng ôn bài nhé, bạn giảng trước, tôi nghe."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-10';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-10', 0, '[{"n":1,"start":0,"end":3.95,"parts":[{"zh":"你的手机信号不好，我没收到短信。"}],"pinyin":"Nǐ de shǒujī xìnhào bù hǎo, wǒ méi shōudào duǎnxìn.","vi":"Điện thoại bạn sóng kém, tôi không nhận được tin nhắn."},{"n":2,"start":3.95,"end":8.120000000000001,"parts":[{"zh":"我在办公室里，信号是有点儿不好。"}],"pinyin":"Wǒ zài bàngōngshì lǐ, xìnhào shì yǒudiǎnr bù hǎo.","vi":"Tôi đang trong văn phòng, sóng hơi kém thật."},{"n":3,"start":8.120000000000001,"end":11.370000000000001,"parts":[{"zh":"你在这家公司工作多久了？"}],"pinyin":"Nǐ zài zhè jiā gōngsī gōngzuò duō jiǔ le?","vi":"Bạn làm ở công ty này bao lâu rồi?"},{"n":4,"start":11.370000000000001,"end":15.670000000000002,"parts":[{"zh":"三年了。经理打算下个月开新的网站。"}],"pinyin":"Sān nián le. Jīnglǐ dǎsuàn xià ge yuè kāi xīn de wǎngzhàn.","vi":"Ba năm rồi. Giám đốc định tháng sau mở trang web mới."},{"n":5,"start":15.670000000000002,"end":17.92,"parts":[{"zh":"你想当商人吗？"}],"pinyin":"Nǐ xiǎng dāng shāngrén ma?","vi":"Bạn muốn làm doanh nhân à?"},{"n":6,"start":17.92,"end":22.62,"parts":[{"zh":"不想，我想好好学计算机，找一个好工作。"}],"pinyin":"Bù xiǎng, wǒ xiǎng hǎohǎo xué jìsuànjī, zhǎo yī ge hǎo gōngzuò.","vi":"Không, tôi muốn học máy tính cho giỏi, tìm một công việc tốt."},{"n":7,"start":22.62,"end":26.1,"parts":[{"zh":"我用计算机发信息给你，好吗？"}],"pinyin":"Wǒ yòng jìsuànjī fā xìnxī gěi nǐ, hǎo ma?","vi":"Tôi dùng máy tính gửi tin cho bạn nhé?"},{"n":8,"start":26.1,"end":29.85,"parts":[{"zh":"好。我计划明天打印那篇文章。"}],"pinyin":"Hǎo. Wǒ jìhuà míngtiān dǎyìn nà piān wénzhāng.","vi":"Được. Tôi định mai in bài báo đó."},{"n":9,"start":29.85,"end":33.08,"parts":[{"zh":"房间里的灯开了，你去关吧。"}],"pinyin":"Fángjiān lǐ de dēng kāile, nǐ qù guān ba.","vi":"Đèn trong phòng bật rồi, cậu đi tắt đi."},{"n":10,"start":33.08,"end":35.53,"parts":[{"zh":"好，我马上关。"}],"pinyin":"Hǎo, wǒ mǎshàng guān.","vi":"Ừ, tôi tắt ngay đây."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-11';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-11', 0, '[{"n":1,"start":0,"end":3.08,"parts":[{"zh":"今天超市的苹果很便宜。"}],"pinyin":"Jīntiān chāoshì de píngguǒ hěn piányí.","vi":"Hôm nay táo ở siêu thị rẻ lắm."},{"n":2,"start":3.08,"end":7.78,"parts":[{"zh":"太好了！银行在超市旁边，我要先取钱。"}],"pinyin":"Tài hǎole! Yínháng zài chāoshì pángbiān, wǒ yào xiān qǔ qián.","vi":"Tốt quá! Ngân hàng cạnh siêu thị, tôi phải rút tiền trước."},{"n":3,"start":7.78,"end":12.010000000000002,"parts":[{"zh":"我要给妈妈买生日礼物，你有什么好办法？"}],"pinyin":"Wǒ yào gěi māma mǎi shēngrì lǐwù, nǐ yǒu shénme hǎo bànfǎ?","vi":"Tôi phải mua quà sinh nhật cho mẹ, bạn có cách gì hay không?"},{"n":4,"start":12.010000000000002,"end":15.490000000000002,"parts":[{"zh":"那家店里卖手表，不太贵。"}],"pinyin":"Nà jiā diàn lǐ mài shǒubiǎo, bú tài guì.","vi":"Cửa hàng đó bán đồng hồ, không đắt lắm."},{"n":5,"start":15.490000000000002,"end":18.39,"parts":[{"zh":"好，我买了以后送到她家。"}],"pinyin":"Hǎo, wǒ mǎile yǐhòu sòng dào tā jiā.","vi":"Được, mua xong tôi mang đến nhà bà."},{"n":6,"start":18.39,"end":21.97,"parts":[{"zh":"妈妈收到礼物，一定很高兴。"}],"pinyin":"Māma shōudào lǐwù, yīdìng hěn gāoxìng.","vi":"Mẹ nhận được quà chắc chắn rất vui."},{"n":7,"start":21.97,"end":24.45,"parts":[{"zh":"你昨天休假了吗？"}],"pinyin":"Nǐ zuótiān xiūjiàle ma?","vi":"Hôm qua bạn nghỉ phép à?"},{"n":8,"start":24.45,"end":28.4,"parts":[{"zh":"没有，我在酒店打工，干了一天的活儿。"}],"pinyin":"Méiyǒu, wǒ zài jiǔdiàn dǎgōng, gànle yī tiān de huór.","vi":"Không, tôi làm thêm ở khách sạn, làm việc cả ngày."},{"n":9,"start":28.4,"end":31.25,"parts":[{"zh":"那家酒店的服务怎么样？"}],"pinyin":"Nà jiā jiǔdiàn de fúwù zěnme yàng?","vi":"Dịch vụ khách sạn đó thế nào?"},{"n":10,"start":31.25,"end":34.35,"parts":[{"zh":"服务很好，收入也可以。"}],"pinyin":"Fúwù hěn hǎo, shōurù yě kěyǐ.","vi":"Dịch vụ tốt, thu nhập cũng được."},{"n":11,"start":34.35,"end":36.7,"parts":[{"zh":"你要办信用卡吗？"}],"pinyin":"Nǐ yào bàn xìnyòngkǎ ma?","vi":"Bạn có muốn làm thẻ tín dụng không?"},{"n":12,"start":36.7,"end":41.32,"parts":[{"zh":"不要，我的银行卡够用了。我还要去药店买药。"}],"pinyin":"Bú yào, wǒ de yínhángkǎ gòu yòngle. Wǒ hái yào qù yàodiàn mǎi yào.","vi":"Không cần, thẻ ngân hàng của tôi dùng đủ rồi. Tôi còn phải đến hiệu thuốc mua thuốc."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-12';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-12', 0, '[{"n":1,"start":0,"end":3.8,"parts":[{"zh":"我借了同学的自行车，明天要还。"}],"pinyin":"Wǒ jièle tóngxué de zìxíngchē, míngtiān yào huán.","vi":"Tôi mượn xe đạp của bạn học, mai phải trả."},{"n":2,"start":3.8,"end":6.05,"parts":[{"zh":"你去哪儿了？"}],"pinyin":"Nǐ qù nǎr le?","vi":"Bạn đã đi đâu thế?"},{"n":3,"start":6.05,"end":9.68,"parts":[{"zh":"我去取火车票了，明天去东北。"}],"pinyin":"Wǒ qù qǔ huǒchēpiào le, míngtiān qù dōngběi.","vi":"Tôi đi lấy vé tàu, mai đi Đông Bắc."},{"n":4,"start":9.68,"end":11.98,"parts":[{"zh":"你要带什么？"}],"pinyin":"Nǐ yào dài shénme?","vi":"Bạn định mang gì?"},{"n":5,"start":11.98,"end":15.530000000000001,"parts":[{"zh":"带一些吃的和衣服，都在包里头。"}],"pinyin":"Dài yīxiē chī de hé yīfu, dōu zài bāo lǐtou.","vi":"Mang một ít đồ ăn và quần áo, đều ở trong túi."},{"n":6,"start":15.530000000000001,"end":18.98,"parts":[{"zh":"回来了把照片带来给我看。"}],"pinyin":"Huíláile bǎ zhàopiàn dàilái gěi wǒ kàn.","vi":"Về rồi mang ảnh đến cho tôi xem nhé."},{"n":7,"start":18.98,"end":23.26,"parts":[{"zh":"好，我一定带来。这是老师交给你的作业吗？"}],"pinyin":"Hǎo, wǒ yīdìng dàilái. Zhè shì lǎoshī jiāogěi nǐ de zuòyè ma?","vi":"Được, tôi nhất định mang. Đây là bài tập thầy giao cho bạn à?"},{"n":8,"start":23.26,"end":26.490000000000002,"parts":[{"zh":"对，请你帮我交给班长。"}],"pinyin":"Duì, qǐng nǐ bāng wǒ jiāogěi bānzhǎng.","vi":"Đúng, nhờ bạn giúp tôi nộp cho lớp trưởng."},{"n":9,"start":26.490000000000002,"end":29.64,"parts":[{"zh":"可以。下学期我们交换书吧。"}],"pinyin":"Kěyǐ. Xià xuéqī wǒmen jiāohuàn shū ba.","vi":"Được. Học kỳ sau chúng ta trao đổi sách nhé."},{"n":10,"start":29.64,"end":33.49,"parts":[{"zh":"好啊。你家在城市的东南方向吧？"}],"pinyin":"Hǎo a. Nǐ jiā zài chéngshì de dōngnán fāngxiàng ba?","vi":"Tốt đấy. Nhà bạn ở hướng Đông Nam thành phố đúng không?"},{"n":11,"start":33.49,"end":36.52,"parts":[{"zh":"不，在西南，离车站很近。"}],"pinyin":"Bù, zài xīnán, lí chēzhàn hěn jìn.","vi":"Không, ở Tây Nam, gần nhà ga lắm."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-13';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-13', 0, '[{"n":1,"start":0,"end":3.45,"parts":[{"zh":"今天我们去公园吧，天气很好。"}],"pinyin":"Jīntiān wǒmen qù gōngyuán ba, tiānqì hěn hǎo.","vi":"Hôm nay mình đi công viên nhé, thời tiết đẹp lắm."},{"n":2,"start":3.45,"end":6.93,"parts":[{"zh":"好，公园东边有一个动物园。"}],"pinyin":"Hǎo, gōngyuán dōngbian yǒu yī ge dòngwùyuán.","vi":"Được, phía đông công viên có một vườn thú."},{"n":3,"start":6.93,"end":9.6,"parts":[{"zh":"动物园的大门在哪儿？"}],"pinyin":"Dòngwùyuán de dàmén zài nǎr?","vi":"Cổng lớn vườn thú ở đâu?"},{"n":4,"start":9.6,"end":13.6,"parts":[{"zh":"入口在大门旁边，出口在对面。"}],"pinyin":"Rùkǒu zài dàmén pángbiān, chūkǒu zài duìmiàn.","vi":"Lối vào cạnh cổng lớn, lối ra ở đối diện."},{"n":5,"start":13.6,"end":16.48,"parts":[{"zh":"你看，天上有很多鸟！"}],"pinyin":"Nǐ kàn, tiānshang yǒu hěn duō niǎo!","vi":"Nhìn kìa, trên trời có nhiều chim quá!"},{"n":6,"start":16.48,"end":19.13,"parts":[{"zh":"我心里很高兴。"}],"pinyin":"Wǒ xīnlǐ hěn gāoxìng.","vi":"Lòng tôi rất vui."},{"n":7,"start":19.13,"end":22.279999999999998,"parts":[{"zh":"我家院子里有一个小花园。"}],"pinyin":"Wǒ jiā yuànzi lǐ yǒu yī ge xiǎo huāyuán.","vi":"Trong sân nhà tôi có một vườn hoa nhỏ."},{"n":8,"start":22.279999999999998,"end":25.159999999999997,"parts":[{"zh":"院子里种花真好。"}],"pinyin":"Yuànzi lǐ zhòng huā zhēn hǎo.","vi":"Trồng hoa trong sân tốt thật."},{"n":9,"start":25.159999999999997,"end":29.58,"parts":[{"zh":"前面的大楼有二十层，我们在第五层上课。"}],"pinyin":"Qiánmiàn de dàlóu yǒu èrshí céng, wǒmen zài dì wǔ céng shàngkè.","vi":"Tòa nhà trước kia hai mươi tầng, chúng tôi học ở tầng năm."},{"n":10,"start":29.58,"end":33.559999999999995,"parts":[{"zh":"我们还在广场上走了走，人真多。"}],"pinyin":"Wǒmen hái zài guǎngchǎng shang zǒule zǒu, rén zhēn duō.","vi":"Chúng tôi còn đi dạo trên quảng trường, người đông thật."},{"n":11,"start":33.559999999999995,"end":36.63999999999999,"parts":[{"zh":"路边有很多花，真漂亮。"}],"pinyin":"Lùbiān yǒu hěn duō huā, zhēn piàoliang.","vi":"Ven đường có nhiều hoa, đẹp thật."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-14';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-14', 0, '[{"n":1,"start":0,"end":3.4,"parts":[{"zh":"我们怎么去体育场？坐地铁吧。"}],"pinyin":"Wǒmen zěnme qù tǐyùchǎng? Zuò dìtiě ba.","vi":"Mình đi sân vận động bằng cách nào? Đi tàu điện nhé."},{"n":2,"start":3.4,"end":5.779999999999999,"parts":[{"zh":"车站在哪儿？"}],"pinyin":"Chēzhàn zài nǎr?","vi":"Nhà ga ở đâu?"},{"n":3,"start":5.779999999999999,"end":9.03,"parts":[{"zh":"地铁站就在前边，很近。"}],"pinyin":"Dìtiězhàn jiù zài qiánbian, hěn jìn.","vi":"Ga tàu điện ngay phía trước, gần lắm."},{"n":4,"start":9.03,"end":13.079999999999998,"parts":[{"zh":"我不会坐地铁，我更想骑自行车。"}],"pinyin":"Wǒ bú huì zuò dìtiě, wǒ gèng xiǎng qí zìxíngchē.","vi":"Tôi không biết đi tàu điện, tôi thích đạp xe hơn."},{"n":5,"start":13.079999999999998,"end":17.31,"parts":[{"zh":"骑车要二十分钟，坐地铁只要十分钟。"}],"pinyin":"Qíchē yào èrshí fēnzhōng, zuò dìtiě zhǐyào shí fēnzhōng.","vi":"Đạp xe mất hai mươi phút, đi tàu điện chỉ mười phút."},{"n":6,"start":17.31,"end":21.04,"parts":[{"zh":"那我坐出租车。停车场在哪儿？"}],"pinyin":"Nà wǒ zuò chūzūchē. Tíngchēchǎng zài nǎr?","vi":"Thôi tôi đi taxi. Bãi đỗ xe ở đâu?"},{"n":7,"start":21.04,"end":24.04,"parts":[{"zh":"停车场在体育馆对面。"}],"pinyin":"Tíngchēchǎng zài tǐyùguǎn duìmiàn.","vi":"Bãi đỗ xe ở đối diện nhà thi đấu."},{"n":8,"start":24.04,"end":28.04,"parts":[{"zh":"前面有一条船，我们可以坐船过河吗？"}],"pinyin":"Qiánmiàn yǒu yī tiáo chuán, wǒmen kěyǐ zuò chuán guò hé ma?","vi":"Phía trước có một chiếc thuyền, mình có thể đi thuyền qua sông không?"},{"n":9,"start":28.04,"end":31.04,"parts":[{"zh":"可以，坐船五分钟就到。"}],"pinyin":"Kěyǐ, zuò chuán wǔ fēnzhōng jiù dào.","vi":"Được, đi thuyền năm phút là tới."},{"n":10,"start":31.04,"end":34.31,"parts":[{"zh":"公共汽车站也在那儿吗？"}],"pinyin":"Gōnggòng qìchē zhàn yě zài nàr ma?","vi":"Trạm xe buýt cũng ở đó à?"},{"n":11,"start":34.31,"end":37.510000000000005,"parts":[{"zh":"在，公交车每五分钟来一辆。"}],"pinyin":"Zài, gōngjiāochē měi wǔ fēnzhōng lái yī liàng.","vi":"Ở đó, xe buýt năm phút có một chuyến."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-15';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-15', 0, '[{"n":1,"start":0,"end":3.05,"parts":[{"zh":"你明年打算去哪儿旅行？"}],"pinyin":"Nǐ míngnián dǎsuàn qù nǎr lǚxíng?","vi":"Năm sau bạn định đi du lịch đâu?"},{"n":2,"start":3.05,"end":7.3,"parts":[{"zh":"我想去南方爬山，还想去看大海。"}],"pinyin":"Wǒ xiǎng qù nánfāng páshān, hái xiǎng qù kàn dàhǎi.","vi":"Tôi muốn vào miền Nam leo núi, còn muốn đi xem biển."},{"n":3,"start":7.3,"end":9.7,"parts":[{"zh":"什么时候出发？"}],"pinyin":"Shénme shíhou chūfā?","vi":"Khi nào khởi hành?"},{"n":4,"start":9.7,"end":13.2,"parts":[{"zh":"七月，飞机下午三点起飞。"}],"pinyin":"Qīyuè, fēijī xiàwǔ sān diǎn qǐfēi.","vi":"Tháng Bảy, máy bay ba giờ chiều cất cánh."},{"n":5,"start":13.2,"end":16.119999999999997,"parts":[{"zh":"去机场要走哪条公路？"}],"pinyin":"Qù jīchǎng yào zǒu nǎ tiáo gōnglù?","vi":"Ra sân bay đi đường cao tốc nào?"},{"n":6,"start":16.119999999999997,"end":19.97,"parts":[{"zh":"新的公路很近，只要四十分钟。"}],"pinyin":"Xīn de gōnglù hěn jìn, zhǐyào sìshí fēnzhōng.","vi":"Đường mới gần lắm, chỉ bốn mươi phút."},{"n":7,"start":19.97,"end":22.299999999999997,"parts":[{"zh":"你的护照带了吗？"}],"pinyin":"Nǐ de hùzhào dài le ma?","vi":"Bạn mang hộ chiếu chưa?"},{"n":8,"start":22.299999999999997,"end":26.029999999999998,"parts":[{"zh":"带了，旅行的时候不能离开护照。"}],"pinyin":"Dài le, lǚxíng de shíhou bù néng líkāi hùzhào.","vi":"Mang rồi, đi du lịch không thể thiếu hộ chiếu."},{"n":9,"start":26.029999999999998,"end":29.029999999999998,"parts":[{"zh":"这条街上有很多游客。"}],"pinyin":"Zhè tiáo jiē shang yǒu hěn duō yóukè.","vi":"Con phố này có nhiều du khách."},{"n":10,"start":29.029999999999998,"end":32.53,"parts":[{"zh":"他们在问去火车站的方向。"}],"pinyin":"Tāmen zài wèn qù huǒchēzhàn de fāngxiàng.","vi":"Họ đang hỏi hướng đến nhà ga."},{"n":11,"start":32.53,"end":37.63,"parts":[{"zh":"我带他们去，火车站离这儿不远，交通也很方便。"}],"pinyin":"Wǒ dài tāmen qù, huǒchēzhàn lí zhèr bù yuǎn, jiāotōng yě hěn fāngbiàn.","vi":"Tôi dẫn họ đi, nhà ga cách đây không xa, giao thông cũng tiện."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-16';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-16', 0, '[{"n":1,"start":0,"end":3.45,"parts":[{"zh":"请问一下路，去饭馆怎么走？"}],"pinyin":"Qǐngwèn yīxià lù, qù fànguǎn zěnme zǒu?","vi":"Cho hỏi đường, đi quán ăn thế nào?"},{"n":2,"start":3.45,"end":6.550000000000001,"parts":[{"zh":"直走，到路口向左拐。"}],"pinyin":"Zhí zǒu, dào lùkǒu xiàng zuǒ guǎi.","vi":"Đi thẳng, đến ngã rẽ rẽ trái."},{"n":3,"start":6.550000000000001,"end":9.97,"parts":[{"zh":"谢谢！咦，我碰到一个老朋友了。"}],"pinyin":"Xièxie! Yí, wǒ pèngdào yī ge lǎo péngyou le.","vi":"Cảm ơn! Ơ, tôi gặp phải một người bạn cũ."},{"n":4,"start":9.97,"end":13.39,"parts":[{"zh":"真的？你们多少年没见面了？"}],"pinyin":"Zhēn de? Nǐmen duōshǎo nián méi jiànmiàn le?","vi":"Thật à? Các bạn bao nhiêu năm không gặp?"},{"n":5,"start":13.39,"end":17.16,"parts":[{"zh":"十年了！今天见到她，我太高兴了。"}],"pinyin":"Shí nián le! Jīntiān jiàndào tā, wǒ tài gāoxìng le.","vi":"Mười năm rồi! Hôm nay gặp cô ấy, tôi vui quá."},{"n":6,"start":17.16,"end":20.26,"parts":[{"zh":"快举手，和她打招呼吧！"}],"pinyin":"Kuài jǔ shǒu, hé tā dǎ zhāohu ba!","vi":"Nhanh giơ tay lên, chào cô ấy đi!"},{"n":7,"start":20.26,"end":24.03,"parts":[{"zh":"我轻轻拉了她一下，她回头就笑了。"}],"pinyin":"Wǒ qīngqīng lāle tā yīxià, tā huítóu jiù xiào le.","vi":"Tôi khẽ kéo tay cô ấy, cô quay lại liền cười."},{"n":8,"start":24.03,"end":28.28,"parts":[{"zh":"她说晚上请我们吃饭，有鱼，还有鸡蛋。"}],"pinyin":"Tā shuō wǎnshang qǐng wǒmen chīfàn, yǒu yú, hái yǒu jīdàn.","vi":"Cô ấy nói tối mời chúng ta ăn cơm, có cá và cả trứng."},{"n":9,"start":28.28,"end":31.26,"parts":[{"zh":"太好了，我最喜欢吃鱼。"}],"pinyin":"Tài hǎole, wǒ zuì xǐhuan chī yú.","vi":"Tốt quá, tôi thích ăn cá nhất."},{"n":10,"start":31.26,"end":35.21,"parts":[{"zh":"那儿还有一只鸡，是她家养的，不卖。"}],"pinyin":"Nàr hái yǒu yī zhī jī, shì tā jiā yǎng de, bú mài.","vi":"Ở đó còn có một con gà, nhà cô nuôi, không bán."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-17';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-17', 0, '[{"n":1,"start":0,"end":3.7,"parts":[{"zh":"中午我们吃什么？中餐还是西餐？"}],"pinyin":"Zhōngwǔ wǒmen chī shénme? Zhōngcān háishì xīcān?","vi":"Trưa mình ăn gì? Món Trung hay món Tây?"},{"n":2,"start":3.7,"end":7.300000000000001,"parts":[{"zh":"我想吃中餐，我最爱吃饺子。"}],"pinyin":"Wǒ xiǎng chī zhōngcān, wǒ zuì ài chī jiǎozi.","vi":"Tôi muốn ăn món Trung, tôi thích ăn sủi cảo nhất."},{"n":3,"start":7.300000000000001,"end":11.13,"parts":[{"zh":"那家饭馆味道很好，今天我请客。"}],"pinyin":"Nà jiā fànguǎn wèidào hěn hǎo, jīntiān wǒ qǐngkè.","vi":"Quán đó món ngon lắm, hôm nay tôi mời."},{"n":4,"start":11.13,"end":14.030000000000001,"parts":[{"zh":"谢谢！我看看菜单。"}],"pinyin":"Xièxie! Wǒ kànkan càidān.","vi":"Cảm ơn! Để tôi xem thực đơn."},{"n":5,"start":14.030000000000001,"end":16.200000000000003,"parts":[{"zh":"你会用筷子吗？"}],"pinyin":"Nǐ huì yòng kuàizi ma?","vi":"Bạn biết dùng đũa không?"},{"n":6,"start":16.200000000000003,"end":19.6,"parts":[{"zh":"会用，我用得不错。来，干杯！"}],"pinyin":"Huì yòng, wǒ yòng de búcuò. Lái, gānbēi!","vi":"Biết, tôi dùng khá lắm. Nào, cạn ly!"},{"n":7,"start":19.6,"end":22.220000000000002,"parts":[{"zh":"我不喝酒，我喝水吧。"}],"pinyin":"Wǒ bù hē jiǔ, wǒ hē shuǐ ba.","vi":"Tôi không uống rượu, tôi uống nước thôi."},{"n":8,"start":22.220000000000002,"end":25.300000000000004,"parts":[{"zh":"好。这儿的早餐怎么样？"}],"pinyin":"Hǎo. Zhèr de zǎocān zěnme yàng?","vi":"Được. Bữa sáng ở đây thế nào?"},{"n":9,"start":25.300000000000004,"end":29.680000000000003,"parts":[{"zh":"方便面不好吃，早餐还是在家做饭好。"}],"pinyin":"Fāngbiànmiàn bù hǎochī, zǎocān háishì zài jiā zuòfàn hǎo.","vi":"Mì ăn liền không ngon, bữa sáng vẫn tốt hơn là nấu ở nhà."},{"n":10,"start":29.680000000000003,"end":34.010000000000005,"parts":[{"zh":"我中午常常叫外卖，吃完睡个午睡。"}],"pinyin":"Wǒ zhōngwǔ chángcháng jiào wàimài, chī wán shuì ge wǔshuì.","vi":"Trưa tôi thường gọi đồ ăn mang về, ăn xong ngủ một giấc trưa."},{"n":11,"start":34.010000000000005,"end":38.540000000000006,"parts":[{"zh":"我吃得很饱，就不睡了。我们找个座位坐下吧。"}],"pinyin":"Wǒ chī de hěn bǎo, jiù bú shuì le. Wǒmen zhǎo ge zuòwei zuò xià ba.","vi":"Tôi ăn no rồi, không ngủ nữa. Mình tìm chỗ ngồi nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-18';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-18', 0, '[{"n":1,"start":0,"end":2.62,"parts":[{"zh":"你怎么了？脸这么白。"}],"pinyin":"Nǐ zěnme le? Liǎn zhème bái.","vi":"Sao thế? Mặt bạn tái thế này."},{"n":2,"start":2.62,"end":5.5,"parts":[{"zh":"我头疼，真不舒服。"}],"pinyin":"Wǒ tóuténg, zhēn bù shūfu.","vi":"Tôi đau đầu, khó chịu thật."},{"n":3,"start":5.5,"end":9.2,"parts":[{"zh":"我带你去医院，让医生检查一下。"}],"pinyin":"Wǒ dài nǐ qù yīyuàn, ràng yīshēng jiǎnchá yīxià.","vi":"Tôi đưa bạn đến bệnh viện, để bác sĩ khám."},{"n":4,"start":9.2,"end":12.579999999999998,"parts":[{"zh":"我怕去医院，也不想吃药。"}],"pinyin":"Wǒ pà qù yīyuàn, yě bù xiǎng chī yào.","vi":"Tôi sợ đi bệnh viện, cũng không muốn uống thuốc."},{"n":5,"start":12.579999999999998,"end":15.909999999999998,"parts":[{"zh":"吃药不疼，吃了药你就舒服了。"}],"pinyin":"Chī yào bù téng, chīle yào nǐ jiù shūfu le.","vi":"Uống thuốc không đau, uống xong bạn sẽ dễ chịu."},{"n":6,"start":15.909999999999998,"end":18.409999999999997,"parts":[{"zh":"好吧，我听你的。"}],"pinyin":"Hǎo ba, wǒ tīng nǐ de.","vi":"Được rồi, tôi nghe bạn."},{"n":7,"start":18.409999999999997,"end":21.889999999999997,"parts":[{"zh":"医生说你的病不重，不用住院。"}],"pinyin":"Yīshēng shuō nǐ de bìng bú zhòng, bú yòng zhùyuàn.","vi":"Bác sĩ nói bệnh bạn không nặng, không cần nằm viện."},{"n":8,"start":21.889999999999997,"end":25.639999999999997,"parts":[{"zh":"太好了！我哥哥上个月刚出院。"}],"pinyin":"Tài hǎole! Wǒ gēge shàng ge yuè gāng chūyuàn.","vi":"Tốt quá! Anh tôi tháng trước vừa xuất viện."},{"n":9,"start":25.639999999999997,"end":28.119999999999997,"parts":[{"zh":"他现在很健康吗？"}],"pinyin":"Tā xiànzài hěn jiànkāng ma?","vi":"Bây giờ anh ấy khỏe không?"},{"n":10,"start":28.119999999999997,"end":32.839999999999996,"parts":[{"zh":"很健康，他每天走很多路，头发都黑黑的。"}],"pinyin":"Hěn jiànkāng, tā měitiān zǒu hěn duō lù, tóufa dōu hēihēi de.","vi":"Khỏe lắm, mỗi ngày anh ấy đi bộ nhiều, tóc đen nhánh."},{"n":11,"start":32.839999999999996,"end":36.81999999999999,"parts":[{"zh":"那你别大声喊了，小声说话，多休息。"}],"pinyin":"Nà nǐ bié dàshēng hǎn le, xiǎoshēng shuōhuà, duō xiūxi.","vi":"Vậy bạn đừng hét to nữa, nói nhỏ thôi, nghỉ ngơi nhiều."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-19';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-19', 0, '[{"n":1,"start":0,"end":2.67,"parts":[{"zh":"你的心情好点儿了吗？"}],"pinyin":"Nǐ de xīnqíng hǎo diǎnr le ma?","vi":"Tâm trạng bạn đỡ hơn chưa?"},{"n":2,"start":2.67,"end":6.1899999999999995,"parts":[{"zh":"好多了，刚才我有一点儿难过。"}],"pinyin":"Hǎo duōle, gāngcái wǒ yǒu yīdiǎnr nánguò.","vi":"Đỡ nhiều rồi, lúc nãy tôi hơi buồn."},{"n":3,"start":6.1899999999999995,"end":9.59,"parts":[{"zh":"不要难过，你的生活不是很好吗？"}],"pinyin":"Bú yào nánguò, nǐ de shēnghuó bú shì hěn hǎo ma?","vi":"Đừng buồn, cuộc sống của bạn không phải rất tốt à?"},{"n":4,"start":9.59,"end":14.26,"parts":[{"zh":"是很好，可是工作不太顺利，我有点儿急。"}],"pinyin":"Shì hěn hǎo, kěshì gōngzuò bú tài shùnlì, wǒ yǒudiǎnr jí.","vi":"Rất tốt, nhưng công việc không thuận lắm, tôi hơi nóng lòng."},{"n":5,"start":14.26,"end":17.64,"parts":[{"zh":"不要急，事情会慢慢变好的。"}],"pinyin":"Bú yào jí, shìqing huì mànmàn biàn hǎo de.","vi":"Đừng vội, mọi chuyện sẽ dần tốt lên."},{"n":6,"start":17.64,"end":20.79,"parts":[{"zh":"听你说话，我开心多了。"}],"pinyin":"Tīng nǐ shuōhuà, wǒ kāixīn duōle.","vi":"Nghe bạn nói, tôi vui hơn nhiều."},{"n":7,"start":20.79,"end":23.77,"parts":[{"zh":"你真香，刚才洗澡了吧？"}],"pinyin":"Nǐ zhēn xiāng, gāngcái xǐzǎo ba?","vi":"Bạn thơm thật, vừa tắm đúng không?"},{"n":8,"start":23.77,"end":26.22,"parts":[{"zh":"对，刚洗了澡。"}],"pinyin":"Duì, gāng xǐle zǎo.","vi":"Đúng, vừa tắm xong."},{"n":9,"start":26.22,"end":30.02,"parts":[{"zh":"晚上回家路上要小心，注意安全。"}],"pinyin":"Wǎnshang huí jiā lùshang yào xiǎoxīn, zhùyì ānquán.","vi":"Tối về đường phải cẩn thận, chú ý an toàn."},{"n":10,"start":30.02,"end":34.37,"parts":[{"zh":"放心吧，我坐公共汽车回去，一路平安。"}],"pinyin":"Fàngxīn ba, wǒ zuò gōnggòng qìchē huíqù, yīlù píng''ān.","vi":"Yên tâm đi, tôi bắt xe buýt về, đi đường bình an."},{"n":11,"start":34.37,"end":37.97,"parts":[{"zh":"那就好，祝你们全家平安快乐！"}],"pinyin":"Nà jiù hǎo, zhù nǐmen quánjiā píng''ān kuàilè!","vi":"Thế thì tốt, chúc cả nhà bạn bình an vui vẻ!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-20';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-20', 0, '[{"n":1,"start":0,"end":3.5,"parts":[{"zh":"今天是晴天，我们出去走走吧。"}],"pinyin":"Jīntiān shì qíngtiān, wǒmen chūqù zǒuzǒu ba.","vi":"Hôm nay trời quang, mình ra ngoài đi dạo nhé."},{"n":2,"start":3.5,"end":7.33,"parts":[{"zh":"好，我想去图书馆，那里很安静。"}],"pinyin":"Hǎo, wǒ xiǎng qù túshūguǎn, nàlǐ hěn ānjìng.","vi":"Được, tôi muốn đến thư viện, nơi đó yên tĩnh lắm."},{"n":3,"start":7.33,"end":11.129999999999999,"parts":[{"zh":"你感觉怎么样？你的汉语越来越好了。"}],"pinyin":"Nǐ gǎnjué zěnme yàng? Nǐ de Hànyǔ yuèláiyuè hǎo le.","vi":"Bạn cảm thấy thế nào? Tiếng Trung của bạn ngày càng tốt."},{"n":4,"start":11.129999999999999,"end":15.229999999999999,"parts":[{"zh":"我感到很高兴，可是我还不够努力。"}],"pinyin":"Wǒ gǎndào hěn gāoxìng, kěshì wǒ hái bú gòu nǔlì.","vi":"Tôi thấy rất vui, nhưng tôi chưa chăm đủ."},{"n":5,"start":15.229999999999999,"end":18.729999999999997,"parts":[{"zh":"你实在很努力了，我对你很满意。"}],"pinyin":"Nǐ shízài hěn nǔlì le, wǒ duì nǐ hěn mǎnyì.","vi":"Thực ra bạn đã rất chăm rồi, tôi rất hài lòng về bạn."},{"n":6,"start":18.729999999999997,"end":21.179999999999996,"parts":[{"zh":"太感谢你了！"}],"pinyin":"Tài gǎnxiè nǐ le!","vi":"Cảm ơn bạn nhiều lắm!"},{"n":7,"start":21.179999999999996,"end":25.009999999999998,"parts":[{"zh":"图书馆的老师们都很热情、友好。"}],"pinyin":"Túshūguǎn de lǎoshīmen dōu hěn rèqíng, yǒuhǎo.","vi":"Các thầy cô ở thư viện đều rất nhiệt tình, thân thiện."},{"n":8,"start":25.009999999999998,"end":28.509999999999998,"parts":[{"zh":"对，他们讲的故事特别有意思。"}],"pinyin":"Duì, tāmen jiǎng de gùshi tèbié yǒu yìsi.","vi":"Đúng, những câu chuyện họ kể đặc biệt hay."},{"n":9,"start":28.509999999999998,"end":32.14,"parts":[{"zh":"我妹妹买了一只小猫，非常可爱。"}],"pinyin":"Wǒ mèimei mǎile yī zhī xiǎo māo, fēicháng kě''ài.","vi":"Em gái tôi mua một con mèo con, dễ thương lắm."},{"n":10,"start":32.14,"end":36.22,"parts":[{"zh":"我们去看看吧！去哪儿都行，随便你。"}],"pinyin":"Wǒmen qù kànkan ba! Qù nǎr dōu xíng, suíbiàn nǐ.","vi":"Đi xem đi! Đi đâu cũng được, tùy bạn."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-21';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-21', 0, '[{"n":1,"start":0,"end":3.3,"parts":[{"zh":"今天是阴天，天上都是云。"}],"pinyin":"Jīntiān shì yīntiān, tiānshang dōu shì yún.","vi":"Hôm nay trời âm u, trên trời toàn mây."},{"n":2,"start":3.3,"end":7.33,"parts":[{"zh":"明天可能下雪，气温是零下五度。"}],"pinyin":"Míngtiān kěnéng xiàxuě, qìwēn shì língxià wǔ dù.","vi":"Mai có thể có tuyết, nhiệt độ âm năm độ."},{"n":3,"start":7.33,"end":10.18,"parts":[{"zh":"太冷了！我不喜欢冬天。"}],"pinyin":"Tài lěngle! Wǒ bù xǐhuan dōngtiān.","vi":"Lạnh quá! Tôi không thích mùa đông."},{"n":4,"start":10.18,"end":13.85,"parts":[{"zh":"我喜欢，雪白的冬天真漂亮。"}],"pinyin":"Wǒ xǐhuan, xuěbái de dōngtiān zhēn piàoliang.","vi":"Tôi thích, mùa đông trắng tuyết đẹp lắm."},{"n":5,"start":13.85,"end":16.47,"parts":[{"zh":"你喜欢什么颜色？"}],"pinyin":"Nǐ xǐhuan shénme yánsè?","vi":"Bạn thích màu gì?"},{"n":6,"start":16.47,"end":19.869999999999997,"parts":[{"zh":"我喜欢红色和蓝色，你呢？"}],"pinyin":"Wǒ xǐhuan hóngsè hé lánsè, nǐ ne?","vi":"Tôi thích màu đỏ và màu xanh dương, còn bạn?"},{"n":7,"start":19.869999999999997,"end":23.29,"parts":[{"zh":"我喜欢绿色，叶子是绿的，很亮。"}],"pinyin":"Wǒ xǐhuan lǜsè, yèzi shì lǜ de, hěn liàng.","vi":"Tôi thích màu xanh lá, lá cây xanh xanh, tươi sáng lắm."},{"n":8,"start":23.29,"end":27.439999999999998,"parts":[{"zh":"黑衣服也好看，你穿黑的更精神。"}],"pinyin":"Hēi yīfu yě hǎokàn, nǐ chuān hēi de gèng jīngshen.","vi":"Quần áo màu đen cũng đẹp, bạn mặc đen còn hơn nữa."},{"n":9,"start":27.439999999999998,"end":30.939999999999998,"parts":[{"zh":"现在气温多少？屋里有点儿冷。"}],"pinyin":"Xiànzài qìwēn duōshǎo? Wūlǐ yǒudiǎnr lěng.","vi":"Bây giờ nhiệt độ bao nhiêu? Trong nhà hơi lạnh."},{"n":10,"start":30.939999999999998,"end":33.839999999999996,"parts":[{"zh":"屋里十度，外面更冷。"}],"pinyin":"Wūlǐ shí dù, wàimiàn gèng lěng.","vi":"Trong nhà mười độ, ngoài kia còn lạnh hơn."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-22';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-22', 0, '[{"n":1,"start":0,"end":3.05,"parts":[{"zh":"你看，那件衣服多漂亮！"}],"pinyin":"Nǐ kàn, nà jiàn yīfu duō piàoliang!","vi":"Nhìn đi, cái áo kia đẹp làm sao!"},{"n":2,"start":3.05,"end":6.8,"parts":[{"zh":"我觉得不好看，红色太普通了。"}],"pinyin":"Wǒ juéde bù hǎokàn, hóngsè tài pǔtōng le.","vi":"Tôi thấy không đẹp, màu đỏ quá bình thường."},{"n":3,"start":6.8,"end":10,"parts":[{"zh":"我不同意，红色很适合你。"}],"pinyin":"Wǒ bù tóngyì, hóngsè hěn shìhé nǐ.","vi":"Tôi không đồng ý, màu đỏ rất hợp với bạn."},{"n":4,"start":10,"end":13.5,"parts":[{"zh":"这个颜色街上到处都是。"}],"pinyin":"Zhège yánsè jiēshang dàochù dōu shì.","vi":"Màu này trên phố có ở khắp nơi."},{"n":5,"start":13.5,"end":17.4,"parts":[{"zh":"这条路又短又方便，为什么没人走？"}],"pinyin":"Zhè tiáo lù yòu duǎn yòu fāngbiàn, wèishénme méi rén zǒu?","vi":"Con đường này ngắn và tiện, sao không ai đi?"},{"n":6,"start":17.4,"end":20.729999999999997,"parts":[{"zh":"因为太脏了，而且不安静。"}],"pinyin":"Yīnwèi tài zāng le, érqiě bù ānjìng.","vi":"Vì quá bẩn, mà lại không yên tĩnh."},{"n":7,"start":20.729999999999997,"end":23.499999999999996,"parts":[{"zh":"你的汉语说得真流利。"}],"pinyin":"Nǐ de Hànyǔ shuō de zhēn liúlì.","vi":"Tiếng Trung của bạn nói lưu loát thật."},{"n":8,"start":23.499999999999996,"end":27.169999999999995,"parts":[{"zh":"哪里哪里，我说得还不够清楚。"}],"pinyin":"Nǎlǐ nǎlǐ, wǒ shuō de hái bú gòu qīngchu.","vi":"Không dám đâu, tôi nói vẫn chưa đủ rõ."},{"n":9,"start":27.169999999999995,"end":30.589999999999996,"parts":[{"zh":"你说得太好了，而且很正确。"}],"pinyin":"Nǐ shuō de tài hǎo le, érqiě hěn zhèngquè.","vi":"Bạn nói hay lắm, mà lại rất chính xác."},{"n":10,"start":30.589999999999996,"end":34.169999999999995,"parts":[{"zh":"今天天气很凉快，真舒服。"}],"pinyin":"Jīntiān tiānqì hěn liángkuai, zhēn shūfu.","vi":"Hôm nay thời tiết mát mẻ, dễ chịu thật."},{"n":11,"start":34.169999999999995,"end":37.769999999999996,"parts":[{"zh":"对，不冷不热，很正常的好天气。"}],"pinyin":"Duì, bù lěng bú rè, hěn zhèngcháng de hǎo tiānqì.","vi":"Ừ, không lạnh không nóng, thời tiết đẹp bình thường."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-23';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-23', 0, '[{"n":1,"start":0,"end":3.05,"parts":[{"zh":"这两个城市有什么不同？"}],"pinyin":"Zhè liǎng ge chéngshì yǒu shénme bùtóng?","vi":"Hai thành phố này khác nhau chỗ nào?"},{"n":2,"start":3.05,"end":6.5,"parts":[{"zh":"实际上，它们差不多，都很大。"}],"pinyin":"Shíjì shang, tāmen chàbuduō, dōu hěn dà.","vi":"Thực ra, chúng cũng na ná nhau, đều rất lớn."},{"n":3,"start":6.5,"end":8.65,"parts":[{"zh":"哪一个更好？"}],"pinyin":"Nǎ yī ge gèng hǎo?","vi":"Cái nào tốt hơn?"},{"n":4,"start":8.65,"end":12.68,"parts":[{"zh":"北方的冬天更冷，南方的更暖和。"}],"pinyin":"Běifāng de dōngtiān gèng lěng, nánfāng de gèng nuǎnhuo.","vi":"Mùa đông miền Bắc lạnh hơn, miền Nam ấm hơn."},{"n":5,"start":12.68,"end":16.83,"parts":[{"zh":"我觉得它们很相同，人们的说法也一样。"}],"pinyin":"Wǒ juéde tāmen hěn xiāngtóng, rénmen de shuōfǎ yě yīyàng.","vi":"Tôi thấy chúng rất giống nhau, cách nói của mọi người cũng vậy."},{"n":6,"start":16.83,"end":20.63,"parts":[{"zh":"不一样，一般南方人吃得特别辣。"}],"pinyin":"Bù yīyàng, yībān nánfāng rén chī de tèbié là.","vi":"Không giống, bình thường người miền Nam ăn rất cay."},{"n":7,"start":20.63,"end":24.029999999999998,"parts":[{"zh":"越来越多人喜欢在河边走。"}],"pinyin":"Yuèláiyuè duō rén xǐhuan zài hébiān zǒu.","vi":"Ngày càng nhiều người thích đi dạo ven sông."},{"n":8,"start":24.029999999999998,"end":27.259999999999998,"parts":[{"zh":"对，那个湖边特别漂亮。"}],"pinyin":"Duì, nàge húbiān tèbié piàoliang.","vi":"Đúng, ven hồ đó đặc biệt đẹp."},{"n":9,"start":27.259999999999998,"end":31.209999999999997,"parts":[{"zh":"今天真冷，是挺冷的，多穿点儿衣服。"}],"pinyin":"Jīntiān zhēn lěng, shì tǐng lěng de, duō chuān diǎnr yīfu.","vi":"Hôm nay lạnh thật, là lạnh thật đấy, mặc thêm quần áo."},{"n":10,"start":31.209999999999997,"end":34.48,"parts":[{"zh":"去年这个时候十分暖和。"}],"pinyin":"Qùnián zhège shíhou shífēn nuǎnhuo.","vi":"Cùng thời điểm năm ngoái rất ấm."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-24';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-24', 0, '[{"n":1,"start":0,"end":4.28,"parts":[{"zh":"你最喜欢春天、夏天、秋天，还是冬天？"}],"pinyin":"Nǐ zuì xǐhuan chūntiān, xiàtiān, qiūtiān, háishì dōngtiān?","vi":"Bạn thích nhất xuân, hạ, thu, hay đông?"},{"n":2,"start":4.28,"end":8.26,"parts":[{"zh":"我最喜欢夏天，可以去海边游泳。"}],"pinyin":"Wǒ zuì xǐhuan xiàtiān, kěyǐ qù hǎibiān yóuyǒng.","vi":"Tôi thích mùa hạ nhất, có thể đi biển bơi."},{"n":3,"start":8.26,"end":11.96,"parts":[{"zh":"我喜欢春天，草是绿的，花都开了。"}],"pinyin":"Wǒ xǐhuan chūntiān, cǎo shì lǜ de, huā dōu kāi le.","vi":"Tôi thích mùa xuân, cỏ xanh, hoa nở hết."},{"n":4,"start":11.96,"end":15.510000000000002,"parts":[{"zh":"秋天的草地上，太阳真好。"}],"pinyin":"Qiūtiān de cǎodì shang, tàiyáng zhēn hǎo.","vi":"Trên bãi cỏ mùa thu, nắng thật dễ chịu."},{"n":5,"start":15.510000000000002,"end":19.01,"parts":[{"zh":"冬天的晚上有月亮和星星。"}],"pinyin":"Dōngtiān de wǎnshang yǒu yuèliang hé xīngxing.","vi":"Tối mùa đông có trăng và sao."},{"n":6,"start":19.01,"end":22.590000000000003,"parts":[{"zh":"对，天空很干净，星星很亮。"}],"pinyin":"Duì, tiānkōng hěn gānjìng, xīngxing hěn liàng.","vi":"Đúng, trời trong, sao sáng lắm."},{"n":7,"start":22.590000000000003,"end":25.840000000000003,"parts":[{"zh":"我家养了一只狗和两只鸟。"}],"pinyin":"Wǒ jiā yǎngle yī zhī gǒu hé liǎng zhī niǎo.","vi":"Nhà tôi nuôi một con chó và hai con chim."},{"n":8,"start":25.840000000000003,"end":30.490000000000002,"parts":[{"zh":"我也喜欢小动物，猫和狗都是人类的朋友。"}],"pinyin":"Wǒ yě xǐhuan xiǎo dòngwù, māo hé gǒu dōu shì rénlèi de péngyou.","vi":"Tôi cũng thích động vật nhỏ, mèo chó đều là bạn của loài người."},{"n":9,"start":30.490000000000002,"end":33.99,"parts":[{"zh":"对，动物和我们住在一个地球上。"}],"pinyin":"Duì, dòngwù hé wǒmen zhù zài yī ge dìqiú shang.","vi":"Đúng, động vật và chúng ta cùng sống trên một Trái Đất."},{"n":10,"start":33.99,"end":37.82,"parts":[{"zh":"海边的大自然真美，空气也好。"}],"pinyin":"Hǎibiān de dàzìrán zhēn měi, kōngqì yě hǎo.","vi":"Thiên nhiên ở biển đẹp thật, không khí cũng tốt."},{"n":11,"start":37.82,"end":41.17,"parts":[{"zh":"夏天我们一起去海边玩儿吧。"}],"pinyin":"Xiàtiān wǒmen yīqǐ qù hǎibiān wánr ba.","vi":"Mùa hạ mình cùng đi biển chơi nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-25';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-25', 0, '[{"n":1,"start":0,"end":3.05,"parts":[{"zh":"晚上有什么好看的节目？"}],"pinyin":"Wǎnshang yǒu shénme hǎokàn de jiémù?","vi":"Tối có chương trình gì hay không?"},{"n":2,"start":3.05,"end":7.05,"parts":[{"zh":"有一个音乐会，还有一场篮球比赛。"}],"pinyin":"Yǒu yī chǎng yīnyuèhuì, hái yǒu yī chǎng lánqiú bǐsài.","vi":"Có một buổi hòa nhạc, và một trận bóng rổ."},{"n":3,"start":7.05,"end":11.03,"parts":[{"zh":"我最喜欢运动，常打排球和网球。"}],"pinyin":"Wǒ zuì xǐhuan yùndòng, cháng dǎ páiqiú hé wǎngqiú.","vi":"Tôi thích vận động nhất, thường chơi bóng chuyền và tennis."},{"n":4,"start":11.03,"end":14.66,"parts":[{"zh":"我们球队明天有比赛，你也来吧。"}],"pinyin":"Wǒmen qiúduì míngtiān yǒu bǐsài, nǐ yě lái ba.","vi":"Đội bóng của chúng tôi mai có trận, bạn cũng đến nhé."},{"n":5,"start":14.66,"end":17.31,"parts":[{"zh":"好！你买了新的球鞋吗？"}],"pinyin":"Hǎo! Nǐ mǎile xīn de qiúxié ma?","vi":"Được! Bạn mua giày thể thao mới chưa?"},{"n":6,"start":17.31,"end":21.479999999999997,"parts":[{"zh":"买了，朋友说很好，体育老师也这么说。"}],"pinyin":"Mǎile, péngyou shuō hěn hǎo, tǐyù lǎoshī yě zhème shuō.","vi":"Mua rồi, bạn bè khen tốt, thầy thể dục cũng nói vậy."},{"n":7,"start":21.479999999999997,"end":25.809999999999995,"parts":[{"zh":"报纸上说，那位明星要来我们学校照相。"}],"pinyin":"Bàozhǐ shang shuō, nà wèi míngxīng yào lái wǒmen xuéxiào zhàoxiàng.","vi":"Báo nói ngôi sao đó sẽ đến trường chúng ta chụp ảnh."},{"n":8,"start":25.809999999999995,"end":30.279999999999994,"parts":[{"zh":"真的吗？我要带相机去，多照几张照片。"}],"pinyin":"Zhēn de ma? Wǒ yào dài xiàngjī qù, duō zhào jǐ zhāng zhàopiàn.","vi":"Thật không? Tôi phải mang máy ảnh đi, chụp mấy tấm."},{"n":9,"start":30.279999999999994,"end":34.279999999999994,"parts":[{"zh":"我不太喜欢看电视，我喜欢看小说。"}],"pinyin":"Wǒ bú tài xǐhuan kàn diànshì, wǒ xǐhuan kàn xiǎoshuō.","vi":"Tôi không thích xem tivi lắm, tôi thích đọc tiểu thuyết."},{"n":10,"start":34.279999999999994,"end":38.029999999999994,"parts":[{"zh":"我喜欢画画儿，我想当画家。"}],"pinyin":"Wǒ xǐhuan huà huàr, wǒ xiǎng dāng huàjiā.","vi":"Tôi thích vẽ, tôi muốn thành họa sĩ."},{"n":11,"start":38.029999999999994,"end":40.98,"parts":[{"zh":"那你给我画一张图片吧！"}],"pinyin":"Nà nǐ gěi wǒ huà yī zhāng túpiàn ba!","vi":"Vậy bạn vẽ cho tôi một bức tranh nhé!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-26';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-26', 0, '[{"n":1,"start":0,"end":3.3,"parts":[{"zh":"学校的晚会什么时候开始？"}],"pinyin":"Xuéxiào de wǎnhuì shénme shíhou kāishǐ?","vi":"Tiệc tối của trường bao giờ bắt đầu?"},{"n":2,"start":3.3,"end":6.22,"parts":[{"zh":"七点，现在才六点。"}],"pinyin":"Qī diǎn, xiànzài cái liù diǎn.","vi":"Bảy giờ, bây giờ mới sáu giờ."},{"n":3,"start":6.22,"end":8.99,"parts":[{"zh":"你已经准备节目了吗？"}],"pinyin":"Nǐ yǐjīng zhǔnbèi jiémù le ma?","vi":"Bạn đã chuẩn bị tiết mục chưa?"},{"n":4,"start":8.99,"end":11.97,"parts":[{"zh":"还没有，我老是忘事儿。"}],"pinyin":"Hái méiyǒu, wǒ lǎoshì wàng shìr.","vi":"Chưa, tôi hay quên việc."},{"n":5,"start":11.97,"end":15.200000000000001,"parts":[{"zh":"你经常参加这样的活动吗？"}],"pinyin":"Nǐ jīngcháng cānjiā zhèyàng de huódòng ma?","vi":"Bạn thường xuyên tham gia hoạt động thế này à?"},{"n":6,"start":15.200000000000001,"end":19.05,"parts":[{"zh":"经常参加，一共参加过五次了。"}],"pinyin":"Jīngcháng cānjiā, yīgòng cānjiāguo wǔ cì le.","vi":"Thường xuyên tham gia, cộng lại đã năm lần."},{"n":7,"start":19.05,"end":22.47,"parts":[{"zh":"上次你唱了歌，这次又唱歌吗？"}],"pinyin":"Shàng cì nǐ chàngle gē, zhè cì yòu chànggē ma?","vi":"Lần trước bạn hát, lần này lại hát nữa à?"},{"n":8,"start":22.47,"end":26.77,"parts":[{"zh":"不，我先跳舞，然后唱歌，接着讲笑话。"}],"pinyin":"Bù, wǒ xiān tiàowǔ, ránhòu chànggē, jiēzhe jiǎng xiàohuà.","vi":"Không, tôi nhảy trước, rồi hát, tiếp theo kể chuyện cười."},{"n":9,"start":26.77,"end":30.32,"parts":[{"zh":"哈哈，真有意思。同时你会很忙。"}],"pinyin":"Hāhā, zhēn yǒu yìsi. Tóngshí nǐ huì hěn máng.","vi":"Ha ha, hay thật. Đồng thời bạn sẽ bận lắm."},{"n":10,"start":30.32,"end":33.47,"parts":[{"zh":"是啊，我很向往当明星。"}],"pinyin":"Shì a, wǒ hěn xiàngwǎng dāng míngxīng.","vi":"Ừ, tôi khao khát thành ngôi sao."},{"n":11,"start":33.47,"end":36.74,"parts":[{"zh":"为什么？为了让大家认识你吗？"}],"pinyin":"Wèishénme? Wèile ràng dàjiā rènshi nǐ ma?","vi":"Vì sao? Để mọi người biết đến bạn à?"},{"n":12,"start":36.74,"end":40.32,"parts":[{"zh":"为自己，也为喜欢我的朋友们。"}],"pinyin":"Wèi zìjǐ, yě wèi xǐhuan wǒ de péngyoumen.","vi":"Vì mình, cũng vì những người bạn thích mình."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-27';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-27', 0, '[{"n":1,"start":0,"end":2.4,"parts":[{"zh":"你为什么学汉语？"}],"pinyin":"Nǐ wèishénme xué Hànyǔ?","vi":"Vì sao bạn học tiếng Trung?"},{"n":2,"start":2.4,"end":6.5,"parts":[{"zh":"因为我喜欢中国，所以我想学汉语。"}],"pinyin":"Yīnwèi wǒ xǐhuan Zhōngguó, suǒyǐ wǒ xiǎng xué Hànyǔ.","vi":"Vì tôi yêu thích Trung Quốc, nên tôi muốn học tiếng Trung."},{"n":3,"start":6.5,"end":10,"parts":[{"zh":"虽然汉语很难，但是很有意思。"}],"pinyin":"Suīrán Hànyǔ hěn nán, dànshì hěn yǒu yìsi.","vi":"Tuy tiếng Trung khó, nhưng rất thú vị."},{"n":4,"start":10,"end":13.17,"parts":[{"zh":"对，而且汉字也很漂亮。"}],"pinyin":"Duì, érqiě Hànzì yě hěn piàoliang.","vi":"Đúng, hơn nữa chữ Hán cũng rất đẹp."},{"n":5,"start":13.17,"end":16.72,"parts":[{"zh":"如果你想说得好，必须多练习。"}],"pinyin":"Rúguǒ nǐ xiǎng shuō de hǎo, bìxū duō liànxí.","vi":"Nếu muốn nói giỏi, phải luyện tập nhiều."},{"n":6,"start":16.72,"end":19.799999999999997,"parts":[{"zh":"我知道，应该每天说。"}],"pinyin":"Wǒ zhīdào, yīnggāi měitiān shuō.","vi":"Tôi biết, nên nói mỗi ngày."},{"n":7,"start":19.799999999999997,"end":22.83,"parts":[{"zh":"只要你努力，就能学好。"}],"pinyin":"Zhǐyào nǐ nǔlì, jiù néng xué hǎo.","vi":"Chỉ cần bạn chăm chỉ thì sẽ học giỏi."},{"n":8,"start":22.83,"end":26.599999999999998,"parts":[{"zh":"可是我没有时间，只能周末学。"}],"pinyin":"Kěshì wǒ méiyǒu shíjiān, zhǐ néng zhōumò xué.","vi":"Nhưng tôi không có thời gian, chỉ học được cuối tuần."},{"n":9,"start":26.599999999999998,"end":29.43,"parts":[{"zh":"那就周末多学一点儿。"}],"pinyin":"Nà jiù zhōumò duō xué yīdiǎnr.","vi":"Thì cuối tuần học nhiều một chút."},{"n":10,"start":29.43,"end":33.26,"parts":[{"zh":"好，或者每天晚上学半小时。"}],"pinyin":"Hǎo, huòzhě měitiān wǎnshang xué bàn xiǎoshí.","vi":"Được, hoặc mỗi tối học nửa giờ."},{"n":11,"start":33.26,"end":35.46,"parts":[{"zh":"这个办法好！"}],"pinyin":"Zhège bànfǎ hǎo!","vi":"Cách này hay!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-28';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-28', 0, '[{"n":1,"start":0,"end":2.85,"parts":[{"zh":"快点儿，电影要开始了！"}],"pinyin":"Kuài diǎnr, diànyǐng yào kāishǐ le!","vi":"Nhanh lên, phim sắp chiếu rồi!"},{"n":2,"start":2.85,"end":6.2,"parts":[{"zh":"不行，我找不到票了，怎么办？"}],"pinyin":"Bùxíng, wǒ zhǎo budào piào le, zěnme bàn?","vi":"Không được, tôi không tìm thấy vé rồi, làm sao bây giờ?"},{"n":3,"start":6.2,"end":9.780000000000001,"parts":[{"zh":"可能在你书包里，也许在家里。"}],"pinyin":"Kěnéng zài nǐ de shūbāo lǐ, yěxǔ zài jiā lǐ.","vi":"Có thể trong cặp bạn, hoặc ở nhà."},{"n":4,"start":9.780000000000001,"end":13.760000000000002,"parts":[{"zh":"找到了！在这儿。可是马上要开始了。"}],"pinyin":"Zhǎodào le! Zài zhèr. Kěshì mǎshàng yào kāishǐ le.","vi":"Thấy rồi! Ở đây. Nhưng sắp bắt đầu mất rồi."},{"n":5,"start":13.760000000000002,"end":16.560000000000002,"parts":[{"zh":"那就快跑，还来得及。"}],"pinyin":"Nà jiù kuài pǎo, hái láidéjí.","vi":"Vậy thì chạy nhanh, vẫn kịp."},{"n":6,"start":16.560000000000002,"end":19.730000000000004,"parts":[{"zh":"你觉得这部电影怎么样？"}],"pinyin":"Nǐ juéde zhè bù diànyǐng zěnmeyàng?","vi":"Bạn thấy bộ phim này thế nào?"},{"n":7,"start":19.730000000000004,"end":23.000000000000004,"parts":[{"zh":"挺好，比我想的好像好一些。"}],"pinyin":"Tǐng hǎo, bǐ wǒ xiǎng de hǎoxiàng hǎo yīxiē.","vi":"Khá hay, hình như hơn tôi nghĩ một chút."},{"n":8,"start":23.000000000000004,"end":26.880000000000003,"parts":[{"zh":"如果有便宜票的话，我们以后常来。"}],"pinyin":"Rúguǒ yǒu piányi piào de huà, wǒmen yǐhòu cháng lái.","vi":"Nếu có vé rẻ thì sau này mình hay đến."},{"n":9,"start":26.880000000000003,"end":30.330000000000002,"parts":[{"zh":"好。其他的时间你看什么电影？"}],"pinyin":"Hǎo. Qítā de shíjiān nǐ kàn shénme diànyǐng?","vi":"Được. Thời gian khác bạn xem phim gì?"},{"n":10,"start":30.330000000000002,"end":34.410000000000004,"parts":[{"zh":"我什么都看，不像你只看爱情电影。"}],"pinyin":"Wǒ shénme dōu kàn, bú xiàng nǐ zhǐ kàn àiqíng diànyǐng.","vi":"Tôi xem cả, không như bạn chỉ xem phim tình cảm."},{"n":11,"start":34.410000000000004,"end":38.53,"parts":[{"zh":"哈哈，还是在家看电视不如电影院好。"}],"pinyin":"Hāhā, háishì zài jiā kàn diànshì bùrú diànyǐngyuàn hǎo.","vi":"Ha ha, dù sao xem tivi ở nhà vẫn không bằng rạp phim."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-29';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-29', 0, '[{"n":1,"start":0,"end":2.38,"parts":[{"zh":"你的头发怎么了？"}],"pinyin":"Nǐ de tóufa zěnme le?","vi":"Tóc bạn sao thế?"},{"n":2,"start":2.38,"end":5.71,"parts":[{"zh":"我自己剪头发，剪坏了。"}],"pinyin":"Wǒ zìjǐ jiǎn tóufa, jiǎn huài le.","vi":"Tôi tự cắt tóc, cắt hỏng rồi."},{"n":3,"start":5.71,"end":9.36,"parts":[{"zh":"你不太会剪，自己去理发店弄吧。"}],"pinyin":"Nǐ bú tài huì jiǎn, zìjǐ qù lǐfàdiàn nòng ba.","vi":"Bạn không rành cắt, tự đến tiệm cắt tóc xử lý đi."},{"n":4,"start":9.36,"end":12.51,"parts":[{"zh":"我不太想去，要排队。"}],"pinyin":"Wǒ bú tài xiǎng qù, yào páiduì.","vi":"Tôi không muốn đi lắm, phải xếp hàng."},{"n":5,"start":12.51,"end":15.129999999999999,"parts":[{"zh":"只排十分钟，很快。"}],"pinyin":"Zhǐ pái shí fēnzhōng, hěn kuài.","vi":"Chỉ xếp mười phút thôi, nhanh lắm."},{"n":6,"start":15.129999999999999,"end":20.21,"parts":[{"zh":"好吧。我出生的时候头发是黑的，现在变黄了。"}],"pinyin":"Hǎo ba. Wǒ chūshēng de shíhou tóufa shì hēi de, xiànzài biàn huáng le.","vi":"Được. Lúc tôi sinh ra tóc đen, giờ vàng rồi."},{"n":7,"start":20.21,"end":24.01,"parts":[{"zh":"头发会慢慢变成别的颜色，正常。"}],"pinyin":"Tóufa huì mànmàn biànchéng biéde yánsè, zhèngcháng.","vi":"Tóc sẽ dần thành màu khác, bình thường."},{"n":8,"start":24.01,"end":27.89,"parts":[{"zh":"我的手机掉了，出现了个大问题。"}],"pinyin":"Wǒ de shǒujī diào le, chūxiànle ge dà wèntí.","vi":"Điện thoại tôi rơi, xuất hiện vấn đề lớn."},{"n":9,"start":27.89,"end":31.22,"parts":[{"zh":"你给出租车公司发短信了吗？"}],"pinyin":"Nǐ gěi chūzūchē gōngsī fā duǎnxìn le ma?","vi":"Bạn gửi tin nhắn cho công ty taxi chưa?"},{"n":10,"start":31.22,"end":35.39,"parts":[{"zh":"发了，还没有回答。明天我们几点出发？"}],"pinyin":"Fā le, hái méiyǒu huídá. Míngtiān wǒmen jǐ diǎn chūfā?","vi":"Gửi rồi, vẫn chưa được trả lời. Mai mình mấy giờ khởi hành?"},{"n":11,"start":35.39,"end":39.47,"parts":[{"zh":"九点。你先等回答，然后重新买一个。"}],"pinyin":"Jiǔ diǎn. Nǐ xiān děng huídá, ránhòu chóngxīn mǎi yī ge.","vi":"Chín giờ. Bạn đợi trả lời trước, rồi mua lại cái mới."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-30';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-30', 0, '[{"n":1,"start":0,"end":2.45,"parts":[{"zh":"你的作业完成了吗？"}],"pinyin":"Nǐ de zuòyè wánchéng le ma?","vi":"Bài tập bạn hoàn thành chưa?"},{"n":2,"start":2.45,"end":5.68,"parts":[{"zh":"完成了，老师已经接受了。"}],"pinyin":"Wánchéng le, lǎoshī yǐjīng jiēshòu le.","vi":"Xong rồi, thầy đã nhận."},{"n":3,"start":5.68,"end":7.93,"parts":[{"zh":"你选好课了吗？"}],"pinyin":"Nǐ xuǎn hǎo kè le ma?","vi":"Bạn chọn môn xong chưa?"},{"n":4,"start":7.93,"end":11.2,"parts":[{"zh":"选了，我选了科学和历史。"}],"pinyin":"Xuǎn le, wǒ xuǎnle kēxué hé lìshǐ.","vi":"Rồi, tôi chọn khoa học và lịch sử."},{"n":5,"start":11.2,"end":14.469999999999999,"parts":[{"zh":"等你长大以后，你想做什么？"}],"pinyin":"Děng nǐ zhǎngdà yǐhòu, nǐ xiǎng zuò shénme?","vi":"Khi lớn lên bạn muốn làm gì?"},{"n":6,"start":14.469999999999999,"end":17.99,"parts":[{"zh":"我想养一只狗，开一家小店。"}],"pinyin":"Wǒ xiǎng yǎng yī zhī gǒu, kāi yī jiā xiǎo diàn.","vi":"Tôi muốn nuôi một con chó, mở một cửa hàng nhỏ."},{"n":7,"start":17.99,"end":20.74,"parts":[{"zh":"你把书装进包里了吗？"}],"pinyin":"Nǐ bǎ shū zhuāng jìn bāo lǐ le ma?","vi":"Bạn bỏ sách vào cặp chưa?"},{"n":8,"start":20.74,"end":23.84,"parts":[{"zh":"装了，还装了两瓶水。"}],"pinyin":"Zhuāng le, hái zhuāngle liǎng píng shuǐ.","vi":"Bỏ rồi, còn bỏ cả hai chai nước."},{"n":9,"start":23.84,"end":25.92,"parts":[{"zh":"背课文难吗？"}],"pinyin":"Bèi kèwén nán ma?","vi":"Học thuộc bài khó không?"},{"n":10,"start":25.92,"end":30.5,"parts":[{"zh":"难，我要背十遍。我想通过考试，提高成绩。"}],"pinyin":"Nán, wǒ yào bèi shí biàn. Wǒ xiǎng tōngguò kǎoshì, tígāo chéngjì.","vi":"Khó, tôi phải học mười lần. Tôi muốn qua được kỳ thi, nâng điểm số."},{"n":11,"start":30.5,"end":33.83,"parts":[{"zh":"加油！你的想法一定会实现。"}],"pinyin":"Jiāyóu! Nǐ de xiǎngfǎ yīdìng huì shíxiàn.","vi":"Cố lên! Suy nghĩ của bạn nhất định sẽ thành hiện thực."},{"n":12,"start":33.83,"end":37.66,"parts":[{"zh":"谢谢！我也要照顾好自己的身体。"}],"pinyin":"Xièxie! Wǒ yě yào zhàogù hǎo zìjǐ de shēntǐ.","vi":"Cảm ơn! Tôi cũng phải chăm sóc tốt sức khỏe của mình."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-31';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-31', 0, '[{"n":1,"start":0,"end":5.47,"parts":[{"zh":"做对话练习的时候，我总是不知道说什么，真不好意思。"}],"pinyin":"Zuò duìhuà liànxí de shíhou, wǒ zǒngshì bù zhīdào shuō shénme, zhēn bù hǎoyìsi.","vi":"Lúc luyện hội thoại, tôi cứ không biết nói gì, ngại thật."},{"n":2,"start":5.47,"end":9.8,"parts":[{"zh":"没关系，你先听我讲话，然后你回答。"}],"pinyin":"Méi guānxi, nǐ xiān tīng wǒ jiǎnghuà, ránhòu nǐ huídá.","vi":"Không sao, bạn nghe tôi nói trước, rồi bạn trả lời."},{"n":3,"start":9.8,"end":13.600000000000001,"parts":[{"zh":"好，我们商量一下明天讨论的题目吧。"}],"pinyin":"Hǎo, wǒmen shāngliang yīxià míngtiān tǎolùn de tímù ba.","vi":"Được, mình bàn về chủ đề thảo luận ngày mai nhé."},{"n":4,"start":13.600000000000001,"end":17.85,"parts":[{"zh":"我有一个请求：你把作业借我看看，好吗？"}],"pinyin":"Wǒ yǒu yī ge qǐngqiú: Nǐ bǎ zuòyè jiè wǒ kànkan, hǎo ma?","vi":"Tôi có một lời nhờ: cho tôi mượn bài tập xem nhé?"},{"n":5,"start":17.85,"end":21.150000000000002,"parts":[{"zh":"不行，老师要求我们自己写。"}],"pinyin":"Bùxíng, lǎoshī yāoqiú wǒmen zìjǐ xiě.","vi":"Không được, thầy yêu cầu tự viết."},{"n":6,"start":21.150000000000002,"end":24.730000000000004,"parts":[{"zh":"那我求你帮我把生词读一遍吧。"}],"pinyin":"Nà wǒ qiú nǐ bāng wǒ bǎ shēngcí dú yī biàn ba.","vi":"Vậy tôi nhờ bạn đọc từ mới một lần giúp tôi nhé."},{"n":7,"start":24.730000000000004,"end":27.080000000000005,"parts":[{"zh":"这个可以答应你。"}],"pinyin":"Zhège kěyǐ dāying nǐ.","vi":"Cái này thì đáp ứng được."},{"n":8,"start":27.080000000000005,"end":30.710000000000004,"parts":[{"zh":"老师通知我们，明天交作文。"}],"pinyin":"Lǎoshī tōngzhī wǒmen, míngtiān jiāo zuòwén.","vi":"Thầy thông báo chúng ta mai nộp bài văn."},{"n":9,"start":30.710000000000004,"end":33.74,"parts":[{"zh":"我知道了，谢谢你的说明。"}],"pinyin":"Wǒ zhīdào le, xièxie nǐ de shuōmíng.","vi":"Tôi biết rồi, cảm ơn bạn đã giải thích."},{"n":10,"start":33.74,"end":37.39,"parts":[{"zh":"老师表示，欢迎大家提意见。"}],"pinyin":"Lǎoshī biǎoshì, huānyíng dàjiā tí yìjiàn.","vi":"Thầy tỏ ý, hoan nghênh mọi người nêu ý kiến."},{"n":11,"start":37.39,"end":40.27,"parts":[{"zh":"那我说一点儿我的看法。"}],"pinyin":"Nà wǒ shuō yīdiǎnr wǒ de kànfǎ.","vi":"Vậy tôi nói một chút ý kiến của mình."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-32';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-32', 0, '[{"n":1,"start":0,"end":2.9,"parts":[{"zh":"上周的晚会你去看了吗？"}],"pinyin":"Shàng zhōu de wǎnhuì nǐ qù kàn le ma?","vi":"Tuần trước buổi tiệc tối bạn có đi xem không?"},{"n":2,"start":2.9,"end":7,"parts":[{"zh":"去了，下周我还想参加这样的活动。"}],"pinyin":"Qù le, xià zhōu wǒ hái xiǎng cānjiā zhèyàng de huódòng.","vi":"Đi rồi, tuần sau tôi còn muốn tham gia hoạt động thế này."},{"n":3,"start":7,"end":10.15,"parts":[{"zh":"你对这本书的看法是什么？"}],"pinyin":"Nǐ duì zhè běn shū de kànfǎ shì shénme?","vi":"Quan điểm của bạn về cuốn sách này là gì?"},{"n":4,"start":10.15,"end":14.45,"parts":[{"zh":"我认为写得很好，作者的态度很认真。"}],"pinyin":"Wǒ rènwéi xiě de hěn hǎo, zuòzhě de tàidù hěn rènzhēn.","vi":"Tôi cho rằng viết rất hay, tác giả có thái độ nghiêm túc."},{"n":5,"start":14.45,"end":18.28,"parts":[{"zh":"我的观点有点儿不同，我觉得一般。"}],"pinyin":"Wǒ de guāndiǎn yǒudiǎnr bùtóng, wǒ juéde yībān.","vi":"Quan điểm tôi hơi khác, tôi thấy bình thường."},{"n":6,"start":18.28,"end":22.26,"parts":[{"zh":"每个人的想法不一样，这很有道理。"}],"pinyin":"Měi ge rén de xiǎngfǎ bù yīyàng, zhè hěn yǒu dàolǐ.","vi":"Suy nghĩ mỗi người một khác, điều này rất hợp lý."},{"n":7,"start":22.26,"end":25.41,"parts":[{"zh":"对，我们要关心别人的想法。"}],"pinyin":"Duì, wǒmen yào guānxīn biérén de xiǎngfǎ.","vi":"Đúng, chúng ta phải quan tâm đến suy nghĩ của người khác."},{"n":8,"start":25.41,"end":29.810000000000002,"parts":[{"zh":"老师说话的时候，我们点头表示同意。"}],"pinyin":"Lǎoshī shuōhuà de shíhou, wǒmen diǎntóu biǎoshì tóngyì.","vi":"Khi thầy cô nói, chúng ta gật đầu tỏ ý đồng ý."},{"n":9,"start":29.810000000000002,"end":33.440000000000005,"parts":[{"zh":"我忽然想起小时候的一件事儿了。"}],"pinyin":"Wǒ hūrán xiǎngqǐ xiǎoshíhou de yī jiàn shìr le.","vi":"Bỗng tôi nhớ lại một chuyện hồi nhỏ."},{"n":10,"start":33.440000000000005,"end":36.27,"parts":[{"zh":"什么事？说来听听。"}],"pinyin":"Shénme shì? Shuō lái tīngtīng.","vi":"Chuyện gì? Kể nghe đi."},{"n":11,"start":36.27,"end":40.300000000000004,"parts":[{"zh":"我相信，只要努力，日子会越来越好。"}],"pinyin":"Wǒ xiāngxìn, zhǐyào nǔlì, rìzi huì yuèláiyuè hǎo.","vi":"Tôi tin, chỉ cần chăm chỉ thì cuộc sống sẽ ngày càng tốt hơn."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-33';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-33', 0, '[{"n":1,"start":0,"end":3.05,"parts":[{"zh":"好久不见，你变化真大！"}],"pinyin":"Hǎojiǔ bújiàn, nǐ biànhuà zhēn dà!","vi":"Lâu quá không gặp, bạn thay đổi nhiều thật!"},{"n":2,"start":3.05,"end":7.05,"parts":[{"zh":"是啊，小时候我很瘦，现在胖多了。"}],"pinyin":"Shì a, xiǎoshíhou wǒ hěn shòu, xiànzài pàng duōle.","vi":"Ừ, hồi nhỏ tôi gầy lắm, giờ mập hơn nhiều."},{"n":3,"start":7.05,"end":9.6,"parts":[{"zh":"好多事情都变了。"}],"pinyin":"Hǎo duō shìqing dōu biàn le.","vi":"Nhiều chuyện đã thay đổi."},{"n":4,"start":9.6,"end":12.68,"parts":[{"zh":"你早就认识我的哥哥吧？"}],"pinyin":"Nǐ zǎojiù rènshi wǒ de gēge ba?","vi":"Bạn quen anh tôi từ lâu rồi đúng không?"},{"n":5,"start":12.68,"end":15.48,"parts":[{"zh":"对，他是我常见的朋友。"}],"pinyin":"Duì, tā shì wǒ cháng jiàn de péngyou.","vi":"Đúng, anh ấy là bạn tôi hay gặp."},{"n":6,"start":15.48,"end":18.88,"parts":[{"zh":"忽然见到老朋友，真高兴！"}],"pinyin":"Hūrán jiàndào lǎo péngyou, zhēn gāoxìng!","vi":"Bỗng gặp bạn cũ, vui thật!"},{"n":7,"start":18.88,"end":22.48,"parts":[{"zh":"我永远记得我们一起学习的日子。"}],"pinyin":"Wǒ yǒngyuǎn jìde wǒmen yīqǐ xuéxí de rìzi.","vi":"Tôi mãi nhớ những ngày cùng học với nhau."},{"n":8,"start":22.48,"end":26.11,"parts":[{"zh":"那些日子，我们一生都不会忘。"}],"pinyin":"Nàxiē rìzi, wǒmen yīshēng dōu bú huì wàng.","vi":"Những ngày đó, cả đời chúng ta không quên."},{"n":9,"start":26.11,"end":29.71,"parts":[{"zh":"这个词很常用，我听过许多次了。"}],"pinyin":"Zhège cí hěn chángyòng, wǒ tīngguo xǔduō cì le.","vi":"Từ này hay dùng lắm, tôi nghe nhiều lần rồi."},{"n":10,"start":29.71,"end":33.04,"parts":[{"zh":"学汉语需要大量的练习。"}],"pinyin":"Xué Hànyǔ xūyào dàliàng de liànxí.","vi":"Học tiếng Trung cần nhiều luyện tập."},{"n":11,"start":33.04,"end":35.589999999999996,"parts":[{"zh":"对，多么努力都不够啊！"}],"pinyin":"Duì, duōme nǔlì dōu bú gòu a!","vi":"Đúng, chăm chỉ bao nhiêu cũng chưa đủ!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-34';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-34', 0, '[{"n":1,"start":0,"end":2.67,"parts":[{"zh":"你弟弟的个子多高？"}],"pinyin":"Nǐ dìdi de gèzi duō gāo?","vi":"Em trai bạn cao bao nhiêu?"},{"n":2,"start":2.67,"end":5.32,"parts":[{"zh":"一米八，个子很高。"}],"pinyin":"Yī mǐ bā, gèzi hěn gāo.","vi":"Một mét tám, người rất cao."},{"n":3,"start":5.32,"end":7.7700000000000005,"parts":[{"zh":"他长得什么样子？"}],"pinyin":"Tā zhǎng de shénme yàngzi?","vi":"Anh ấy trông như thế nào?"},{"n":4,"start":7.7700000000000005,"end":11.690000000000001,"parts":[{"zh":"眼睛很大，头发不长不短，正好。"}],"pinyin":"Yǎnjing hěn dà, tóufa bù cháng bù duǎn, zhènghǎo.","vi":"Mắt to, tóc không dài không ngắn, vừa phải."},{"n":5,"start":11.690000000000001,"end":14.46,"parts":[{"zh":"你的房间大小怎么样？"}],"pinyin":"Nǐ de fángjiān dàxiǎo zěnme yàng?","vi":"Phòng bạn to nhỏ thế nào?"},{"n":6,"start":14.46,"end":17.79,"parts":[{"zh":"不大，但是什么条件都有。"}],"pinyin":"Bú dà, dànshì shénme tiáojiàn dōu yǒu.","vi":"Không to, nhưng điều kiện gì cũng có."},{"n":7,"start":17.79,"end":20.869999999999997,"parts":[{"zh":"昨天的比赛，结果怎么样？"}],"pinyin":"Zuótiān de bǐsài, jiéguǒ zěnme yàng?","vi":"Trận đấu hôm qua, kết quả thế nào?"},{"n":8,"start":20.869999999999997,"end":24.22,"parts":[{"zh":"我们赢了，这是最好的结果。"}],"pinyin":"Wǒmen yíng le, zhè shì zuì hǎo de jiéguǒ.","vi":"Chúng tôi thắng, đó là kết quả tốt nhất."},{"n":9,"start":24.22,"end":27.25,"parts":[{"zh":"你学汉语的目的是什么？"}],"pinyin":"Nǐ xué Hànyǔ de mùdì shì shénme?","vi":"Mục đích học tiếng Trung của bạn là gì?"},{"n":10,"start":27.25,"end":32,"parts":[{"zh":"我想了解中国文化，每个方面都想了解。"}],"pinyin":"Wǒ xiǎng liǎojiě Zhōngguó wénhuà, měi ge fāngmiàn dōu xiǎng liǎojiě.","vi":"Tôi muốn hiểu văn hóa Trung Quốc, khía cạnh nào cũng muốn hiểu."},{"n":11,"start":32,"end":35.77,"parts":[{"zh":"从不同的角度看，问题就不一样了。"}],"pinyin":"Cóng bùtóng de jiǎodù kàn, wèntí jiù bù yīyàng le.","vi":"Nhìn từ góc độ khác nhau thì vấn đề đã khác."},{"n":12,"start":35.77,"end":39.190000000000005,"parts":[{"zh":"对，每个人都有自己的特点。"}],"pinyin":"Duì, měi ge rén dōu yǒu zìjǐ de tèdiǎn.","vi":"Đúng, mỗi người đều có đặc điểm riêng."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-35';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-35', 0, '[{"n":1,"start":0,"end":2.67,"parts":[{"zh":"名单上有你的名字！"}],"pinyin":"Míngdān shang yǒu nǐ de míngzi!","vi":"Trong danh sách có tên bạn!"},{"n":2,"start":2.67,"end":5.32,"parts":[{"zh":"真的吗？什么名单？"}],"pinyin":"Zhēn de ma? Shénme míngdān?","vi":"Thật không? Danh sách gì?"},{"n":3,"start":5.32,"end":9.370000000000001,"parts":[{"zh":"参加比赛的名单，你的汉语水平很高。"}],"pinyin":"Cānjiā bǐsài de míngdān, nǐ de Hànyǔ shuǐpíng hěn gāo.","vi":"Danh sách dự thi, trình độ tiếng Trung của bạn cao lắm."},{"n":4,"start":9.370000000000001,"end":13.170000000000002,"parts":[{"zh":"谢谢，我对这次比赛很有信心。"}],"pinyin":"Xièxie, wǒ duì zhè cì bǐsài hěn yǒu xìnxīn.","vi":"Cảm ơn, tôi rất tự tin về kỳ thi lần này."},{"n":5,"start":13.170000000000002,"end":15.370000000000001,"parts":[{"zh":"这是什么意思？"}],"pinyin":"Zhè shì shénme yìsi?","vi":"Cái này nghĩa là gì?"},{"n":6,"start":15.370000000000001,"end":19.17,"parts":[{"zh":"意思是我可以和大家一起比赛了。"}],"pinyin":"Yìsi shì wǒ kěyǐ hé dàjiā yīqǐ bǐsài le.","vi":"Nghĩa là tôi có thể cùng mọi người thi rồi."},{"n":7,"start":19.17,"end":21.840000000000003,"parts":[{"zh":"学汉语有什么好处？"}],"pinyin":"Xué Hànyǔ yǒu shénme hǎochù?","vi":"Học tiếng Trung có ích gì?"},{"n":8,"start":21.840000000000003,"end":26.560000000000002,"parts":[{"zh":"好处很多，坏处只有一个：要花很多时间。"}],"pinyin":"Hǎochù hěn duō, huàichù zhǐ yǒu yī ge: Yào huā hěn duō shíjiān.","vi":"Lợi nhiều, hại chỉ một: tốn rất nhiều thời gian."},{"n":9,"start":26.560000000000002,"end":29.040000000000003,"parts":[{"zh":"你的理想是什么？"}],"pinyin":"Nǐ de lǐxiǎng shì shénme?","vi":"Lý tưởng của bạn là gì?"},{"n":10,"start":29.040000000000003,"end":33.14,"parts":[{"zh":"我希望做一个好人，多做点儿好事。"}],"pinyin":"Wǒ xīwàng zuò yī ge hǎorén, duō zuò diǎnr hǎoshì.","vi":"Tôi mong làm người tốt, làm nhiều việc tốt."},{"n":11,"start":33.14,"end":37.12,"parts":[{"zh":"你真不错。好的行为会影响很多人。"}],"pinyin":"Nǐ zhēn búcuò. Hǎo de xíngwéi huì yǐngxiǎng hěn duō rén.","vi":"Bạn thật tốt. Hành động tốt sẽ ảnh hưởng đến nhiều người."},{"n":12,"start":37.12,"end":41.97,"parts":[{"zh":"对，好的行为比说话更有作用，我们要有行动。"}],"pinyin":"Duì, hǎo de xíngwéi bǐ shuōhuà gèng yǒu zuòyòng, wǒmen yào yǒu xíngdòng.","vi":"Đúng, hành động tốt hơn nói, chúng ta phải hành động."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-36';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-36', 0, '[{"n":1,"start":0,"end":3.3,"parts":[{"zh":"听说你要报名参加汉语班？"}],"pinyin":"Tīngshuō nǐ yào bàomíng cānjiā Hànyǔ bān?","vi":"Nghe nói bạn định đăng ký lớp tiếng Trung?"},{"n":2,"start":3.3,"end":6.75,"parts":[{"zh":"对，我想提高我的语言水平。"}],"pinyin":"Duì, wǒ xiǎng tígāo wǒ de yǔyán shuǐpíng.","vi":"Đúng, tôi muốn nâng trình độ ngôn ngữ của mình."},{"n":3,"start":6.75,"end":10.55,"parts":[{"zh":"高中的时候，我上课常常不听讲。"}],"pinyin":"Gāozhōng de shíhou, wǒ shàngkè chángcháng bù tīngjiǎng.","vi":"Hồi cấp ba, tôi thường không nghe giảng."},{"n":4,"start":10.55,"end":15.25,"parts":[{"zh":"现在老师写在黑板上的词，你都记下来吧。"}],"pinyin":"Xiànzài lǎoshī xiě zài hēibǎn shang de cí, nǐ dōu jì xiàlái ba.","vi":"Bây giờ những từ thầy viết trên bảng, bạn đều ghi lại nhé."},{"n":5,"start":15.25,"end":18.9,"parts":[{"zh":"对，这样学很有用。你买新鞋了吗？"}],"pinyin":"Duì, zhèyàng xué hěn yǒuyòng. Nǐ mǎi xīn xié le ma?","vi":"Đúng, học thế này rất hữu ích. Bạn mua giày mới chưa?"},{"n":6,"start":18.9,"end":22.75,"parts":[{"zh":"买了，还买了一件大衣和一块手表。"}],"pinyin":"Mǎi le, hái mǎile yī jiàn dàyī hé yī kuài shǒubiǎo.","vi":"Mua rồi, còn mua cả áo khoác và đồng hồ."},{"n":7,"start":22.75,"end":25.48,"parts":[{"zh":"手表是送人的礼物吗？"}],"pinyin":"Shǒubiǎo shì sòng rén de lǐwù ma?","vi":"Đồng hồ là quà tặng ai à?"},{"n":8,"start":25.48,"end":29.03,"parts":[{"zh":"不是，是送给自己的生日礼物。"}],"pinyin":"Bú shì, shì sòng gěi zìjǐ de shēngrì lǐwù.","vi":"Không, là quà sinh nhật cho chính mình."},{"n":9,"start":29.03,"end":31.380000000000003,"parts":[{"zh":"那张卡是什么？"}],"pinyin":"Nà zhāng kǎ shì shénme?","vi":"Cái thẻ đó là gì?"},{"n":10,"start":31.380000000000003,"end":35.38,"parts":[{"zh":"是电话卡。瓶子里是油，送给妈妈的。"}],"pinyin":"Shì diànhuàkǎ. Píngzi lǐ shì yóu, sòng gěi māma de.","vi":"Là thẻ điện thoại. Trong chai là dầu, tặng mẹ."},{"n":11,"start":35.38,"end":38.21,"parts":[{"zh":"你家的洗衣机修好了吗？"}],"pinyin":"Nǐ jiā de xǐyījī xiū hǎo le ma?","vi":"Máy giặt nhà bạn sửa xong chưa?"},{"n":12,"start":38.21,"end":41.84,"parts":[{"zh":"修好了，现在什么都方便了。"}],"pinyin":"Xiū hǎo le, xiànzài shénme dōu fāngbiàn le.","vi":"Sửa xong rồi, giờ mọi thứ đều tiện."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-37';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-37', 0, '[{"n":1,"start":0,"end":3.05,"parts":[{"zh":"老王，听说你是外地来的？"}],"pinyin":"Lǎo Wáng, tīngshuō nǐ shì wàidì lái de?","vi":"Lão Vương, nghe nói bạn từ nơi khác đến?"},{"n":2,"start":3.05,"end":7.97,"parts":[{"zh":"对，我从南方的一个省来，坐了十个小时的火车。"}],"pinyin":"Duì, wǒ cóng nánfāng de yī ge shěng lái, zuòle shí ge xiǎoshí de huǒchē.","vi":"Đúng, tôi từ một tỉnh miền Nam ra, đi tàu mười tiếng."},{"n":3,"start":7.97,"end":11.719999999999999,"parts":[{"zh":"欢迎欢迎！我带你参观我们的学校。"}],"pinyin":"Huānyíng huānyíng! Wǒ dài nǐ cānguān wǒmen de xuéxiào.","vi":"Chào mừng! Tôi dẫn bạn tham quan trường."},{"n":4,"start":11.719999999999999,"end":16.189999999999998,"parts":[{"zh":"太好了，学校的墙上画着很好看的画儿。"}],"pinyin":"Tài hǎole, xuéxiào de qiáng shang huàzhe hěn hǎokàn de huàr.","vi":"Tốt quá, tường trường vẽ những bức tranh đẹp."},{"n":5,"start":16.189999999999998,"end":19.889999999999997,"parts":[{"zh":"明天市长要来我们市参加活动。"}],"pinyin":"Míngtiān shìzhǎng yào lái wǒmen shì cānjiā huódòng.","vi":"Mai thị trưởng sẽ đến thành phố chúng ta tham gia hoạt động."},{"n":6,"start":19.889999999999997,"end":23.769999999999996,"parts":[{"zh":"真的吗？全国的电视都会放新闻吧。"}],"pinyin":"Zhēn de ma? Quánguó de diànshì dōu huì fàng xīnwén ba.","vi":"Thật không? Truyền hình cả nước sẽ phát tin tức chứ."},{"n":7,"start":23.769999999999996,"end":27.249999999999996,"parts":[{"zh":"会。你要参加运动场上的比赛吗？"}],"pinyin":"Huì. Nǐ yào cānjiā yùndòngchǎng shang de bǐsài ma?","vi":"Có. Bạn định tham dự trận đấu ở sân vận động không?"},{"n":8,"start":27.249999999999996,"end":31.4,"parts":[{"zh":"参加，我要打篮球，用全身的力气！"}],"pinyin":"Cānjiā, wǒ yào dǎ lánqiú, yòng quánshēn de lìqi!","vi":"Tham dự, tôi sẽ chơi bóng rổ, dùng hết sức toàn thân!"},{"n":9,"start":31.4,"end":34.8,"parts":[{"zh":"加油！我当司机，开车送你去。"}],"pinyin":"Jiāyóu! Wǒ dāng sījī, kāichē sòng nǐ qù.","vi":"Cố lên! Tôi làm tài xế, lái xe chở bạn đi."},{"n":10,"start":34.8,"end":39.05,"parts":[{"zh":"谢谢！路上行人多，你开车要慢点儿。"}],"pinyin":"Xièxie! Lùshang xíngrén duō, nǐ kāichē yào màndiǎnr.","vi":"Cảm ơn! Trên đường người đi bộ nhiều, bạn lái chậm thôi."},{"n":11,"start":39.05,"end":42.4,"parts":[{"zh":"知道了，小王也和我们一起去。"}],"pinyin":"Zhīdào le, Xiǎo Wáng yě hé wǒmen yīqǐ qù.","vi":"Rồi, Tiểu Vương cũng đi cùng chúng ta."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-38';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-38', 0, '[{"n":1,"start":0,"end":3.7,"parts":[{"zh":"谢谢你帮助我复习，我懂了很多。"}],"pinyin":"Xièxie nǐ bāngzhù wǒ fùxí, wǒ dǒngle hěn duō.","vi":"Cảm ơn bạn giúp tôi ôn bài, tôi hiểu nhiều hơn."},{"n":2,"start":3.7,"end":8.030000000000001,"parts":[{"zh":"你学得很快，你一定会成为好学生。"}],"pinyin":"Nǐ xué de hěn kuài, nǐ yīdìng huì chéngwéi hǎo xuésheng.","vi":"Bạn học nhanh lắm, bạn chắc chắn sẽ thành học sinh giỏi."},{"n":3,"start":8.030000000000001,"end":11.010000000000002,"parts":[{"zh":"你打算什么时候出国？"}],"pinyin":"Nǐ dǎsuàn shénme shíhou chūguó?","vi":"Bạn định khi nào xuất ngoại?"},{"n":4,"start":11.010000000000002,"end":14.71,"parts":[{"zh":"下个月出国，两年以后回国。"}],"pinyin":"Xià ge yuè chūguó, liǎng nián yǐhòu huíguó.","vi":"Tháng sau xuất ngoại, hai năm sau trở về nước."},{"n":5,"start":14.71,"end":16.94,"parts":[{"zh":"你要当翻译吗？"}],"pinyin":"Nǐ yào dāng fānyì ma?","vi":"Bạn muốn làm phiên dịch à?"},{"n":6,"start":16.94,"end":21.41,"parts":[{"zh":"对。可是一开始，在国外可能有点儿难受。"}],"pinyin":"Duì. Kěshì yī kāishǐ, zài guówài kěnéng yǒudiǎnr nánshòu.","vi":"Đúng. Nhưng lúc đầu ở nước ngoài có thể hơi khó chịu."},{"n":7,"start":21.41,"end":24.91,"parts":[{"zh":"别难过，你会受到大家的帮助。"}],"pinyin":"Bié nánguò, nǐ huì shòudào dàjiā de bāngzhù.","vi":"Đừng buồn, bạn sẽ nhận được sự giúp đỡ của mọi người."},{"n":8,"start":24.91,"end":29.36,"parts":[{"zh":"你说得对，我把心事放下，就不难受了。"}],"pinyin":"Nǐ shuō de duì, wǒ bǎ xīnshì fàngxià, jiù bù nánshòu le.","vi":"Bạn nói đúng, tôi buông phiền muộn xuống là hết khó chịu."},{"n":9,"start":29.36,"end":31.939999999999998,"parts":[{"zh":"那个国家流行什么？"}],"pinyin":"Nàge guójiā liúxíng shénme?","vi":"Ở nước đó thịnh hành gì?"},{"n":10,"start":31.939999999999998,"end":36.239999999999995,"parts":[{"zh":"流行喝咖啡，我发现了好多咖啡店。"}],"pinyin":"Liúxíng hē kāfēi, wǒ fāxiànle hǎo duō kāfēidiàn.","vi":"Thịnh hành uống cà phê, tôi thấy nhiều quán cà phê lắm."},{"n":11,"start":36.239999999999995,"end":42.88999999999999,"parts":[{"zh":"和朋友分开的时候，记得常常联系。手机要关机的时候，先发个信息。"}],"pinyin":"Hé péngyou fēnkāi de shíhou, jìde chángcháng liánxì. Shǒujī yào guānjī de shíhou, xiān fā ge xìnxī.","vi":"Khi chia tay bạn bè, nhớ giữ liên lạc thường xuyên. Khi phải tắt điện thoại thì nhắn tin trước."},{"n":12,"start":42.88999999999999,"end":45.41,"parts":[{"zh":"好，我不会忘的。"}],"pinyin":"Hǎo, wǒ bú huì wàng de.","vi":"Được, tôi sẽ không quên."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-39';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-39', 0, '[{"n":1,"start":0,"end":4.45,"parts":[{"zh":"我接到通知，下个月学校举行汉语比赛。"}],"pinyin":"Wǒ jiēdào tōngzhī, xià ge yuè xuéxiào jǔxíng Hànyǔ bǐsài.","vi":"Tôi nhận được thông báo, tháng sau trường tổ chức cuộc thi tiếng Trung."},{"n":2,"start":4.45,"end":7.6,"parts":[{"zh":"真的吗？你愿意参加吗？"}],"pinyin":"Zhēn de ma? Nǐ yuànyì cānjiā ma?","vi":"Thật không? Bạn muốn tham gia không?"},{"n":3,"start":7.6,"end":11.399999999999999,"parts":[{"zh":"愿意，比赛的主要重点是听和说。"}],"pinyin":"Yuànyì, bǐsài de zhǔyào zhòngdiǎn shì tīng hé shuō.","vi":"Muốn, trọng điểm chính của cuộc thi là nghe và nói."},{"n":4,"start":11.399999999999999,"end":14.349999999999998,"parts":[{"zh":"那你练习得怎么样了？"}],"pinyin":"Nà nǐ liànxí de zěnmeyàng le?","vi":"Vậy bạn luyện tập thế nào rồi?"},{"n":5,"start":14.349999999999998,"end":17.769999999999996,"parts":[{"zh":"还不太熟，我得每天多练习。"}],"pinyin":"Hái bú tài shú, wǒ děi měitiān duō liànxí.","vi":"Chưa rành lắm, tôi phải luyện mỗi ngày."},{"n":6,"start":17.769999999999996,"end":21.469999999999995,"parts":[{"zh":"我们组成一个小组，一起练习吧。"}],"pinyin":"Wǒmen zǔchéng yī ge xiǎozǔ, yīqǐ liànxí ba.","vi":"Chúng ta lập một nhóm nhỏ, cùng luyện tập nhé."},{"n":7,"start":21.469999999999995,"end":25.749999999999996,"parts":[{"zh":"好主意。我租的房子里正好有一间空房。"}],"pinyin":"Hǎo zhǔyi. Wǒ zū de fángzi lǐ zhènghǎo yǒu yī jiān kòngfáng.","vi":"Ý hay. Nhà tôi thuê trùng hợp có một căn phòng trống."},{"n":8,"start":25.749999999999996,"end":28.869999999999997,"parts":[{"zh":"原来你搬到新房子了？"}],"pinyin":"Yuánlái nǐ bān dào xīn fángzi le?","vi":"Hóa ra bạn chuyển sang nhà mới rồi?"},{"n":9,"start":28.869999999999997,"end":32.419999999999995,"parts":[{"zh":"对。你什么时候来我的新家看看？"}],"pinyin":"Duì. Nǐ shénme shíhou lái wǒ de xīn jiā kànkan?","vi":"Đúng. Khi nào bạn ghé nhà mới tôi chơi?"},{"n":10,"start":32.419999999999995,"end":35.019999999999996,"parts":[{"zh":"直接说吧，哪天？"}],"pinyin":"Zhíjiē shuō ba, nǎ tiān?","vi":"Nói thẳng đi, ngày nào?"},{"n":11,"start":35.019999999999996,"end":39.019999999999996,"parts":[{"zh":"这个星期六，我们可以进行一次练习。"}],"pinyin":"Zhège xīngqīliù, wǒmen kěyǐ jìnxíng yī cì liànxí.","vi":"Thứ Bảy tuần này, chúng ta có thể tiến hành một buổi luyện tập."},{"n":12,"start":39.019999999999996,"end":43.31999999999999,"parts":[{"zh":"好，你的做法很好，老师一定会重视的。"}],"pinyin":"Hǎo, nǐ de zuòfǎ hěn hǎo, lǎoshī yīdìng huì zhòngshì de.","vi":"Được, cách làm của bạn hay lắm, thầy nhất định sẽ coi trọng."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk2/lesson-40';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk2/lesson-40', 0, '[{"n":1,"start":0,"end":3.85,"parts":[{"zh":"这位是新来的同学，他叫王小明。"}],"pinyin":"Zhè wèi shì xīn lái de tóngxué, tā jiào Wáng Xiǎomíng.","vi":"Vị này là bạn mới, anh ấy tên Vương Tiểu Minh."},{"n":2,"start":3.85,"end":9.05,"parts":[{"zh":"你好！你是作家吗？我看过根据你的小说拍的影片。"}],"pinyin":"Nǐ hǎo! Nǐ shì zuòjiā ma? Wǒ kànguo gēnjù nǐ de xiǎoshuō pāi de yǐngpiàn.","vi":"Xin chào! Bạn là nhà văn à? Tôi đã xem phim dựng từ tiểu thuyết của bạn."},{"n":3,"start":9.05,"end":12.780000000000001,"parts":[{"zh":"哈哈，不是作家，我只是一个学生。"}],"pinyin":"Hāhā, bú shì zuòjiā, wǒ zhǐshì yī ge xuésheng.","vi":"Ha ha, không phải nhà văn, tôi chỉ là sinh viên thôi."},{"n":4,"start":12.780000000000001,"end":15.63,"parts":[{"zh":"你来中国多久了？"}],"pinyin":"Nǐ lái Zhōngguó duō jiǔ le?","vi":"Bạn sang Trung Quốc bao lâu rồi?"},{"n":5,"start":15.63,"end":18.48,"parts":[{"zh":"三年了，学习很顺利。"}],"pinyin":"Sān nián le, xuéxí hěn shùnlì.","vi":"Ba năm rồi, học hành thuận lợi."},{"n":6,"start":18.48,"end":22.38,"parts":[{"zh":"太好了！那家饭馆的菜真好吃。"}],"pinyin":"Tài hǎole! Nà jiā fànguǎn de cài zhēn hǎochī.","vi":"Tốt quá! Món ăn ở quán đó ngon thật."},{"n":7,"start":22.38,"end":25.88,"parts":[{"zh":"对，我天天去，老板都认识我了。"}],"pinyin":"Duì, wǒ tiāntiān qù, lǎobǎn dōu rènshi wǒ le.","vi":"Đúng, tôi đi hằng ngày, chủ quán còn quen tôi rồi."},{"n":8,"start":25.88,"end":30.18,"parts":[{"zh":"你的电话号码是多少？把数字告诉我。"}],"pinyin":"Nǐ de diànhuà hàomǎ shì duōshǎo? Bǎ shùzì gàosu wǒ.","vi":"Số điện thoại của bạn bao nhiêu? Cho tôi xin số."},{"n":9,"start":30.18,"end":34.26,"parts":[{"zh":"别生气，我记不住，我用手机发给你吧。"}],"pinyin":"Bié shēngqì, wǒ jì bú zhù, wǒ yòng shǒujī fā gěi nǐ ba.","vi":"Đừng giận, tôi không nhớ nổi, tôi gửi qua điện thoại cho bạn nhé."},{"n":10,"start":34.26,"end":36.71,"parts":[{"zh":"好，考试顺利！"}],"pinyin":"Hǎo, kǎoshì shùnlì!","vi":"Được, chúc thi thuận lợi!"},{"n":11,"start":36.71,"end":39.04,"parts":[{"zh":"谢谢，一路平安！"}],"pinyin":"Xièxie, yīlù píng''ān!","vi":"Cảm ơn, chúc đi đường bình an!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-1';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-1', 0, '[{"n":1,"start":0,"end":2.9,"parts":[{"zh":"你今天为什么这么不安？"}],"pinyin":"nǐ jīntiān wèishénme zhème bù''ān?","vi":"Hôm nay sao bạn bất an thế?"},{"n":2,"start":2.9,"end":7.6,"parts":[{"zh":"我不得不给父母打一个电话，报告我的成绩。"}],"pinyin":"wǒ bùdébù gěi fùmǔ dǎ yí ge diànhuà, bàogào wǒ de chéngjì.","vi":"Mình phải gọi điện cho bố mẹ, báo cáo thành tích của mình."},{"n":3,"start":7.6,"end":11.12,"parts":[{"zh":"这是个好事情啊，你不必紧张。"}],"pinyin":"zhè shì ge hǎo shìqing a, nǐ búbì jǐnzhāng.","vi":"Đây là chuyện tốt mà, bạn không cần lo lắng."},{"n":4,"start":11.12,"end":16.72,"parts":[{"zh":"不光是成绩，我还要告诉他们，我在东部地区订了房子。"}],"pinyin":"bùguāng shì chéngjì, wǒ hái yào gàosu tāmen, wǒ zài dōngbù dìqū dìng le fángzi.","vi":"Không chỉ có thành tích, mình còn phải nói với họ là mình đã đặt nhà ở khu vực phía đông."},{"n":5,"start":16.72,"end":19.95,"parts":[{"zh":"真的？房东是个什么样的人？"}],"pinyin":"zhēn de? fángdōng shì ge shénmeyàng de rén?","vi":"Thật à? Chủ nhà là người thế nào?"},{"n":6,"start":19.95,"end":24.1,"parts":[{"zh":"除了周末，他每周都定期来收房租。"}],"pinyin":"chúle zhōumò, tā měi zhōu dōu dìngqī lái shōu fángzū.","vi":"Ngoài cuối tuần, mỗi tuần anh ấy đều đến thu tiền nhà định kỳ."},{"n":7,"start":24.1,"end":29.05,"parts":[{"zh":"那你的衬衫买了吗？在这个场合，白衬衫最重要。"}],"pinyin":"nà nǐ de chènshān mǎi le ma? zài zhège chǎnghé, bái chènshān zuì zhòngyào.","vi":"Vậy bạn mua áo sơ mi chưa? Trong dịp này, áo sơ mi trắng quan trọng nhất."},{"n":8,"start":29.05,"end":32.78,"parts":[{"zh":"买了，我等待这一天已经很久了。"}],"pinyin":"mǎi le, wǒ děngdài zhè yìtiān yǐjīng hěn jiǔ le.","vi":"Rồi, mình đã chờ ngày này rất lâu rồi."},{"n":9,"start":32.78,"end":36.730000000000004,"parts":[{"zh":"你的成功是大家都能看到的成就。"}],"pinyin":"nǐ de chénggōng shì dàjiā dōu néng kàndào de chéngjiù.","vi":"Thành công của bạn là thành tựu ai cũng nhìn thấy được."},{"n":10,"start":36.730000000000004,"end":42.400000000000006,"parts":[{"zh":"谢谢，我不会否认自己很努力，但我还要发表一篇报告。"}],"pinyin":"xièxie, wǒ bú huì fǒurèn zìjǐ hěn nǔlì, dàn wǒ hái yào fābiǎo yì piān bàogào.","vi":"Cảm ơn, tôi không phủ nhận mình rất cố gắng, nhưng tôi còn phải trình bày một bản báo cáo."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-2';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-2', 0, '[{"n":1,"start":0,"end":3.52,"parts":[{"zh":"听说你父亲要来我们这里工作？"}],"pinyin":"tīngshuō nǐ fùqīn yào lái wǒmen zhèlǐ gōngzuò?","vi":"Nghe nói bố bạn sẽ đến đây làm việc?"},{"n":2,"start":3.52,"end":9.1,"parts":[{"zh":"对，各地都有他的学生，他基本上每个月都去一个地方。"}],"pinyin":"duì, gèdì dōu yǒu tā de xuésheng, tā jīběnshàng měi ge yuè dōu qù yí ge dìfang.","vi":"Đúng vậy, ở đâu cũng có học trò của ông, về cơ bản mỗi tháng ông đến một nơi."},{"n":3,"start":9.1,"end":12,"parts":[{"zh":"那今年的结婚计划呢？"}],"pinyin":"nà jīnnián de jiéhūn jìhuà ne?","vi":"Thế kế hoạch kết hôn năm nay thì sao?"},{"n":4,"start":12,"end":17.6,"parts":[{"zh":"我们决定举办一个简单的婚礼，只请家属和几个朋友。"}],"pinyin":"wǒmen juédìng jǔbàn yí ge jiǎndān de hūnlǐ, zhǐ qǐng jiāshǔ hé jǐ ge péngyou.","vi":"Chúng tôi quyết định tổ chức đám cưới đơn giản, chỉ mời người nhà và vài người bạn."},{"n":5,"start":17.6,"end":22.07,"parts":[{"zh":"这个规定很好，公共的场合不用花太多钱。"}],"pinyin":"zhège guīdìng hěn hǎo, gōnggòng de chǎnghé bú yòng huā tài duō qián.","vi":"Quy định này hay đấy, ở nơi công cộng không cần tốn nhiều tiền."},{"n":6,"start":22.07,"end":27.240000000000002,"parts":[{"zh":"我父亲有很多工夫，他说他会公开地帮助我们。"}],"pinyin":"wǒ fùqīn yǒu hěn duō gōngfu, tā shuō tā huì gōngkāi de bāngzhù wǒmen.","vi":"Bố tôi có nhiều thời gian, ông nói ông sẽ công khai giúp chúng tôi."},{"n":7,"start":27.240000000000002,"end":30.540000000000003,"parts":[{"zh":"电视上会广播这个消息吗？"}],"pinyin":"diànshì shàng huì guǎngbō zhège xiāoxi ma?","vi":"Trên TV có phát tin này không?"},{"n":8,"start":30.540000000000003,"end":34.57,"parts":[{"zh":"不会，我们是普通公民，不是公务员。"}],"pinyin":"bú huì, wǒmen shì pǔtōng gōngmín, bú shì gōngwùyuán.","vi":"Không, chúng tôi là công dân bình thường, không phải công chức."},{"n":9,"start":34.57,"end":39.35,"parts":[{"zh":"旧的东西就不用买了，用你的工具自己做一个吧。"}],"pinyin":"jiù de dōngxi jiù bú yòng mǎi le, yòng nǐ de gōngjù zìjǐ zuò yí ge ba.","vi":"Đồ cũ thì khỏi mua, dùng dụng cụ của bạn tự làm một cái đi."},{"n":10,"start":39.35,"end":42.120000000000005,"parts":[{"zh":"好啊，我有这个技术！"}],"pinyin":"hǎo a, wǒ yǒu zhège jìshù!","vi":"Được chứ, tôi có kỹ năng này!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-3';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-3', 0, '[{"n":1,"start":0,"end":3.9,"parts":[{"zh":"老太太看起来不太高兴，她怎么了？"}],"pinyin":"lǎotàitai kànqǐlái bú tài gāoxìng, tā zěnme le?","vi":"Bà lão trông không vui lắm, bà bị sao thế?"},{"n":2,"start":3.9,"end":9.05,"parts":[{"zh":"她和老头儿在讨论儿子离婚的问题，都很难决定。"}],"pinyin":"tā hé lǎotóur zài tǎolùn érzi líhūn de wèntí, dōu hěn nán juédìng.","vi":"Bà và ông lão đang bàn chuyện con trai ly hôn, rất khó quyết định."},{"n":3,"start":9.05,"end":14.8,"parts":[{"zh":"据说现在农村的年轻人缺少工作机会，是不是这个原因？"}],"pinyin":"jùshuō xiànzài nóngcūn de niánqīngrén quēshǎo gōngzuò jīhuì, shì bú shì zhège yuányīn?","vi":"Nghe nói hiện nay thanh niên ở nông thôn thiếu cơ hội việc làm, có phải vì lý do đó không?"},{"n":4,"start":14.8,"end":22.5,"parts":[{"zh":"有这个可能。媒体上常常报道，很多男子去城市工作，母亲和亲人都在农村。"}],"pinyin":"yǒu zhège kěnéng. méitǐ shàng chángcháng bàodào, hěn duō nánzǐ qù chéngshì gōngzuò, mǔqīn hé qīnrén dōu zài nóngcūn.","vi":"Có thể vậy. Trên truyền thông hay đưa tin, nhiều đàn ông vào thành phố làm việc, mẹ và người thân đều ở nông thôn."},{"n":5,"start":22.5,"end":27.15,"parts":[{"zh":"那面对这样的问题，他们能不能早点说清楚呢？"}],"pinyin":"nà miànduì zhèyàng de wèntí, tāmen néng bu néng zǎodiǎn shuō qīngchu ne?","vi":"Vậy trước vấn đề như vậy, họ có thể nói rõ sớm hơn không?"},{"n":6,"start":27.15,"end":33.18,"parts":[{"zh":"说清楚不容易，生活里有很多看起来简单、实际上很难的事。"}],"pinyin":"shuō qīngchu bù róngyì, shēnghuó lǐ yǒu hěn duō kànqǐlái jiǎndān, shíjì shàng hěn nán de shì.","vi":"Nói rõ không dễ, trong cuộc sống có nhiều việc nhìn thì đơn giản mà thực tế rất khó."},{"n":7,"start":33.18,"end":37.76,"parts":[{"zh":"科技发展得这么快，农活也有机器帮忙了吧？"}],"pinyin":"kējì fāzhǎn de zhème kuài, nónghuó yě yǒu jīqì bāngmáng le ba?","vi":"Công nghệ phát triển nhanh thế, việc đồng áng cũng có máy giúp rồi chứ?"},{"n":8,"start":37.76,"end":42.23,"parts":[{"zh":"是啊，可是机器再好，也不能代替亲人。"}],"pinyin":"shì a, kěshì jīqì zài hǎo, yě bù néng dàitì qīnrén.","vi":"Ừ, nhưng máy móc tốt đến đâu cũng không thay thế được người thân."},{"n":9,"start":42.23,"end":46.4,"parts":[{"zh":"我明白。希望他们能确定一个好的方向。"}],"pinyin":"wǒ míngbai. xīwàng tāmen néng quèdìng yí ge hǎo de fāngxiàng.","vi":"Tôi hiểu rồi. Hy vọng họ xác định được hướng đi tốt."},{"n":10,"start":46.4,"end":51.519999999999996,"parts":[{"zh":"我也是。这个房子太空了，人少了就显得没有生气。"}],"pinyin":"wǒ yě shì. zhège fángzi tài kōng le, rén shǎo le jiù xiǎn de méiyǒu shēngqì.","vi":"Tôi cũng vậy. Căn nhà này trống quá, ít người trông chẳng có sức sống."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-4';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-4', 0, '[{"n":1,"start":0,"end":3.15,"parts":[{"zh":"你昨天收看天气预报了吗？"}],"pinyin":"nǐ zuótiān shōukàn tiānqì yùbào le ma?","vi":"Hôm qua bạn xem dự báo thời tiết chưa?"},{"n":2,"start":3.15,"end":7.5,"parts":[{"zh":"看了，突然降温，我只好穿上厚的衣服。"}],"pinyin":"kàn le, tūrán jiàngwēn, wǒ zhǐhǎo chuān shàng hòu de yīfu.","vi":"Xem rồi, trời đột nhiên lạnh xuống, tôi đành phải mặc áo dày."},{"n":3,"start":7.5,"end":11.8,"parts":[{"zh":"我爸爸退休以后，每天都准时收看新闻。"}],"pinyin":"wǒ bàba tuìxiū yǐhòu, měitiān dōu zhǔnshí shōukàn xīnwén.","vi":"Bố tôi nghỉ hưu xong, mỗi ngày đều xem tin tức đúng giờ."},{"n":4,"start":11.8,"end":17.130000000000003,"parts":[{"zh":"老人喜欢完整的信息，不喜欢题目太简单的文章。"}],"pinyin":"lǎorén xǐhuan wánzhěng de xìnxī, bù xǐhuan tímù tài jiǎndān de wénzhāng.","vi":"Người già thích thông tin đầy đủ, không thích bài viết có tiêu đề quá đơn giản."},{"n":5,"start":17.130000000000003,"end":20.830000000000002,"parts":[{"zh":"他还会外文吗？听说他以前学过。"}],"pinyin":"tā hái huì wàiwén ma? tīngshuō tā yǐqián xué guo.","vi":"Ông ấy còn biết ngoại ngữ không? Nghe nói trước đây ông học rồi."},{"n":6,"start":20.830000000000002,"end":25.830000000000002,"parts":[{"zh":"会一点，但是没有真实的机会用，慢慢就消失了。"}],"pinyin":"huì yìdiǎn, dànshì méiyǒu zhēnshí de jīhuì yòng, mànmàn jiù xiāoshī le.","vi":"Biết chút ít, nhưng không có cơ hội thật để dùng, dần dần cũng quên mất."},{"n":7,"start":25.830000000000002,"end":30.18,"parts":[{"zh":"现在通信这么方便，可以从网上学习。"}],"pinyin":"xiànzài tōngxìn zhème fāngbiàn, kěyǐ cóng wǎngshàng xuéxí.","vi":"Giờ liên lạc tiện thế mà, có thể học trên mạng."},{"n":8,"start":30.18,"end":35.63,"parts":[{"zh":"他试过，但是他更喜欢真实的接触，比如收集邮票。"}],"pinyin":"tā shì guo, dànshì tā gèng xǐhuan zhēnshí de jiēchù, bǐrú shōují yóupiào.","vi":"Ông thử rồi, nhưng ông thích tiếp xúc thật hơn, như sưu tầm tem."},{"n":9,"start":35.63,"end":39.18,"parts":[{"zh":"人群里到处都是他这样的人吧？"}],"pinyin":"rénqún lǐ dàochù dōu shì tā zhèyàng de rén ba?","vi":"Trong đám đông chắc toàn những người như ông ấy nhỉ?"},{"n":10,"start":39.18,"end":44.58,"parts":[{"zh":"有的是！他自己声明过：退休不是结束，是新的事业。"}],"pinyin":"yǒu de shì! tā zìjǐ shēngmíng guo: tuìxiū bú shì jiéshù, shì xīn de shìyè.","vi":"Nhiều lắm! Ông ấy từng tuyên bố: nghỉ hưu không phải kết thúc mà là sự nghiệp mới."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-5';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-5', 0, '[{"n":1,"start":0,"end":3.2,"parts":[{"zh":"哈哈，你今天的精神真好！"}],"pinyin":"hāhā, nǐ jīntiān de jīngshén zhēn hǎo!","vi":"Haha, hôm nay tinh thần bạn tốt thật!"},{"n":2,"start":3.2,"end":8.58,"parts":[{"zh":"因为我终于完成了一个长期的工作，内心特别欢乐。"}],"pinyin":"yīnwèi wǒ zhōngyú wánchéng le yí ge chángqī de gōngzuò, nèixīn tèbié huānlè.","vi":"Vì tôi cuối cùng cũng hoàn thành công việc dài hạn, trong lòng đặc biệt vui vẻ."},{"n":3,"start":8.58,"end":12.75,"parts":[{"zh":"怪不得！你平时遇到困难会不会害怕？"}],"pinyin":"guàibudé! nǐ píngshí yùdào kùnnán huì bú huì hàipà?","vi":"Chả trách! Bình thường gặp khó khăn bạn có sợ không?"},{"n":4,"start":12.75,"end":17.53,"parts":[{"zh":"会紧张，但是我很乐观，相信事情会变好。"}],"pinyin":"huì jǐnzhāng, dànshì wǒ hěn lèguān, xiāngxìn shìqing huì biàn hǎo.","vi":"Có hồi hộp, nhưng tôi lạc quan, tin mọi việc sẽ tốt lên."},{"n":5,"start":17.53,"end":22.36,"parts":[{"zh":"上次你受伤的时候，我恐怕你伤心了好几天。"}],"pinyin":"shàng cì nǐ shòushāng de shíhou, wǒ kǒngpà nǐ shāngxīn le hǎo jǐ tiān.","vi":"Hôm trước khi bạn bị thương, tôi e là bạn buồn mấy ngày."},{"n":6,"start":22.36,"end":27.509999999999998,"parts":[{"zh":"是啊，身体上的伤不可怕，感情上的伤才难过。"}],"pinyin":"shì a, shēntǐ shàng de shāng bù kěpà, gǎnqíng shàng de shāng cái nánguò.","vi":"Ừ, vết thương trên thân thể không đáng sợ, vết thương trong tình cảm mới buồn."},{"n":7,"start":27.509999999999998,"end":31.24,"parts":[{"zh":"现在呢？商业上的事还让你紧张吗？"}],"pinyin":"xiànzài ne? shāngyè shàng de shì hái ràng nǐ jǐnzhāng ma?","vi":"Còn bây giờ? Chuyện làm ăn còn khiến bạn căng thẳng không?"},{"n":8,"start":31.24,"end":35.989999999999995,"parts":[{"zh":"好多了。日常的生活很美好，我热爱每一天。"}],"pinyin":"hǎo duō le. rìcháng de shēnghuó hěn měihǎo, wǒ rè''ài měi yì tiān.","vi":"Khá hơn nhiều rồi. Cuộc sống thường ngày thật đẹp, tôi yêu mỗi ngày."},{"n":9,"start":35.989999999999995,"end":39.019999999999996,"parts":[{"zh":"你能说说自己的长处吗？"}],"pinyin":"nǐ néng shuōshuo zìjǐ de chángchù ma?","vi":"Bạn có thể nói về ưu điểm của mình không?"},{"n":10,"start":39.019999999999996,"end":44.449999999999996,"parts":[{"zh":"我情感丰富，还很巧，什么难事到我手里都变简单了。"}],"pinyin":"wǒ qínggǎn fēngfù, hái hěn qiǎo, shénme nán shì dào wǒ shǒu lǐ dōu biàn jiǎndān le.","vi":"Tôi giàu cảm xúc, lại khéo tay, việc khó gì đến tay tôi cũng trở nên đơn giản."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-6';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-6', 0, '[{"n":1,"start":0,"end":3,"parts":[{"zh":"你觉得什么样的人最可靠？"}],"pinyin":"nǐ juéde shénmeyàng de rén zuì kěkào?","vi":"Bạn thấy người thế nào nhất đáng tin cậy?"},{"n":2,"start":3,"end":7.3,"parts":[{"zh":"我觉得有个性的、能坚持的人最可靠。"}],"pinyin":"wǒ juéde yǒu gèxìng de, néng jiānchí de rén zuì kěkào.","vi":"Tôi thấy người có cá tính, biết kiên trì mới đáng tin nhất."},{"n":3,"start":7.3,"end":12.55,"parts":[{"zh":"你说得对。我弟弟就是这样，他总是争取做得最好。"}],"pinyin":"nǐ shuō de duì. wǒ dìdi jiù shì zhèyàng, tā zǒng shì zhēngqǔ zuò de zuì hǎo.","vi":"Bạn nói đúng. Em trai tôi là vậy, nó luôn cố gắng làm tốt nhất."},{"n":4,"start":12.55,"end":15.4,"parts":[{"zh":"他现在成熟多了吧？"}],"pinyin":"tā xiànzài chéngshú duō le ba?","vi":"Giờ nó trưởng thành hơn nhiều rồi chứ?"},{"n":5,"start":15.4,"end":20.87,"parts":[{"zh":"是的，他的成长让我很放心。虽然他还年轻，但有本事。"}],"pinyin":"shì de, tā de chéngzhǎng ràng wǒ hěn fàngxīn. suīrán tā hái niánqīng, dàn yǒu běnshi.","vi":"Đúng vậy, sự trưởng thành của nó khiến tôi yên tâm. Dù còn trẻ nhưng có bản lĩnh."},{"n":6,"start":20.87,"end":24.12,"parts":[{"zh":"那你呢？你有什么好性格？"}],"pinyin":"nà nǐ ne? nǐ yǒu shénme hǎo xìnggé?","vi":"Còn bạn? Bạn có tính cách nào tốt?"},{"n":7,"start":24.12,"end":28.57,"parts":[{"zh":"我做事尽量节约时间，也尽量帮助别人。"}],"pinyin":"wǒ zuòshì jìnliàng jiéyuē shíjiān, yě jìnliàng bāngzhù biérén.","vi":"Tôi làm việc cố gắng tiết kiệm thời gian, cũng cố gắng giúp người khác."},{"n":8,"start":28.57,"end":33.32,"parts":[{"zh":"这确实是你的积极性。所以大家都信任你。"}],"pinyin":"zhè quèshí shì nǐ de jījíxìng. suǒyǐ dàjiā dōu xìnrèn nǐ.","vi":"Đây quả thật là tính tích cực của bạn. Nên ai cũng tin tưởng bạn."},{"n":9,"start":33.32,"end":37.05,"parts":[{"zh":"谢谢。好好努力，我们都会进步的。"}],"pinyin":"xièxie. hǎohāo nǔlì, wǒmen dōu huì jìnbù de.","vi":"Cảm ơn. Cố gắng tốt lên, chúng ta đều sẽ tiến bộ."},{"n":10,"start":37.05,"end":40.93,"parts":[{"zh":"终于有人这么说了！我们一起加油吧。"}],"pinyin":"zhōngyú yǒu rén zhème shuō le! wǒmen yìqǐ jiāyóu ba.","vi":"Cuối cùng cũng có người nói thế! Mình cùng cố gắng nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-7';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-7', 0, '[{"n":1,"start":0,"end":3.67,"parts":[{"zh":"部长今天安排了一个重要的会议。"}],"pinyin":"bùzhǎng jīntiān ānpái le yí ge zhòngyào de huìyì.","vi":"Bộ trưởng hôm nay đã sắp xếp một cuộc họp quan trọng."},{"n":2,"start":3.67,"end":7.62,"parts":[{"zh":"我知道，是关于经济合作的事情吧？"}],"pinyin":"wǒ zhīdào, shì guānyú jīngjì hézuò de shìqing ba?","vi":"Tôi biết, là chuyện hợp tác kinh tế đúng không?"},{"n":3,"start":7.62,"end":11.29,"parts":[{"zh":"对。老板要我负责谈判，压力很大。"}],"pinyin":"duì. lǎobǎn yào wǒ fùzé tánpàn, yālì hěn dà.","vi":"Đúng. Sếp bảo tôi phụ trách đàm phán, áp lực rất lớn."},{"n":4,"start":11.29,"end":16.439999999999998,"parts":[{"zh":"别乱想，你的任务很简单：把市场的情况说清楚。"}],"pinyin":"bié luàn xiǎng, nǐ de rènwù hěn jiǎndān: bǎ shìchǎng de qíngkuàng shuō qīngchu.","vi":"Đừng nghĩ lung tung, nhiệm vụ của bạn rất đơn giản: nói rõ tình hình thị trường."},{"n":5,"start":16.439999999999998,"end":19.74,"parts":[{"zh":"可是人员不够，事情太多了。"}],"pinyin":"kěshì rényuán bú gòu, shìqing tài duō le.","vi":"Nhưng nhân sự không đủ, việc quá nhiều."},{"n":6,"start":19.74,"end":24.04,"parts":[{"zh":"你可以和所长联合起来，大家一起做。"}],"pinyin":"nǐ kěyǐ hé suǒzhǎng liánhé qǐlái, dàjiā yìqǐ zuò.","vi":"Bạn có thể liên kết với trưởng phòng, mọi người cùng làm."},{"n":7,"start":24.04,"end":28.82,"parts":[{"zh":"好主意！他们公司最近开业了，正需要生意伙伴。"}],"pinyin":"hǎo zhǔyi! tāmen gōngsī zuìjìn kāiyè le, zhèng xūyào shēngyi huǒbàn.","vi":"Ý hay! Công ty họ mới khai trương, đang cần đối tác kinh doanh."},{"n":8,"start":28.82,"end":34.35,"parts":[{"zh":"那就这样安排。工资方面，做完这个项目会有奖励。"}],"pinyin":"nà jiù zhèyàng ānpái. gōngzī fāngmiàn, zuò wán zhège xiàngmù huì yǒu jiǎnglì.","vi":"Vậy sắp xếp thế nhé. Về lương, làm xong dự án này sẽ có thưởng."},{"n":9,"start":34.35,"end":38.18,"parts":[{"zh":"太好了！我下午就去海关办手续。"}],"pinyin":"tài hǎo le! wǒ xiàwǔ jiù qù hǎiguān bàn shǒuxù.","vi":"Tốt quá! Chiều nay tôi đi hải quan làm thủ tục ngay."},{"n":10,"start":38.18,"end":41.58,"parts":[{"zh":"加油，我相信你会成功的。"}],"pinyin":"jiāyóu, wǒ xiāngxìn nǐ huì chénggōng de.","vi":"Cố lên, tôi tin bạn sẽ thành công."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-8';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-8', 0, '[{"n":1,"start":0,"end":3.23,"parts":[{"zh":"我们班级的比赛成绩怎么样？"}],"pinyin":"wǒmen bānjí de bǐsài chéngjì zěnmeyàng?","vi":"Kết quả thi đấu của lớp mình thế nào rồi?"},{"n":2,"start":3.23,"end":7.35,"parts":[{"zh":"我们班的得分最高！大家都高兴极了。"}],"pinyin":"wǒmen bān de défēn zuì gāo! dàjiā dōu gāoxìng jí le.","vi":"Lớp mình có số điểm cao nhất! Ai cũng vui lắm."},{"n":3,"start":7.35,"end":10.379999999999999,"parts":[{"zh":"真棒！那功课呢，跟得上吗？"}],"pinyin":"zhēn bàng! nà gōngkè ne, gēn de shàng ma?","vi":"Giỏi thế! Còn bài vở thì theo kịp không?"},{"n":4,"start":10.379999999999999,"end":15.03,"parts":[{"zh":"初中虽然忙，但是必要的内容我都复习了。"}],"pinyin":"chūzhōng suīrán máng, dànshì bìyào de nèiróng wǒ dōu fùxí le.","vi":"Trung học cơ sở tuy bận nhưng những nội dung cần thiết tôi đều ôn lại."},{"n":5,"start":15.03,"end":19.18,"parts":[{"zh":"听说新的教材做了改进，你觉得怎么样？"}],"pinyin":"tīngshuō xīn de jiàocái zuò le gǎijìn, nǐ juéde zěnmeyàng?","vi":"Nghe nói giáo trình mới đã được cải tiến, bạn thấy thế nào?"},{"n":6,"start":19.18,"end":23.33,"parts":[{"zh":"好多了，课程更有经验，也更容易懂。"}],"pinyin":"hǎo duō le, kèchéng gèng yǒu jīngyàn, yě gèng róngyì dǒng.","vi":"Khá hơn nhiều, chương trình học có kinh nghiệm hơn cũng dễ hiểu hơn."},{"n":7,"start":23.33,"end":27.909999999999997,"parts":[{"zh":"你想从事什么工作？留学的经验对你有帮助吗？"}],"pinyin":"nǐ xiǎng cóngshì shénme gōngzuò? liúxué de jīngyàn duì nǐ yǒu bāngzhù ma?","vi":"Bạn muốn theo nghề gì? Kinh nghiệm du học có giúp ích cho bạn không?"},{"n":8,"start":27.909999999999997,"end":31.909999999999997,"parts":[{"zh":"我想当教练，或者设计新的设备。"}],"pinyin":"wǒ xiǎng dāng jiàoliàn, huòzhě shèjì xīn de shèbèi.","vi":"Tôi muốn làm huấn luyện viên, hoặc thiết kế thiết bị mới."},{"n":9,"start":31.909999999999997,"end":36.91,"parts":[{"zh":"那你可以去实验室做试验，缺什么设备跟老师说。"}],"pinyin":"nà nǐ kěyǐ qù shíyànshì zuò shìyàn, quē shénme shèbèi gēn lǎoshī shuō.","vi":"Thế bạn có thể vào phòng thí nghiệm làm thí nghiệm, thiếu thiết bị gì thì nói với thầy."},{"n":10,"start":36.91,"end":41.459999999999994,"parts":[{"zh":"好！全场的人都说我有想法，我一定努力。"}],"pinyin":"hǎo! quánchǎng de rén dōu shuō wǒ yǒu xiǎngfǎ, wǒ yídìng nǔlì.","vi":"Được! Cả khán phòng ai cũng nói tôi có ý tưởng, tôi nhất định cố gắng."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-9';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-9', 0, '[{"n":1,"start":0,"end":4.75,"parts":[{"zh":"按照这个地图，长城附近有一家不错的餐厅。"}],"pinyin":"ànzhào zhège dìtú, Chángchéng fùjìn yǒu yì jiā búcuò de cāntīng.","vi":"Theo tấm bản đồ này, gần Vạn Lý Trường Thành có một nhà hàng khá ổn."},{"n":2,"start":4.75,"end":8.67,"parts":[{"zh":"太好了！我大概饿了，咱们赶紧走吧。"}],"pinyin":"tài hǎo le! wǒ dàgài è le, zánmen gǎnjǐn zǒu ba.","vi":"Tốt quá! Tôi cũng đói rồi, mình đi nhanh nào."},{"n":3,"start":8.67,"end":12.77,"parts":[{"zh":"你报了团吗？导游会在报到的地方等我们。"}],"pinyin":"nǐ bào le tuán ma? dǎoyóu huì zài bàodào de dìfang děng wǒmen.","vi":"Bạn đã đăng ký tour chưa? Hướng dẫn viên sẽ đợi chúng ta ở nơi tập kết."},{"n":4,"start":12.77,"end":18.17,"parts":[{"zh":"报了，这个团员大概有二十个人，大家来自不同的城市。"}],"pinyin":"bào le, zhège tuányuán dàgài yǒu èrshí ge rén, dàjiā láizì bùtóng de chéngshì.","vi":"Rồi, đoàn này khoảng hai mươi người, mọi người đến từ các thành phố khác nhau."},{"n":5,"start":18.17,"end":22.400000000000002,"parts":[{"zh":"听说这个导演拍了一部关于美食的电影。"}],"pinyin":"tīngshuō zhège dǎoyǎn pāi le yí bù guānyú měishí de diànyǐng.","vi":"Nghe nói đạo diễn này quay một bộ phim về ẩm thực."},{"n":6,"start":22.400000000000002,"end":26.82,"parts":[{"zh":"对，电影里说，好的饭菜能把人变为朋友。"}],"pinyin":"duì, diànyǐng lǐ shuō, hǎo de fàncài néng bǎ rén biàn wéi péngyou.","vi":"Đúng, trong phim nói món ăn ngon có thể biến người ta thành bạn bè."},{"n":7,"start":26.82,"end":31.77,"parts":[{"zh":"有道理！为了吃到好东西，我们才能走这么远的路。"}],"pinyin":"yǒu dàolǐ! wèile chī dào hǎo dōngxi, wǒmen cái néng zǒu zhème yuǎn de lù.","vi":"Có lý! Để ăn được món ngon, chúng ta mới đi xa như vậy."},{"n":8,"start":31.77,"end":37.8,"parts":[{"zh":"今天的队员都很喜欢吃，晚上点菜的时候要防止浪费。"}],"pinyin":"jīntiān de duìyuán dōu hěn xǐhuan chī, wǎnshang diǎn cài de shíhou yào fángzhǐ làngfèi.","vi":"Hôm nay các thành viên trong đoàn đều thích ăn, tối gọi món phải đề phòng lãng phí."},{"n":9,"start":37.8,"end":42.55,"parts":[{"zh":"放心，我们的方式是一人点一个菜，大家一起吃。"}],"pinyin":"fàngxīn, wǒmen de fāngshì shì yì rén diǎn yí ge cài, dàjiā yìqǐ chī.","vi":"Yên tâm, cách của chúng ta là mỗi người gọi một món, cả nhóm cùng ăn."},{"n":10,"start":42.55,"end":46.18,"parts":[{"zh":"好，干吗想那么多？先吃再说！"}],"pinyin":"hǎo, gànmá xiǎng nàme duō? xiān chī zài shuō!","vi":"Được, việc gì phải nghĩ nhiều thế? Ăn trước đã!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-10';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-10', 0, '[{"n":1,"start":0,"end":2.67,"parts":[{"zh":"你要红茶还是绿茶？"}],"pinyin":"nǐ yào hóngchá háishì lǜchá?","vi":"Bạn muốn trà đỏ hay trà xanh?"},{"n":2,"start":2.67,"end":6.84,"parts":[{"zh":"我要一杯奶茶，再加一些果汁，谢谢。"}],"pinyin":"wǒ yào yì bēi nǎichá, zài jiā yìxiē guǒzhī, xièxie.","vi":"Cho tôi một ly trà sữa, thêm chút nước trái cây, cảm ơn."},{"n":3,"start":6.84,"end":10.219999999999999,"parts":[{"zh":"你怎么不喝咖啡或者可乐呢？"}],"pinyin":"nǐ zěnme bù hē kāfēi huòzhě kělè ne?","vi":"Sao bạn không uống cà phê hay nước có ga?"},{"n":4,"start":10.219999999999999,"end":15.069999999999999,"parts":[{"zh":"我胃有毛病，不能喝那些。这儿的会员卡能打折吗？"}],"pinyin":"wǒ wèi yǒu máobìng, bù néng hē nàxiē. zhèr de huìyuán kǎ néng dǎzhé ma?","vi":"Dạ tôi dạ dày có vấn đề, không uống được mấy thứ đó. Thẻ hội viên ở đây có được giảm giá không?"},{"n":5,"start":15.069999999999999,"end":19.599999999999998,"parts":[{"zh":"当然可以。你办个会员卡吧，管理得很方便。"}],"pinyin":"dāngrán kěyǐ. nǐ bàn ge huìyuán kǎ ba, guǎnlǐ de hěn fāngbiàn.","vi":"Đương nhiên được. Bạn làm thẻ hội viên đi, quản lý rất tiện."},{"n":6,"start":19.599999999999998,"end":23.769999999999996,"parts":[{"zh":"好。我家乡也有这样的店，功能差不多。"}],"pinyin":"hǎo. wǒ jiāxiāng yě yǒu zhèyàng de diàn, gōngnéng chàbuduō.","vi":"Được. Quê tôi cũng có tiệm như thế này, chức năng tương tự."},{"n":7,"start":23.769999999999996,"end":28.619999999999997,"parts":[{"zh":"加强休息也很重要，别太困难的事都自己扛。"}],"pinyin":"jiāqiáng xiūxi yě hěn zhòngyào, bié tài kùnnán de shì dōu zìjǐ káng.","vi":"Nghỉ ngơi nhiều cũng quan trọng lắm, việc gì quá khó cũng đừng tự gánh một mình."},{"n":8,"start":28.619999999999997,"end":33.339999999999996,"parts":[{"zh":"谢谢你的关心。各位朋友都说，我最近瘦了。"}],"pinyin":"xièxie nǐ de guānxīn. gè wèi péngyou dōu shuō, wǒ zuìjìn shòu le.","vi":"Cảm ơn bạn quan tâm. Các bạn đều nói dạo này tôi gầy đi."},{"n":9,"start":33.339999999999996,"end":38.169999999999995,"parts":[{"zh":"那就更要照顾自己了。这些美食都能保存多久？"}],"pinyin":"nà jiù gèng yào zhàogù zìjǐ le. zhèxiē měishí dōu néng bǎocún duō jiǔ?","vi":"Vậy càng phải chăm sóc bản thân. Mấy món ngon này giữ được bao lâu?"},{"n":10,"start":38.169999999999995,"end":42.519999999999996,"parts":[{"zh":"两三天吧。告别之前，我把奶茶喝完！"}],"pinyin":"liǎng sān tiān ba. gàobié zhīqián, wǒ bǎ nǎichá hē wán!","vi":"Hai ba ngày. Trước khi chia tay, tôi uống hết ly trà sữa này đã!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-11';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-11', 0, '[{"n":1,"start":0,"end":4.33,"parts":[{"zh":"今天天气上升了十度，我们喝点凉的吧。"}],"pinyin":"jīntiān tiānqì shàngshēng le shí dù, wǒmen hē diǎn liáng de ba.","vi":"Hôm nay nhiệt độ tăng mười độ, mình uống chút đồ mát đi."},{"n":2,"start":4.33,"end":7.18,"parts":[{"zh":"好啊，我要啤酒，你呢？"}],"pinyin":"hǎo a, wǒ yào píjiǔ, nǐ ne?","vi":"Được, tôi uống bia, còn bạn?"},{"n":3,"start":7.18,"end":10.98,"parts":[{"zh":"我不要酒，我要一碗汤和一杯奶茶。"}],"pinyin":"wǒ bú yào jiǔ, wǒ yào yì wǎn tāng hé yì bēi nǎichá.","vi":"Tôi không uống rượu, tôi muốn một bát canh và một ly trà sữa."},{"n":4,"start":10.98,"end":15.58,"parts":[{"zh":"这里的汤很甜，是用沙子地里的白菜做的。"}],"pinyin":"zhèlǐ de tāng hěn tián, shì yòng shāzi dì lǐ de báicài zuò de.","vi":"Canh ở đây rất ngọt, nấu từ cải trắng trồng trên đất cát."},{"n":5,"start":15.58,"end":19.13,"parts":[{"zh":"听说糖吃多了，生命会有危险。"}],"pinyin":"tīngshuō táng chī duō le, shēngmìng huì yǒu wēixiǎn.","vi":"Nghe nói ăn nhiều đường thì sức khỏe có nguy hiểm."},{"n":6,"start":19.13,"end":23.849999999999998,"parts":[{"zh":"其次才是糖的问题，主要是要全面地吃饭。"}],"pinyin":"qícì cái shì táng de wèntí, zhǔyào shì yào quánmiàn de chīfàn.","vi":"Đường chỉ là vấn đề thứ yếu, chủ yếu là phải ăn uống đầy đủ."},{"n":7,"start":23.849999999999998,"end":29.47,"parts":[{"zh":"你能力真强，什么都懂。以前是不是在铁路上工作过？"}],"pinyin":"nǐ nénglì zhēn qiáng, shénme dōu dǒng. yǐqián shì bu shì zài tiělù shàng gōngzuò guo?","vi":"Bạn năng lực thật mạnh, hiểu biết mọi thứ. Trước đây bạn từng làm trên đường sắt à?"},{"n":8,"start":29.47,"end":33.94,"parts":[{"zh":"对，我以前是铁路工人，现在做石油生意。"}],"pinyin":"duì, wǒ yǐqián shì tiělù gōngrén, xiànzài zuò shíyóu shēngyi.","vi":"Đúng, trước tôi là công nhân đường sắt, giờ làm ăn về dầu mỏ."},{"n":9,"start":33.94,"end":38.39,"parts":[{"zh":"怪不得你的实力这么好，老板们都很认可你。"}],"pinyin":"guàibudé nǐ de shílì zhème hǎo, lǎobǎnmen dōu hěn rènkě nǐ.","vi":"Chả vậy thực lực của bạn tốt thế, các ông chủ đều công nhận bạn."},{"n":10,"start":38.39,"end":43.47,"parts":[{"zh":"哪里，都是随大家帮忙。我的命运才刚刚开始呢。"}],"pinyin":"nǎlǐ, dōu shì suí dàjiā bāngmáng. wǒ de mìngyùn cái gānggāng kāishǐ ne.","vi":"Đâu có, là nhờ mọi người giúp. Số phận của tôi mới chỉ bắt đầu thôi."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-12';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-12', 0, '[{"n":1,"start":0,"end":3.77,"parts":[{"zh":"你的听力进步很大，是怎么练习的？"}],"pinyin":"nǐ de tīnglì jìnbù hěn dà, shì zěnme liànxí de?","vi":"Kỹ năng nghe của bạn tiến bộ nhiều, bạn luyện thế nào?"},{"n":2,"start":3.77,"end":8.55,"parts":[{"zh":"我每天听广播，也从网上下载文化节目。"}],"pinyin":"wǒ měitiān tīng guǎngbō, yě cóng wǎngshàng xiàzǎi wénhuà jiémù.","vi":"Mỗi ngày tôi nghe đài, cũng tải các chương trình văn hóa trên mạng."},{"n":3,"start":8.55,"end":11.97,"parts":[{"zh":"看来学习效果不错。写作呢？"}],"pinyin":"kànlái xuéxí xiàoguǒ búcuò. xiězuò ne?","vi":"Xem ra học có hiệu quả. Còn viết thì sao?"},{"n":4,"start":11.97,"end":17.07,"parts":[{"zh":"写作难一点儿，汉字太多了。我整天都在练习。"}],"pinyin":"xiězuò nán yìdiǎnr, hànzì tài duō le. wǒ zhěngtiān dōu zài liànxí.","vi":"Viết hơi khó, chữ Hán nhiều quá. Cả ngày tôi đều luyện tập."},{"n":5,"start":17.07,"end":20.65,"parts":[{"zh":"你有没有形成自己的学习方法？"}],"pinyin":"nǐ yǒu méiyǒu xíngchéng zìjǐ de xuéxí fāngfǎ?","vi":"Bạn đã hình thành cách học riêng cho mình chưa?"},{"n":6,"start":20.65,"end":25.479999999999997,"parts":[{"zh":"有了，我把生词写在线上卡片里，随时复习。"}],"pinyin":"yǒu le, wǒ bǎ shēngcí xiě zài xiànshang kǎpiàn lǐ, suíshí fùxí.","vi":"Rồi, tôi ghi từ mới vào thẻ trên mạng, ôn bất cứ lúc nào."},{"n":7,"start":25.479999999999997,"end":29.759999999999998,"parts":[{"zh":"这样增加词汇量，成绩肯定提高得快。"}],"pinyin":"zhèyàng zēngjiā cíhuì liàng, chéngjì kěndìng tígāo de kuài.","vi":"Vậy tăng thêm lượng từ vựng, thành tích chắc chắn tiến bộ nhanh."},{"n":8,"start":29.759999999999998,"end":34.589999999999996,"parts":[{"zh":"对。等我行李收拾好，我要去图书馆学文学。"}],"pinyin":"duì. děng wǒ xíngli shōushi hǎo, wǒ yào qù túshūguǎn xué wénxué.","vi":"Đúng. Xếp hành lý xong, tôi sẽ đến thư viện học văn học."},{"n":9,"start":34.589999999999996,"end":39.419999999999995,"parts":[{"zh":"文明的语言也很重要，说话整齐一些，别太快。"}],"pinyin":"wénmíng de yǔyán yě hěn zhòngyào, shuōhuà zhěngqí yìxiē, bié tài kuài.","vi":"Ngôn ngữ văn minh cũng quan trọng, nói trau truốt một chút, đừng nói quá nhanh."},{"n":10,"start":39.419999999999995,"end":43.919999999999995,"parts":[{"zh":"好，我记住了。从今天开始，一步一步来。"}],"pinyin":"hǎo, wǒ jìzhù le. cóng jīntiān kāishǐ, yíbù yíbù lái.","vi":"Được, tôi nhớ rồi. Từ hôm nay, từng bước một."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-13';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-13', 0, '[{"n":1,"start":0,"end":3.9,"parts":[{"zh":"这个商品的价格太贵了，能便宜点儿吗？"}],"pinyin":"zhège shāngpǐn de jiàgé tài guì le, néng piányi diǎnr ma?","vi":"Giá món hàng này đắt quá, giảm bớt được không?"},{"n":2,"start":3.9,"end":8.35,"parts":[{"zh":"不能。我们的价钱是固定的，收费很公开。"}],"pinyin":"bù néng. wǒmen de jiàqián shì gùdìng de, shōufèi hěn gōngkāi.","vi":"Không được. Giá của chúng tôi cố định, thu phí rất công khai."},{"n":3,"start":8.35,"end":11.6,"parts":[{"zh":"那用现金还是刷卡支付？"}],"pinyin":"nà yòng xiànjīn háishì shuākǎ zhīfù?","vi":"Vậy thanh toán bằng tiền mặt hay quẹt thẻ?"},{"n":4,"start":11.6,"end":16.13,"parts":[{"zh":"都可以。不过人民币要交现金，美元也行。"}],"pinyin":"dōu kěyǐ. búguò rénmínbì yào jiāo xiànjīn, měiyuán yě xíng.","vi":"Đều được. Nhưng nhân dân tệ thì phải nộp tiền mặt, đô la Mỹ cũng được."},{"n":5,"start":16.13,"end":20.43,"parts":[{"zh":"好的。我还要交费吗？听说票价比网上高。"}],"pinyin":"hǎo de. wǒ hái yào jiāofèi ma? tīngshuō piàojià bǐ wǎngshàng gāo.","vi":"Được. Tôi còn phải nộp thêm phí gì không? Nghe nói giá vé cao hơn trên mạng."},{"n":6,"start":20.43,"end":25.55,"parts":[{"zh":"网上的交易一般便宜一些，但是得自己排队取票。"}],"pinyin":"wǎngshàng de jiāoyì yìbān piányi yìxiē, dànshì děi zìjǐ páiduì qǔ piào.","vi":"Giao dịch trên mạng thường rẻ hơn, nhưng phải tự xếp hàng lấy vé."},{"n":7,"start":25.55,"end":30.05,"parts":[{"zh":"这样太浪费我的时间了。上面那个柜子有包吗？"}],"pinyin":"zhèyàng tài làngfèi wǒ de shíjiān le. shàngmiàn nàge guìzi yǒu bāo ma?","vi":"Vậy phí thời gian tôi quá. Trên kệ có túi không?"},{"n":8,"start":30.05,"end":34.6,"parts":[{"zh":"有，那个包很值，里面还能装东西，很实用。"}],"pinyin":"yǒu, nàge bāo hěn zhí, lǐmiàn hái néng zhuāng dōngxi, hěn shíyòng.","vi":"Có, chiếc túi đó rất đáng tiền, bên trong còn đựng được đồ, rất tiện dụng."},{"n":9,"start":34.6,"end":39.6,"parts":[{"zh":"你们店里的商品真丰富，西部和南部的特产都有。"}],"pinyin":"nǐmen diàn lǐ de shāngpǐn zhēn fēngfù, xībù hé nánbù de tèchǎn dōu yǒu.","vi":"Hàng hóa trong cửa hàng phong phú thật, đặc sản Tây Nam và miền Nam đều có."},{"n":10,"start":39.6,"end":44.63,"parts":[{"zh":"对，我们主动为客人想办法，资金上也支持大家。"}],"pinyin":"duì, wǒmen zhǔdòng wèi kèrén xiǎng bànfǎ, zījīn shàng yě zhīchí dàjiā.","vi":"Đúng vậy, chúng tôi chủ động nghĩ cách cho khách, về vốn cũng hỗ trợ."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-14';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-14', 0, '[{"n":1,"start":0,"end":4.15,"parts":[{"zh":"咱们赶紧走吧，旅行社的车马上就到了。"}],"pinyin":"zánmen gǎnjǐn zǒu ba, lǚxíngshè de chē mǎshàng jiù dào le.","vi":"Mình đi nhanh lên, xe của công ty du lịch sắp đến rồi."},{"n":2,"start":4.15,"end":8.15,"parts":[{"zh":"等等我，我 map 上的路线还没看明白。"}],"pinyin":"děngděng wǒ, wǒ tú shàng de lùxiàn hái méi kàn míngbai.","vi":"Chờ tôi chút, tuyến đường trên bản đồ tôi còn chưa xem rõ."},{"n":3,"start":8.15,"end":12.05,"parts":[{"zh":"不用看，我们走高速公路，速度很快。"}],"pinyin":"bú yòng kàn, wǒmen zǒu gāosù gōnglù, sùdù hěn kuài.","vi":"Không cần xem, chúng ta đi đường cao tốc, tốc độ rất nhanh."},{"n":4,"start":12.05,"end":16.580000000000002,"parts":[{"zh":"好。我还需要休息，昨天散步走了太多路。"}],"pinyin":"hǎo. wǒ hái xūyào xiūxi, zuótiān sànbù zǒu le tài duō lù.","vi":"Được. Tôi vẫn cần nghỉ, hôm qua đi bộ quá nhiều."},{"n":5,"start":16.580000000000002,"end":21.160000000000004,"parts":[{"zh":"那正好，车上你可以睡觉。到了旅馆再活动。"}],"pinyin":"nà zhènghǎo, chē shàng nǐ kěyǐ shuìjiào. dào le lǚguǎn zài huódòng.","vi":"Thế càng tốt, trên xe bạn có thể ngủ. Đến khách sạn rồi hãy hoạt động."},{"n":6,"start":21.160000000000004,"end":26.460000000000004,"parts":[{"zh":"好主意。这次旅行有重大意义，我一定要好好配合。"}],"pinyin":"hǎo zhǔyi. zhè cì lǚxíng yǒu zhòngdà yìyì, wǒ yídìng yào hǎohǎo pèihé.","vi":"Ý hay. Chuyến đi này có ý nghĩa lớn, tôi nhất định phải phối hợp tốt."},{"n":7,"start":26.460000000000004,"end":31.460000000000004,"parts":[{"zh":"你飞行的时候害怕吗？强烈的风有时候让人紧张。"}],"pinyin":"nǐ fēixíng de shíhou hàipà ma? qiángliè de fēng yǒushíhou ràng rén jǐnzhāng.","vi":"Khi bay bạn có sợ không? Gió mạnh đôi khi khiến người ta lo lắng."},{"n":8,"start":31.460000000000004,"end":35.040000000000006,"parts":[{"zh":"不怕，我倒觉得飞行很有意思。"}],"pinyin":"bú pà, wǒ dào juéde fēixíng hěn yǒu yìsi.","vi":"Không sợ, tôi lại thấy bay rất thú vị."},{"n":9,"start":35.040000000000006,"end":40.24000000000001,"parts":[{"zh":"那太好了。听说这里的风景特别美，爱心游客都来了。"}],"pinyin":"nà tài hǎo le. tīngshuō zhèlǐ de fēngjǐng tèbié měi, àixīn yóukè dōu lái le.","vi":"Thế thì tốt. Nghe nói cảnh đẹp nơi này đặc biệt, du khách yêu mến đều đến."},{"n":10,"start":40.24000000000001,"end":44.12000000000001,"parts":[{"zh":"太棒了！我马上收拾东西出发。"}],"pinyin":"tài bàng le! wǒ mǎshàng shōushi dōngxi chūfā.","vi":"Tuyệt vời! Tôi ngay lập tức thu dọn đồ xuất phát."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-15';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-15', 0, '[{"n":1,"start":0,"end":2.98,"parts":[{"zh":"国庆节你打算怎么过？"}],"pinyin":"guóqìng jié nǐ dǎsuàn zěnme guò?","vi":"Lễ Quốc khánh bạn định ăn mừng thế nào?"},{"n":2,"start":2.98,"end":8.13,"parts":[{"zh":"我当初想回家，后来因为工作太忙，只好取消了。"}],"pinyin":"wǒ dāngchū xiǎng huí jiā, hòulái yīnwèi gōngzuò tài máng, zhǐhǎo qǔxiāo le.","vi":"Ban đầu tôi muốn về quê, sau đó vì việc quá bận đành phải hủy."},{"n":3,"start":8.13,"end":11.760000000000002,"parts":[{"zh":"太可惜了！你以前曾经回国过吗？"}],"pinyin":"tài kěxī le! nǐ yǐqián céngjīng huí guó guo ma?","vi":"Tiếc quá! Trước đây bạn từng về nước chưa?"},{"n":4,"start":11.760000000000002,"end":17.090000000000003,"parts":[{"zh":"回国过一次，大概五年前吧。那次的光景我现在还记得。"}],"pinyin":"huí guó guo yí cì, dàgài wǔ nián qián ba. nà cì de guāngjǐng wǒ xiànzài hái jìde.","vi":"Về nước một lần, khoảng năm năm trước. Cảnh tượng lúc đó giờ tôi vẫn nhớ."},{"n":5,"start":17.090000000000003,"end":20.240000000000002,"parts":[{"zh":"从那以后，你一直在国外吗？"}],"pinyin":"cóng nà yǐhòu, nǐ yìzhí zài guówài ma?","vi":"Từ đó đến giờ, bạn luôn ở nước ngoài à?"},{"n":6,"start":20.240000000000002,"end":25.82,"parts":[{"zh":"对，我从来没有那么长时间不在家。今年年初我打算回来。"}],"pinyin":"duì, wǒ cónglái méiyǒu nàme cháng shíjiān bú zài jiā. jīnnián niánchū wǒ dǎsuàn huílái.","vi":"Đúng, tôi chưa bao giờ xa nhà lâu như vậy. Đầu năm nay tôi định về."},{"n":7,"start":25.82,"end":29.47,"parts":[{"zh":"那你现在有事儿吗？我有点儿空儿。"}],"pinyin":"nà nǐ xiànzài yǒu shìr ma? wǒ yǒudiǎnr kòngr.","vi":"Vậy bây giờ bạn có bận gì không? Tôi có chút thời gian rảnh."},{"n":8,"start":29.47,"end":34.9,"parts":[{"zh":"正好，你帮我看一下这份创作，我赶紧要交给老师。"}],"pinyin":"zhènghǎo, nǐ bāng wǒ kàn yíxià zhè fèn chuàngzuò, wǒ gǎnjǐn yào jiāo gěi lǎoshī.","vi":"Đúng lúc, bạn giúp tôi xem bài sáng tác này, tôi phải nộp cho thầy gấp."},{"n":9,"start":34.9,"end":39.73,"parts":[{"zh":"好，慢慢写，别着急。发明新的东西也需要时间。"}],"pinyin":"hǎo, mànmàn xiě, bié zháojí. fāmíng xīn de dōngxi yě xūyào shíjiān.","vi":"Được, cứ từ từ, đừng vội. Sáng chế ra cái mới cũng cần thời gian."},{"n":10,"start":39.73,"end":45.029999999999994,"parts":[{"zh":"谢谢！以后我们光着脚也来不及的事，就提前安排。"}],"pinyin":"xièxie! yǐhòu wǒmen guāngzhe jiǎo yě láibují de shì, jiù tíqián ānpái.","vi":"Cảm ơn! Sau này việc gấp đến mức chân không kịp thì cứ sắp trước."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-16';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-16', 0, '[{"n":1,"start":0,"end":4.1,"parts":[{"zh":"还有一个月就到年底了，时间过得真快。"}],"pinyin":"hái yǒu yí ge yuè jiù dào niándǐ le, shíjiān guò de zhēn kuài.","vi":"Còn một tháng nữa là đến cuối năm, thời gian trôi nhanh thật."},{"n":2,"start":4.1,"end":8.379999999999999,"parts":[{"zh":"是啊，我年纪越大，越觉得时间不够用。"}],"pinyin":"shì a, wǒ niánjì yuè dà, yuè juéde shíjiān bú gòu yòng.","vi":"Ừ, tuổi càng lớn, tôi càng thấy thời gian không đủ dùng."},{"n":3,"start":8.379999999999999,"end":12.459999999999999,"parts":[{"zh":"你得提前做计划，不要等到最后一刻。"}],"pinyin":"nǐ děi tíqián zuò jìhuà, bú yào děng dào zuìhòu yí kè.","vi":"Bạn phải lên kế hoạch trước, đừng đợi đến phút cuối."},{"n":4,"start":12.459999999999999,"end":17.36,"parts":[{"zh":"你说得对。我约了医生，下午三点在门诊见面。"}],"pinyin":"nǐ shuō de duì. wǒ yuē le yīshēng, xiàwǔ sān diǎn zài ménzhěn jiànmiàn.","vi":"Bạn nói đúng. Tôi đã hẹn bác sĩ, ba giờ chiều gặp ở phòng khám."},{"n":5,"start":17.36,"end":21.009999999999998,"parts":[{"zh":"那你最好在钟敲三点以前到。"}],"pinyin":"nà nǐ zuìhǎo zài zhōng qiāo sān diǎn yǐqián dào.","vi":"Vậy tốt nhất bạn nên đến trước khi đồng hồ điểm ba."},{"n":6,"start":21.009999999999998,"end":25.479999999999997,"parts":[{"zh":"我总是提醒自己，可惜常常做不到。"}],"pinyin":"wǒ zǒng shì tíxǐng zìjǐ, kěxī chángcháng zuò bú dào.","vi":"Tôi luôn tự nhắc mình, tiếc là thường không làm được."},{"n":7,"start":25.479999999999997,"end":30.059999999999995,"parts":[{"zh":"其实从现在开始也来得及，一直坚持就好。"}],"pinyin":"qíshí cóng xiànzài kāishǐ yě láidejí, yìzhí jiānchí jiù hǎo.","vi":"Thật ra bắt đầu từ bây giờ vẫn kịp, chỉ cần kiên trì là được."},{"n":8,"start":30.059999999999995,"end":35.959999999999994,"parts":[{"zh":"好，我早就想改变了。从今天起，一直到年底，我都要早睡。"}],"pinyin":"hǎo, wǒ zǎojiù xiǎng gǎibiàn le. cóng jīntiān qǐ, yìzhí dào niándǐ, wǒ dōu yào zǎo shuì.","vi":"Được, tôi sớm đã muốn thay đổi. Từ hôm nay đến hết năm, tôi sẽ ngủ sớm."},{"n":9,"start":35.959999999999994,"end":39.629999999999995,"parts":[{"zh":"太好了！那你眼睛里又有精神了。"}],"pinyin":"tài hǎo le! nà nǐ yǎnjīng lǐ yòu yǒu jīngshén le.","vi":"Tốt quá! Vậy trong mắt bạn lại có tinh thần rồi."},{"n":10,"start":39.629999999999995,"end":42.23,"parts":[{"zh":"哈哈，但愿如此！"}],"pinyin":"hāhā, dànyuàn rúcǐ!","vi":"Haha, mong là vậy!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-17';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-17', 0, '[{"n":1,"start":0,"end":2.55,"parts":[{"zh":"你感冒好点儿了吗？"}],"pinyin":"nǐ gǎnmào hǎo diǎnr le ma?","vi":"Cảm cúm của bạn khá hơn chưa?"},{"n":2,"start":2.55,"end":7.8999999999999995,"parts":[{"zh":"好多了。本来我想去上班，后来决定在家休息一天。"}],"pinyin":"hǎo duō le. běnlái wǒ xiǎng qù shàngbān, hòulái juédìng zài jiā xiūxi yì tiān.","vi":"Khá hơn rồi. Lúc đầu tôi định đi làm, sau đó quyết định nghỉ ở nhà một ngày."},{"n":3,"start":7.8999999999999995,"end":13,"parts":[{"zh":"这几天天气变化太大了，国内很多地方都在下雨。"}],"pinyin":"zhè jǐ tiān tiānqì biànhuà tài dà le, guónèi hěn duō dìfang dōu zài xiàyǔ.","vi":"Vài ngày nay thời tiết biến động lớn, nhiều nơi trong nước đều mưa."},{"n":4,"start":13,"end":18.15,"parts":[{"zh":"是啊，这里的气候和我的家乡不一样，凉水太多了。"}],"pinyin":"shì a, zhèlǐ de qìhòu hé wǒ de jiāxiāng bù yíyàng, liángshuǐ tài duō le.","vi":"Ừ, khí hậu ở đây khác quê tôi, nước lạnh nhiều quá."},{"n":5,"start":18.15,"end":22.27,"parts":[{"zh":"你想不想去南方？那里的阳光特别好。"}],"pinyin":"nǐ xiǎng bù xiǎng qù nánfāng? nàlǐ de yángguāng tèbié hǎo.","vi":"Bạn có muốn đi miền Nam không? Ở đó nắng đẹp lắm."},{"n":6,"start":22.27,"end":27.17,"parts":[{"zh":"想去！听说天空总是很蓝，人们还非常友好。"}],"pinyin":"xiǎng qù! tīngshuō tiānkōng zǒngshì hěn lán, rénmen hái fēicháng yǒuhǎo.","vi":"Muốn lắm! Nghe nói bầu trời lúc nào cũng xanh, người dân lại rất thân thiện."},{"n":7,"start":27.17,"end":32.64,"parts":[{"zh":"那里的食品也好吃。很多华人住在那儿，吃饭很方便。"}],"pinyin":"nàlǐ de shípǐn yě hǎochī. hěn duō huárén zhù zài nàr, chīfàn hěn fāngbiàn.","vi":"Đồ ăn ở đó cũng ngon. Nhiều người Hoa sống ở đó, ăn uống rất tiện."},{"n":8,"start":32.64,"end":36.64,"parts":[{"zh":"太好了，我想去看看美丽的景色。"}],"pinyin":"tài hǎo le, wǒ xiǎng qù kànkàn měilì de jǐngsè.","vi":"Tốt quá, tôi muốn đi xem phong cảnh đẹp."},{"n":9,"start":36.64,"end":40.52,"parts":[{"zh":"快点儿好起来吧，到时候我们一起去！"}],"pinyin":"kuài diǎnr hǎo qǐlái ba, dào shíhou wǒmen yìqǐ qù!","vi":"Mau khỏe lại đi, đến lúc đó mình cùng đi nhé!"},{"n":10,"start":40.52,"end":42.67,"parts":[{"zh":"一言为定！"}],"pinyin":"yìyán wéi dìng!","vi":"Hẹn vậy nhé, nhất định!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-18';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-18', 0, '[{"n":1,"start":0,"end":2.98,"parts":[{"zh":"大夫今天怎么跟你说的？"}],"pinyin":"dàifu jīntiān zěnme gēn nǐ shuō de?","vi":"Hôm nay bác sĩ nói với bạn thế nào?"},{"n":2,"start":2.98,"end":6.859999999999999,"parts":[{"zh":"他说我的手指没问题，不用动刀。"}],"pinyin":"tā shuō wǒ de shǒuzhǐ méi wèntí, bú yòng dòng dāo.","vi":"Ông nói ngón tay tôi không sao, không cần mổ."},{"n":3,"start":6.859999999999999,"end":10.76,"parts":[{"zh":"太好了！那你平时喜欢做什么运动？"}],"pinyin":"tài hǎo le! nà nǐ píngshí xǐhuan zuò shénme yùndòng?","vi":"Tốt quá! Vậy bình thường bạn thích vận động gì?"},{"n":4,"start":10.76,"end":14.86,"parts":[{"zh":"我每天走一万步，身体感受很好。"}],"pinyin":"wǒ měitiān zǒu yí wàn bù, shēntǐ gǎnshòu hěn hǎo.","vi":"Mỗi ngày tôi đi mười nghìn bước, cảm giác cơ thể rất tốt."},{"n":5,"start":14.86,"end":18.509999999999998,"parts":[{"zh":"真好。我呢，每天坐着，越来越胖了。"}],"pinyin":"zhēn hǎo. wǒ ne, měitiān zuòzhe, yuèláiyuè pàng le.","vi":"Hay thật. Còn tôi ngày nào cũng ngồi, càng ngày càng béo."},{"n":6,"start":18.509999999999998,"end":23.61,"parts":[{"zh":"那不行，健康是最基本的。你可以穿短裤去跑步。"}],"pinyin":"nà bù xíng, jiànkāng shì zuì jīběn de. nǐ kěyǐ chuān duǎnkù qù pǎobù.","vi":"Vậy không được, sức khỏe là điều cơ bản nhất. Bạn có thể mặc quần đùi đi chạy bộ."},{"n":7,"start":23.61,"end":28.83,"parts":[{"zh":"好主意。不过古代的人不是更健康吗？他们没有汽车。"}],"pinyin":"hǎo zhǔyi. búguò gǔdài de rén bú shì gèng jiànkāng ma? tāmen méiyǒu qìchē.","vi":"Ý hay. Nhưng người thời cổ không phải khỏe hơn sao? Họ không có ô tô."},{"n":8,"start":28.83,"end":33.36,"parts":[{"zh":"也不一定，他们生病了很危险，没有好大夫。"}],"pinyin":"yě bù yídìng, tāmen shēngbìng le hěn wēixiǎn, méiyǒu hǎo dàifu.","vi":"Cũng chưa chắc, họ ốm đau thì nguy hiểm, không có bác sĩ giỏi."},{"n":9,"start":33.36,"end":37.74,"parts":[{"zh":"对，我们现在的生活和平又方便，要珍惜。"}],"pinyin":"duì, wǒmen xiànzài de shēnghuó hépíng yòu fāngbiàn, yào zhēnxī.","vi":"Đúng, cuộc sống của chúng ta bây giờ hòa bình và tiện lợi, phải trân trọng."},{"n":10,"start":37.74,"end":42.09,"parts":[{"zh":"是的。明天早上我们一起去公园走路吧？"}],"pinyin":"shì de. míngtiān zǎoshang wǒmen yìqǐ qù gōngyuán zǒulù ba?","vi":"Vậy nhé. Sáng mai mình cùng đến công viên đi bộ nhé?"},{"n":11,"start":42.09,"end":44.21,"parts":[{"zh":"好，七点见！"}],"pinyin":"hǎo, qī diǎn jiàn!","vi":"Được, gặp nhau lúc bảy giờ!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-19';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-19', 0, '[{"n":1,"start":0,"end":2.7,"parts":[{"zh":"你头上怎么有个包？"}],"pinyin":"nǐ tóu shang zěnme yǒu ge bāo?","vi":"Đầu bạn sao lại có cục?"},{"n":2,"start":2.7,"end":6.62,"parts":[{"zh":"昨天撞到门了，疼了好几个小时。"}],"pinyin":"zuótiān zhuàng dào mén le, téng le hǎo jǐ ge xiǎoshí.","vi":"Hôm qua va vào cửa, đau mấy tiếng đồng hồ."},{"n":3,"start":6.62,"end":10.2,"parts":[{"zh":"流血了吗？身体重要，别不在乎。"}],"pinyin":"liúxiě le ma? shēntǐ zhòngyào, bié bú zàihu.","vi":"Có chảy máu không? Cơ thể quan trọng, đừng coi thường."},{"n":4,"start":10.2,"end":15.049999999999999,"parts":[{"zh":"没流血。不过这次让我体会到了健康的可贵。"}],"pinyin":"méi liúxiě. búguò zhè cì ràng wǒ tǐhuì dào le jiànkāng de kěguì.","vi":"Không chảy máu. Nhưng lần này cho tôi cảm nhận được sức khỏe đáng quý."},{"n":5,"start":15.049999999999999,"end":18.2,"parts":[{"zh":"是的。你现在营养跟得上吗？"}],"pinyin":"shì de. nǐ xiànzài yíngyǎng gēn de shàng ma?","vi":"Đúng vậy. Bây giờ dinh dưỡng của bạn đủ không?"},{"n":6,"start":18.2,"end":22.799999999999997,"parts":[{"zh":"还可以。医生说要注意营养，也要预防感冒。"}],"pinyin":"hái kěyǐ. yīshēng shuō yào zhùyì yíngyǎng, yě yào yùfáng gǎnmào.","vi":"Cũng được. Bác sĩ dặn chú ý dinh dưỡng, cũng phải phòng cảm cúm."},{"n":7,"start":22.799999999999997,"end":25.97,"parts":[{"zh":"对。你最近是不是又抽烟了？"}],"pinyin":"duì. nǐ zuìjìn shì bu shì yòu chōuyān le?","vi":"Đúng. Dạo này bạn có hút thuốc lại không?"},{"n":8,"start":25.97,"end":30.169999999999998,"parts":[{"zh":"抽了两次，被女朋友看见了，她很生气。"}],"pinyin":"chōu le liǎng cì, bèi nǚpéngyou kànjian le, tā hěn shēngqì.","vi":"Hút hai lần, bị bạn gái thấy, cô ấy rất giận."},{"n":9,"start":30.169999999999998,"end":33.87,"parts":[{"zh":"她是对的。为了健康，烟一定要戒。"}],"pinyin":"tā shì duì de. wèile jiànkāng, yān yídìng yào jiè.","vi":"Cô ấy đúng. Vì sức khỏe, thuốc nhất định phải bỏ."},{"n":10,"start":33.87,"end":38.75,"parts":[{"zh":"我知道。我给他留下了不好的印象，真不好意思。"}],"pinyin":"wǒ zhīdào. wǒ gěi tā liúxià le bù hǎo de yìnxiàng, zhēn bù hǎoyìsi.","vi":"Tôi biết. Tôi đã để lại ấn tượng xấu cho cô ấy, thật ngại quá."},{"n":11,"start":38.75,"end":43.2,"parts":[{"zh":"没关系，改了就好。整个周末你好好休息吧。"}],"pinyin":"méi guānxì, gǎi le jiù hǎo. zhěng ge zhōumò nǐ hǎohāo xiūxi ba.","vi":"Không sao, sửa là được. Cả cuối tuần bạn cứ nghỉ ngơi cho khỏe."},{"n":12,"start":43.2,"end":46.470000000000006,"parts":[{"zh":"好，谢谢你，我一定照办。"}],"pinyin":"hǎo, xièxie nǐ, wǒ yídìng zhàobàn.","vi":"Được, cảm ơn bạn, tôi nhất định làm theo."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-20';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-20', 0, '[{"n":1,"start":0,"end":2.5,"parts":[{"zh":"听说你要搬家了？"}],"pinyin":"tīngshuō nǐ yào bānjiā le?","vi":"Nghe nói bạn sắp chuyển nhà?"},{"n":2,"start":2.5,"end":7,"parts":[{"zh":"对，我找到了一个新的屋子，房租便宜一些。"}],"pinyin":"duì, wǒ zhǎodào le yí ge xīn de wūzi, fángzū piányi yìxiē.","vi":"Đúng, tôi tìm được một căn phòng mới, tiền thuê rẻ hơn một chút."},{"n":3,"start":7,"end":10.42,"parts":[{"zh":"在首都吗？那儿的房租可贵了。"}],"pinyin":"zài shǒudū ma? nàr de fángzū kě guì le.","vi":"Ở thủ đô à? Tiền thuê nhà ở đó đắt lắm."},{"n":4,"start":10.42,"end":15.370000000000001,"parts":[{"zh":"不在市中心，在郊区。坐地铁半个小时就到。"}],"pinyin":"bú zài shìzhōngxīn, zài jiāoqū. zuò dìtiě bàn ge xiǎoshí jiù dào.","vi":"Không phải trung tâm, ở vùng ven. Đi tàu điện nửa tiếng là đến."},{"n":5,"start":15.370000000000001,"end":18.62,"parts":[{"zh":"那不错。新家有什么家具吗？"}],"pinyin":"nà búcuò. xīn jiā yǒu shénme jiājù ma?","vi":"Vậy được đấy. Nhà mới có nội thất gì không?"},{"n":6,"start":18.62,"end":22.92,"parts":[{"zh":"有沙发和书架，但是卫生间太小了。"}],"pinyin":"yǒu shāfā hé shūjià, dànshì wèishēngjiān tài xiǎo le.","vi":"Có ghế sô pha và kệ sách, nhưng nhà vệ sinh quá nhỏ."},{"n":7,"start":22.92,"end":26.62,"parts":[{"zh":"慢慢来，东西可以一件一件地买。"}],"pinyin":"mànmàn lái, dōngxi kěyǐ yí jiàn yí jiàn de mǎi.","vi":"Từ từ thôi, đồ đạc có thể mua từng món một."},{"n":8,"start":26.62,"end":31.740000000000002,"parts":[{"zh":"你说得对。我表姐在那儿的工厂工作，她会帮我。"}],"pinyin":"nǐ shuō de duì. wǒ biǎojiě zài nàr de gōngchǎng gōngzuò, tā huì bāng wǒ.","vi":"Bạn nói đúng. Chị họ tôi làm ở nhà máy gần đó, chị sẽ giúp tôi."},{"n":9,"start":31.740000000000002,"end":35.24,"parts":[{"zh":"那就好。搬家的时候需要人手吗？"}],"pinyin":"nà jiù hǎo. bānjiā de shíhou xūyào rénshǒu ma?","vi":"Vậy thì tốt. Ngày chuyển nhà có cần người giúp không?"},{"n":10,"start":35.24,"end":39.59,"parts":[{"zh":"需要！到时候你可别批评我东西太多啊！"}],"pinyin":"xūyào! dào shíhou nǐ kě bié pīpíng wǒ dōngxi tài duō a!","vi":"Có chứ! Đến lúc đó đừng chê tôi đồ nhiều quá nhé!"},{"n":11,"start":39.59,"end":42.74,"parts":[{"zh":"哈哈，放心，我一定准时到。"}],"pinyin":"hāhā, fàngxīn, wǒ yídìng zhǔnshí dào.","vi":"Haha, yên tâm, tôi nhất định đến đúng giờ."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-21';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-21', 0, '[{"n":1,"start":0,"end":3.6,"parts":[{"zh":"明天决赛的服装你准备好了吗？"}],"pinyin":"míngtiān juésài de fúzhuāng nǐ zhǔnbèi hǎo le ma?","vi":"Bạn chuẩn bị trang phục cho trận chung kết ngày mai chưa?"},{"n":2,"start":3.6,"end":7.630000000000001,"parts":[{"zh":"准备好了，金色的上衣，黑色的裤子。"}],"pinyin":"zhǔnbèi hǎo le, jīnsè de shàngyī, hēisè de kùzi.","vi":"Sẵn sàng rồi, áo vàng kim, quần đen."},{"n":3,"start":7.630000000000001,"end":11.68,"parts":[{"zh":"颜色真好看！那你穿裙子还是裤子呢？"}],"pinyin":"yánsè zhēn hǎokàn! nà nǐ chuān qúnzi háishì kùzi ne?","vi":"Màu đẹp thật! Vậy bạn mặc váy hay quần?"},{"n":4,"start":11.68,"end":15.98,"parts":[{"zh":"裤子方便一些，比赛的时候活动自如。"}],"pinyin":"kùzi fāngbiàn yìxiē, bǐsài de shíhou huódòng zìrú.","vi":"Quần tiện hơn, lúc thi đấu vận động thoải mái."},{"n":5,"start":15.98,"end":20.48,"parts":[{"zh":"对。不过你还得调整一下心理，别太紧张。"}],"pinyin":"duì. búguò nǐ hái děi tiáozhěng yíxià xīnlǐ, bié tài jǐnzhāng.","vi":"Đúng. Nhưng bạn còn phải điều chỉnh tâm lý, đừng quá căng thẳng."},{"n":6,"start":20.48,"end":24.46,"parts":[{"zh":"我保证不紧张。这次我一定要赢！"}],"pinyin":"wǒ bǎozhèng bù jǐnzhāng. zhè cì wǒ yídìng yào yíng!","vi":"Tôi cam đoan không căng thẳng. Lần này tôi nhất định phải thắng!"},{"n":7,"start":24.46,"end":28.34,"parts":[{"zh":"对，世界上的好事都是靠努力得来的。"}],"pinyin":"duì, shìjiè shàng de hǎoshì dōu shì kào nǔlì délái de.","vi":"Đúng, những điều tốt đẹp trên đời đều đến từ nỗ lực."},{"n":8,"start":28.34,"end":32.94,"parts":[{"zh":"嗯，从比赛开始到结束，我都会尽全力。"}],"pinyin":"ǹg, cóng bǐsài kāishǐ dào jiéshù, wǒ dōu huì jìn quánlì.","vi":"Ừ, từ đầu đến cuối trận, tôi sẽ dồn hết sức."},{"n":9,"start":32.94,"end":37.519999999999996,"parts":[{"zh":"加油！对了，衣服上的银色扣子掉了，得缝一下。"}],"pinyin":"jiāyóu! duìle, yīfu shàng de yínsè kòuzi diào le, děi féng yíxià.","vi":"Cố lên! À, cúc bạc trên áo rơi mất rồi, phải khâu lại."},{"n":10,"start":37.519999999999996,"end":41.75,"parts":[{"zh":"好，我马上去整理。一切都会顺利的！"}],"pinyin":"hǎo, wǒ mǎshàng qù zhěnglǐ. yíqiè dōu huì shùnlì de!","vi":"Được, tôi đi sắp xếp ngay. Mọi việc sẽ hanh thông!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-22';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-22', 0, '[{"n":1,"start":0,"end":2.98,"parts":[{"zh":"你收到我的电子邮件了吗？"}],"pinyin":"nǐ shōudào wǒ de diànzǐ yóujiàn le ma?","vi":"Bạn nhận được email của tôi chưa?"},{"n":2,"start":2.98,"end":7.33,"parts":[{"zh":"收到了，消息很重要，我马上就回复了。"}],"pinyin":"shōudào le, xiāoxi hěn zhòngyào, wǒ mǎshàng jiù huífù le.","vi":"Rồi, tin quan trọng mà, tôi trả lời ngay."},{"n":3,"start":7.33,"end":11.31,"parts":[{"zh":"谢谢！我想向你请教一个问题，可以吗？"}],"pinyin":"xièxie! wǒ xiǎng xiàng nǐ qǐngjiào yí ge wèntí, kěyǐ ma?","vi":"Cảm ơn! Tôi muốn hỏi bạn một vấn đề, được không?"},{"n":4,"start":11.31,"end":14.260000000000002,"parts":[{"zh":"当然可以。什么话题？"}],"pinyin":"dāngrán kěyǐ. shénme huàtí?","vi":"Đương nhiên được. Chủ đề gì vậy?"},{"n":5,"start":14.260000000000002,"end":18.910000000000004,"parts":[{"zh":"我想访问一位记者，可是不知道怎么联系他。"}],"pinyin":"wǒ xiǎng fǎngwèn yí wèi jìzhě, kěshì bù zhīdào zěnme liánxì tā.","vi":"Tôi muốn phỏng vấn một phóng viên, nhưng không biết cách liên hệ thế nào."},{"n":6,"start":18.910000000000004,"end":24.060000000000002,"parts":[{"zh":"你可以去电视台打听一下，他们办公室的人都知道。"}],"pinyin":"nǐ kěyǐ qù diànshìtái dǎting yíxià, tāmen bàngōngshì de rén dōu zhīdào.","vi":"Bạn có thể đến đài truyền hình hỏi thăm, ai trong văn phòng họ cũng biết."},{"n":7,"start":24.060000000000002,"end":28.680000000000003,"parts":[{"zh":"好主意。听说他是个奇怪的人，不接受访问？"}],"pinyin":"hǎo zhǔyi. tīngshuō tā shì ge qíguài de rén, bù jiēshòu fǎngwèn?","vi":"Ý hay. Nghe nói ông ấy là người kỳ lạ, không nhận phỏng vấn?"},{"n":8,"start":28.680000000000003,"end":33.85,"parts":[{"zh":"其实不是，老百姓都愿意跟他谈话。他只是很忙。"}],"pinyin":"qíshí bú shì, lǎobǎixìng dōu yuànyì gēn tā tánhuà. tā zhǐ shì hěn máng.","vi":"Thật ra không phải vậy, dân thường đều muốn nói chuyện với ông. Ông chỉ bận thôi."},{"n":9,"start":33.85,"end":38.08,"parts":[{"zh":"那就好。听说他每次发言都反对浪费。"}],"pinyin":"nà jiù hǎo. tīngshuō tā měi cì fāyán dōu fǎnduì làngfèi.","vi":"Vậy tốt. Nghe nói lần nào ông phát biểu cũng phản đối lãng phí."},{"n":10,"start":38.08,"end":43.33,"parts":[{"zh":"对，他提的问题往往都很尖锐，大家确实喜欢他。"}],"pinyin":"duì, tā tí de wèntí wǎngwǎng dōu hěn jiānruì, dàjiā quèshí xǐhuan tā.","vi":"Đúng, những câu hỏi ông đặt ra thường rất sắc bén, mọi người thật sự quý ông ấy."},{"n":11,"start":43.33,"end":46.28,"parts":[{"zh":"明白了，我这就去联系。"}],"pinyin":"míngbai le, wǒ zhè jiù qù liánxì.","vi":"Hiểu rồi, tôi đi liên hệ ngay đây."},{"n":12,"start":46.28,"end":50.03,"parts":[{"zh":"祝你好运！欢迎来我的邮箱留言。"}],"pinyin":"zhù nǐ hǎoyùn! huānyíng lái wǒ de yóuxiāng liúyán.","vi":"Chúc bạn may mắn! Mời bạn để lại lời nhắn vào hộp thư của tôi."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-23';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-23', 0, '[{"n":1,"start":0,"end":3.27,"parts":[{"zh":"今晚我们去看京剧表演好吗？"}],"pinyin":"jīnwǎn wǒmen qù kàn jīngjù biǎoyǎn hǎo ma?","vi":"Tối nay đi xem biểu diễn kinh kịch nhé?"},{"n":2,"start":3.27,"end":6.07,"parts":[{"zh":"好啊！剧场在哪儿？"}],"pinyin":"hǎo a! jùchǎng zài nǎr?","vi":"Được chứ! Nhà hát ở đâu?"},{"n":3,"start":6.07,"end":10.52,"parts":[{"zh":"在城市东边。先说好，我们可不能吵架了。"}],"pinyin":"zài chéngshì dōngbian. xiān shuō hǎo, wǒmen kě bù néng chǎojià le.","vi":"Ở phía đông thành phố. Thống nhất trước nhé, mình đừng cãi nhau."},{"n":4,"start":10.52,"end":14.29,"parts":[{"zh":"放心，看演出的时候我很安静。"}],"pinyin":"fàngxīn, kàn yǎnchū de shíhou wǒ hěn ānjìng.","vi":"Yên tâm, lúc xem biểu diễn tôi rất trật tự."},{"n":5,"start":14.29,"end":16.939999999999998,"parts":[{"zh":"你是歌迷还是戏迷？"}],"pinyin":"nǐ shì gēmí háishì xìmí?","vi":"Bạn là fan nhạc hay fan hát chèo?"},{"n":6,"start":16.939999999999998,"end":22.189999999999998,"parts":[{"zh":"都是！我以前听过很多歌手的歌，也喜欢看话剧。"}],"pinyin":"dōu shì! wǒ yǐqián tīng guo hěn duō gēshǒu de gē, yě xǐhuan kàn huàjù.","vi":"Đều là! Trước đây tôi nghe nhiều bài của các ca sĩ, cũng thích xem kịch nói."},{"n":7,"start":22.189999999999998,"end":27.72,"parts":[{"zh":"现在电视剧也发展得很好，我们还可以在家看连续剧。"}],"pinyin":"xiànzài diànshìjù yě fāzhǎn de hěn hǎo, wǒmen hái kěyǐ zài jiā kàn liánxùjù.","vi":"Giờ phim truyền hình cũng phát triển tốt, còn có thể xem phim dài tập ở nhà."},{"n":8,"start":27.72,"end":32.72,"parts":[{"zh":"看电视不运动可不行，我周末还要跑步、跳高。"}],"pinyin":"kàn diànshì bú yùndòng kě bù xíng, wǒ zhōumò hái yào pǎobù, tiàogāo.","vi":"Chỉ xem TV mà không vận động thì không được, cuối tuần tôi còn chạy bộ, nhảy cao."},{"n":9,"start":32.72,"end":35.89,"parts":[{"zh":"怪不得你的身体这么结实。"}],"pinyin":"guàibudé nǐ de shēntǐ zhème jiēshi.","vi":"Chả vậy mà thân hình bạn vạm vỡ thế."},{"n":10,"start":35.89,"end":41.19,"parts":[{"zh":"我们代表团还经常比赛呢。走了，别让孩子们等我们。"}],"pinyin":"wǒmen dàibiǎotuán hái jīngcháng bǐsài ne. zǒu le, bié ràng háizimen děng wǒmen.","vi":"Đoàn của chúng tôi còn hay thi đấu nữa. Đi thôi, đừng để lũ trẻ đợi."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-24';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-24', 0, '[{"n":1,"start":0,"end":3.88,"parts":[{"zh":"你到底想不想去留学？做个决定吧。"}],"pinyin":"nǐ dàodǐ xiǎng bù xiǎng qù liúxué? zuò ge juédìng ba.","vi":"Rốt cuộc bạn có muốn đi du học không? Quyết định đi."},{"n":2,"start":3.88,"end":8.33,"parts":[{"zh":"我想去，但是问题很复杂，我比较犹豫。"}],"pinyin":"wǒ xiǎng qù, dànshì wèntí hěn fùzá, wǒ bǐjiào yóuyù.","vi":"Tôi muốn đi, nhưng vấn đề phức tạp, tôi hơi phân vân."},{"n":3,"start":8.33,"end":12.030000000000001,"parts":[{"zh":"具体的困难是什么？说给我听听。"}],"pinyin":"jùtǐ de kùnnán shì shénme? shuō gěi wǒ tīngting.","vi":"Khó khăn cụ thể là gì? Kể tôi nghe xem."},{"n":4,"start":12.030000000000001,"end":16.68,"parts":[{"zh":"费用太高了，而且我担心自己达不到要求。"}],"pinyin":"fèiyòng tài gāo le, érqiě wǒ dānxīn zìjǐ dá bú dào yāoqiú.","vi":"Chi phí quá cao, nữa tôi lo mình không đạt yêu cầu."},{"n":5,"start":16.68,"end":20.28,"parts":[{"zh":"你有把握吗？先看看事实再说。"}],"pinyin":"nǐ yǒu bǎwò ma? xiān kànkàn shìshí zài shuō.","vi":"Bạn có tự tin không? Xem thực tế trước đã."},{"n":6,"start":20.28,"end":24.310000000000002,"parts":[{"zh":"其实我的成绩不错，理由还是有的。"}],"pinyin":"qíshí wǒ de chéngjì búcuò, lǐyóu háishì yǒu de.","vi":"Thật ra thành tích của tôi không tệ, lý do vẫn có."},{"n":7,"start":24.310000000000002,"end":28.360000000000003,"parts":[{"zh":"那你还犹豫什么？学习的机会很有价值。"}],"pinyin":"nà nǐ hái yóuyù shénme? xuéxí de jīhuì hěn yǒu jiàzhí.","vi":"Vậy còn do dự gì nữa? Cơ hội học tập rất có giá trị."},{"n":8,"start":28.360000000000003,"end":32.78,"parts":[{"zh":"你说得明确，我听清楚了。我坚决要去！"}],"pinyin":"nǐ shuō de míngquè, wǒ tīng qīngchu le. wǒ jiānjué yào qù!","vi":"Bạn nói rõ ràng, tôi nghe hiểu rồi. Tôi quyết tâm đi!"},{"n":9,"start":32.78,"end":36.980000000000004,"parts":[{"zh":"这才对！一个人的决心能带来明显的变化。"}],"pinyin":"zhè cái duì! yí ge rén de juéxīn néng dàilái míngxiǎn de biànhuà.","vi":"Vậy mới đúng! Quyết tâm của một người có thể mang lại thay đổi rõ rệt."},{"n":10,"start":36.980000000000004,"end":41.400000000000006,"parts":[{"zh":"嗯，这件事让我对将来的计划更深刻了。"}],"pinyin":"ǹg, zhè jiàn shì ràng wǒ duì jiānglái de jìhuà gèng shēnkè le.","vi":"Ừ, chuyện này khiến tôi hiểu sâu hơn về kế hoạch tương lai."},{"n":11,"start":41.400000000000006,"end":45.400000000000006,"parts":[{"zh":"好，祝你成功！到时候别忘了告诉我。"}],"pinyin":"hǎo, zhù nǐ chénggōng! dào shíhou bié wàngle gàosu wǒ.","vi":"Được, chúc bạn thành công! Đừng quên nói với tôi nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-25';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-25', 0, '[{"n":1,"start":0,"end":3.1,"parts":[{"zh":"这台新空调安装好了吗？"}],"pinyin":"zhè tái xīn kōngtiáo ānzhuāng hǎo le ma?","vi":"Máy điều hòa mới lắp đặt xong chưa?"},{"n":2,"start":3.1,"end":8.05,"parts":[{"zh":"快了，安装的师傅马上到。他们从城东赶到这儿。"}],"pinyin":"kuài le, ānzhuāng de shīfu mǎshàng dào. tāmen cóng chéngdōng gǎndào zhèr.","vi":"Sắp rồi, thợ lắp đặt sắp đến. Họ chạy từ phía đông thành phố sang đây."},{"n":3,"start":8.05,"end":12.280000000000001,"parts":[{"zh":"好。搬家的事呢？我们先把东西放到车上。"}],"pinyin":"hǎo. bānjiā de shì ne? wǒmen xiān bǎ dōngxi fàng dào chē shàng.","vi":"Được. Chuyện chuyển nhà thì sao? Mình先把 đồ lên xe trước."},{"n":4,"start":12.280000000000001,"end":16.51,"parts":[{"zh":"好。我搬了几次家，感觉一次比一次累。"}],"pinyin":"hǎo. wǒ bān le jǐ cì jiā, gǎnjué yí cì bǐ yí cì lèi.","vi":"Được. Tôi chuyển nhà mấy lần, cảm giác lần nào cũng mệt hơn."},{"n":5,"start":16.51,"end":21.410000000000004,"parts":[{"zh":"搬家也是学习的过程，能了解自己有多少东西。"}],"pinyin":"bānjiā yě shì xuéxí de guòchéng, néng liǎojiě zìjǐ yǒu duōshǎo dōngxi.","vi":"Chuyển nhà cũng là quá trình học hỏi, biết được mình có bao nhiêu đồ."},{"n":6,"start":21.410000000000004,"end":25.510000000000005,"parts":[{"zh":"哈哈，还发现了很多没用过的东西！"}],"pinyin":"hāhā, hái fāxiàn le hěn duō méi yòng guo de dōngxi!","vi":"Haha, còn phát hiện ra nhiều thứ chưa từng dùng!"},{"n":7,"start":25.510000000000005,"end":30.060000000000006,"parts":[{"zh":"分别的时候，别忘了告诉邻居们你的新地址。"}],"pinyin":"fēnbié de shíhou, bié wàngle gàosu línjūmen nǐ de xīn dìzhǐ.","vi":"Khi chia tay, đừng quên nói cho hàng xóm địa chỉ mới của bạn."},{"n":8,"start":30.060000000000006,"end":34.480000000000004,"parts":[{"zh":"我会的。电话一发出，大家就都收到了。"}],"pinyin":"wǒ huì de. diànhuà yì fāchū, dàjiā jiù dōu shōudào le.","vi":"Tôi sẽ thế. Tin nhắn vừa gửi đi là mọi người đều nhận được."},{"n":9,"start":34.480000000000004,"end":38.150000000000006,"parts":[{"zh":"对了，墙上那幅画要不要挂起来？"}],"pinyin":"duìle, qiáng shang nà fú huà yào bu yào guà qǐlái?","vi":"À, bức tranh trên tường có cần treo lên không?"},{"n":10,"start":38.150000000000006,"end":43.2,"parts":[{"zh":"挂吧！新家就要有个新样子，也产生点新气象。"}],"pinyin":"guà ba! xīn jiā jiù yào yǒu ge xīn yàngzi, yě chǎnshēng diǎn xīn qìxiàng.","vi":"Treo đi! Nhà mới phải có dáng vẻ mới, cũng tạo chút khí sắc mới."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-26';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-26', 0, '[{"n":1,"start":0,"end":3.77,"parts":[{"zh":"你最近在忙什么？好久没见面了。"}],"pinyin":"nǐ zuìjìn zài máng shénme? hǎojiǔ méi jiànmiàn le.","vi":"Dạo này bạn bận gì thế? Lâu rồi không gặp."},{"n":2,"start":3.77,"end":8.8,"parts":[{"zh":"我在建立一个新的网站，开展在线交流的活动。"}],"pinyin":"wǒ zài jiànlì yí ge xīn de wǎngzhàn, kāizhǎn zàixiàn jiāoliú de huódòng.","vi":"Tôi đang xây dựng một website mới, triển khai hoạt động giao tiếp trực tuyến."},{"n":3,"start":8.8,"end":12.15,"parts":[{"zh":"听起来不错！难道你不怕累吗？"}],"pinyin":"tīng qǐlái búcuò! nándào nǐ bú pà lèi ma?","vi":"Nghe hay đấy! Chẳng lẽ bạn không sợ mệt à?"},{"n":4,"start":12.15,"end":17.5,"parts":[{"zh":"其实很累，但是我不怕。经过考验才知道自己的能力。"}],"pinyin":"qíshí hěn lèi, dànshì wǒ bú pà. jīngguò kǎoyàn cái zhīdào zìjǐ de nénglì.","vi":"Thật ra rất mệt, nhưng tôi không sợ. Trải qua thử thách mới biết năng lực của mình."},{"n":5,"start":17.5,"end":21.53,"parts":[{"zh":"你的理论真不错。你怎么克服困难呢？"}],"pinyin":"nǐ de lǐlùn zhēn búcuò. nǐ zěnme kèfú kùnnán ne?","vi":"Lý luận của bạn hay đấy. Bạn vượt qua khó khăn thế nào?"},{"n":6,"start":21.53,"end":26.78,"parts":[{"zh":"一步一步来。另外，多向有经验的人请教也很重要。"}],"pinyin":"yíbù yíbù lái. lìngwài, duō xiàng yǒu jīngyàn de rén qǐngjiào yě hěn zhòngyào.","vi":"Từng bước một. Ngoài ra, hỏi ý kiến người có kinh nghiệm cũng rất quan trọng."},{"n":7,"start":26.78,"end":29.98,"parts":[{"zh":"环境对人的影响也很大吧？"}],"pinyin":"huánjìng duì rén de yǐngxiǎng yě hěn dà ba?","vi":"Môi trường ảnh hưởng đến con người cũng lớn lắm chứ?"},{"n":8,"start":29.98,"end":34.58,"parts":[{"zh":"对。在城市里工作，交往的人多，机会也多。"}],"pinyin":"duì. zài chéngshì lǐ gōngzuò, jiāowǎng de rén duō, jīhuì yě duō.","vi":"Đúng. Làm việc ở thành phố, người giao tiếp nhiều, cơ hội cũng nhiều."},{"n":9,"start":34.58,"end":37.059999999999995,"parts":[{"zh":"那你有什么缺点吗？"}],"pinyin":"nà nǐ yǒu shénme quēdiǎn ma?","vi":"Thế bạn có điểm yếu gì không?"},{"n":10,"start":37.059999999999995,"end":42.51,"parts":[{"zh":"我太容易分心，这是我最大的问题，我要进一步改进。"}],"pinyin":"wǒ tài róngyì fēnxīn, zhè shì wǒ zuì dà de wèntí, wǒ yào jìnyíbù gǎijìn.","vi":"Tôi dễ bị mất tập trung, đó là vấn đề lớn nhất của tôi, tôi sẽ cải tiến thêm."},{"n":11,"start":42.51,"end":46.239999999999995,"parts":[{"zh":"能认识到这一点就很好了。加油！"}],"pinyin":"néng rènshidào zhè yìdiǎn jiù hěn hǎo le. jiāyóu!","vi":"Nhận ra được điều này là rất tốt rồi. Cố lên!"},{"n":12,"start":46.239999999999995,"end":51.13999999999999,"parts":[{"zh":"谢谢，我会努力的。网站做好了请你来评价！"}],"pinyin":"xièxie, wǒ huì nǔlì de. wǎngzhàn zuò hǎo le qǐng nǐ lái píngjià!","vi":"Cảm ơn, tôi sẽ cố gắng. Website làm xong mời bạn đến đánh giá!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-27';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-27', 0, '[{"n":1,"start":0,"end":5.12,"parts":[{"zh":"刚才收音机里说，这个地区的工厂收了不少废品。"}],"pinyin":"gāngcái shōuyīnjī lǐ shuō, zhège dìqū de gōngchǎng shōu le bùshǎo fèipǐn.","vi":"Nãy giờ-radio nói nhà máy ở khu vực này thu không ít phế liệu."},{"n":2,"start":5.12,"end":9.32,"parts":[{"zh":"是啊，这是件好事，我同意他们的做法。"}],"pinyin":"shì a, zhè shì jiàn hǎoshì, wǒ tóngyì tāmen de zuòfǎ.","vi":"Ừ, đây là việc tốt, tôi đồng ý với cách làm của họ."},{"n":3,"start":9.32,"end":13.32,"parts":[{"zh":"不过他们扔石头进河里，这就不好了。"}],"pinyin":"búguò tāmen rēng shítou jìn hé lǐ, zhè jiù bù hǎo le.","vi":"Nhưng họ ném đá xuống sông thì không hay."},{"n":4,"start":13.32,"end":16.95,"parts":[{"zh":"真的吗？那会造成环境问题。"}],"pinyin":"zhēn de ma? nà huì zàochéng huánjìng wèntí.","vi":"Thật không? Vậy sẽ gây ra vấn đề môi trường."},{"n":5,"start":16.95,"end":20.75,"parts":[{"zh":"我们上去看看吧，把这事儿搞清楚。"}],"pinyin":"wǒmen shàngqu qù kànkàn ba, bǎ zhè shìr gǎo qīngchu.","vi":"Mình lên xem thử đi, làm rõ chuyện này."},{"n":6,"start":20.75,"end":25.1,"parts":[{"zh":"好。实际上，保护环境是每个人的责任。"}],"pinyin":"hǎo. shíjì shàng, bǎohù huánjìng shì měi ge rén de zérèn.","vi":"Được. Thực tế, bảo vệ môi trường là trách nhiệm của mỗi người."},{"n":7,"start":25.1,"end":28.400000000000002,"parts":[{"zh":"对。你们工厂属于哪个部门管？"}],"pinyin":"duì. nǐmen gōngchǎng shǔyú nǎge bùmén guǎn?","vi":"Đúng. Nhà máy của các bạn thuộc bộ phận nào quản lý?"},{"n":8,"start":28.400000000000002,"end":33.6,"parts":[{"zh":"属于市里的环保部门。我们可以打电话反映情况。"}],"pinyin":"shǔyú shì lǐ de huánbǎo bùmén. wǒmen kěyǐ dǎ diànhuà fǎnyìng qíngkuàng.","vi":"Thuộc bộ phận môi trường của thành phố. Mình có thể gọi điện phản ánh tình hình."},{"n":9,"start":33.6,"end":38.15,"parts":[{"zh":"好主意。让我们把这个问题深入地讨论一下。"}],"pinyin":"hǎo zhǔyi. ràng wǒmen bǎ zhège wèntí shēnrù de tǎolùn yíxià.","vi":"Ý hay. Cứ để chúng ta bàn bạc sâu vấn đề này."},{"n":10,"start":38.15,"end":42.62,"parts":[{"zh":"行。通过讨论，大家的思想就会更清楚。"}],"pinyin":"xíng. tōngguò tǎolùn, dàjiā de sīxiǎng jiù huì gèng qīngchu.","vi":"Được. Qua bàn bạc, tư tưởng của mọi người sẽ rõ hơn."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-28';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-28', 0, '[{"n":1,"start":0,"end":4.8,"parts":[{"zh":"这家工厂专门生产衣服，产品做得值得信赖。"}],"pinyin":"zhè jiā gōngchǎng zhuānmén shēngchǎn yīfu, chǎnpǐn zuò de zhídé xìnlài.","vi":"Nhà máy này chuyên sản xuất quần áo, sản phẩm làm đáng tin."},{"n":2,"start":4.8,"end":9.1,"parts":[{"zh":"他们的运输也不错，货物左右都能送到。"}],"pinyin":"tāmen de yùnshū yě búcuò, huòwù zuǒyòu dōu néng sòngdào.","vi":"Vận chuyển của họ cũng tốt, hàng hóa bên nào cũng giao đến được."},{"n":3,"start":9.1,"end":13.27,"parts":[{"zh":"听说周围的几个公司都想跟他们合作。"}],"pinyin":"tīngshuō zhōuwéi de jǐ ge gōngsī dōu xiǎng gēn tāmen hézuò.","vi":"Nghe nói vài công ty xung quanh đều muốn hợp tác với họ."},{"n":4,"start":13.27,"end":17.32,"parts":[{"zh":"因为他们互相尊重，很讲究信用。"}],"pinyin":"yīnwèi tāmen hùxiāng zūnzhòng, hěn jiǎngjiu xìnyòng.","vi":"Vì họ tôn trọng lẫn nhau, rất coi trọng uy tín."},{"n":5,"start":17.32,"end":21.32,"parts":[{"zh":"你认识他们的经理吗？能不能介绍一下？"}],"pinyin":"nǐ rènshi tāmen de jīnglǐ ma? néng bu néng jièshào yíxià?","vi":"Bạn quen giám đốc của họ không? Giới thiệu giúp được không?"},{"n":6,"start":21.32,"end":26.07,"parts":[{"zh":"认识。他这个人抓工作很紧，对人却很客气。"}],"pinyin":"rènshi. tā zhège rén zhuā gōngzuò hěn jǐn, duì rén què hěn kèqi.","vi":"Quen. Anh ấy bắt tay vào công việc rất chặt, nhưng với người lại rất lịch sự."},{"n":7,"start":26.07,"end":30.3,"parts":[{"zh":"那就好了。至少我们可以先去参观一下。"}],"pinyin":"nà jiù hǎo le. zhìshǎo wǒmen kěyǐ xiān qù cānguān yíxià.","vi":"Vậy tốt. Ít nhất chúng ta có thể đi tham quan trước."},{"n":8,"start":30.3,"end":34.85,"parts":[{"zh":"对。他们生产的过程很现代化，值得学习。"}],"pinyin":"duì. tāmen shēngchǎn de guòchéng hěn xiàndàihuà, zhídé xuéxí.","vi":"Đúng. Quy trình sản xuất của họ rất hiện đại, đáng học hỏi."},{"n":9,"start":34.85,"end":39.730000000000004,"parts":[{"zh":"那你先帮我们约个时间，咱们转一圈再谈合作。"}],"pinyin":"nà nǐ xiān bāng wǒmen yuē ge shíjiān, zánmen zhuàn yì quān zài tán hézuò.","vi":"Vậy bạn hẹn giúp thời gian trước, mình tham quan một vòng rồi mới bàn hợp tác."},{"n":10,"start":39.730000000000004,"end":42.50000000000001,"parts":[{"zh":"好，我马上打电话。"}],"pinyin":"hǎo, wǒ mǎshàng dǎ diànhuà.","vi":"Được, tôi gọi điện ngay."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-29';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-29', 0, '[{"n":1,"start":0,"end":2.88,"parts":[{"zh":"互联网让世界变小了。"}],"pinyin":"hùliánwǎng ràng shìjiè biàn xiǎo le.","vi":"Internet khiến thế giới thu nhỏ lại."},{"n":2,"start":2.88,"end":8.66,"parts":[{"zh":"对，一方面信息传播快，另一方面人也互相理解得更多了。"}],"pinyin":"duì, yì fāngmiàn xìnxī chuánbō kuài, lìng yì fāngmiàn rén yě hùxiāng lǐjiě de gèng duō le.","vi":"Đúng, một mặt thông tin lan nhanh, mặt khác con người hiểu nhau nhiều hơn."},{"n":3,"start":8.66,"end":11.89,"parts":[{"zh":"你是专家，说说你的主意吧。"}],"pinyin":"nǐ shì zhuānjiā, shuōshuo nǐ de zhǔyi ba.","vi":"Bạn là chuyên gia, nói ý kiến của bạn đi."},{"n":4,"start":11.89,"end":17.240000000000002,"parts":[{"zh":"我觉得人民的生活水平提高了，可是也要注意安全。"}],"pinyin":"wǒ juéde rénmín de shēnghuó shuǐpíng tígāo le, kěshì yě yào zhùyì ānquán.","vi":"Tôi thấy đời sống của người dân nâng cao, nhưng cũng phải chú ý an toàn."},{"n":5,"start":17.240000000000002,"end":21.860000000000003,"parts":[{"zh":"对。现在网上的骗子不少，还是要亲自核对。"}],"pinyin":"duì. xiànzài wǎngshàng de piànzǐ bù shǎo, háishì yào qīnzì héduì.","vi":"Đúng. Giờ lừa đảo trên mạng không ít, vẫn phải tự kiểm chứng."},{"n":6,"start":21.860000000000003,"end":27.060000000000002,"parts":[{"zh":"说得好。人生里的经验，都是一件一件的事情学来的。"}],"pinyin":"shuō de hǎo. rénshēng lǐ de jīngyàn, dōu shì yí jiàn yí jiàn de shìqing xué lái de.","vi":"Nói hay. Kinh nghiệm trong cuộc đời đều học từ từng việc một."},{"n":7,"start":27.060000000000002,"end":32.660000000000004,"parts":[{"zh":"人类就是这样进步的，不管科技怎么发展，人都得成长。"}],"pinyin":"rénlèi jiù shì zhèyàng jìnbù de, bùguǎn kējì zěnme fāzhǎn, rén dōu děi chéngzhǎng.","vi":"Nhân loại tiến bộ như thế, bất kể công nghệ phát triển thế nào, con người vẫn phải lớn lên."},{"n":8,"start":32.660000000000004,"end":37.49,"parts":[{"zh":"我完全同意。这一件事让我们都学到了很多。"}],"pinyin":"wǒ wánquán tóngyì. zhè yí jiàn shì ràng wǒmen dōu xuédào le hěn duō.","vi":"Tôi hoàn toàn đồng ý. Chuyện này giúp cả hai học được nhiều thứ."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-30';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-30', 0, '[{"n":1,"start":0,"end":3.15,"parts":[{"zh":"这位作家的作品，你读过吗？"}],"pinyin":"zhè wèi zuòjiā de zuòpǐn, nǐ dú guo ma?","vi":"Tác phẩm của nhà văn này bạn đọc chưa?"},{"n":2,"start":3.15,"end":8.05,"parts":[{"zh":"读过。他从前写的故事都很伟大，我很佩服。"}],"pinyin":"dú guo. tā cóngqián xiě de gùshi dōu hěn wěidà, wǒ hěn pèifú.","vi":"Rồi. Chuyện ông viết trước kia đều rất vĩ đại, tôi rất khâm phục."},{"n":3,"start":8.05,"end":12.47,"parts":[{"zh":"听说他的代表作体现了那个时代的生活。"}],"pinyin":"tīngshuō tā de dàibiǎo zuò tǐxiàn le nàge shídài de shēnghuó.","vi":"Nghe nói tác phẩm tiêu biểu của ông thể hiện cuộc sống của thời đại đó."},{"n":4,"start":12.47,"end":18.14,"parts":[{"zh":"是的，字里行间充满感情。我到现在还保留着他的书。"}],"pinyin":"shì de, zì lǐ háng jiān chōngmǎn gǎnqíng. wǒ dào xiànzài hái bǎoliú zhe tā de shū.","vi":"Đúng vậy, trong từng chữ tràn đầy cảm xúc. Đến giờ tôi vẫn giữ sách của ông."},{"n":5,"start":18.14,"end":20.810000000000002,"parts":[{"zh":"那我借来读读，可以吗？"}],"pinyin":"nà wǒ jiè lái dú du, kěyǐ ma?","vi":"Thế tôi mượn đọc được không?"},{"n":6,"start":20.810000000000002,"end":25.26,"parts":[{"zh":"当然可以。不过你要小心，别把书弄坏了。"}],"pinyin":"dāngrán kěyǐ. búguò nǐ yào xiǎoxīn, bié bǎ shū nòng huài le.","vi":"Đương nhiên được. Nhưng bạn phải cẩn thận, đừng làm hỏng sách."},{"n":7,"start":25.26,"end":28.360000000000003,"parts":[{"zh":"放心，我一定好好保护它。"}],"pinyin":"fàngxīn, wǒ yídìng hǎohǎo bǎohù tā.","vi":"Yên tâm, tôi nhất định giữ gìn sách cẩn thận."},{"n":8,"start":28.360000000000003,"end":33.31,"parts":[{"zh":"好。对了，今天晚上我们去他家做客，你去不去？"}],"pinyin":"hǎo. duìle, jīntiān wǎnshang wǒmen qù tā jiā zuòkè, nǐ qù bu qù?","vi":"Được. À, tối nay chúng tôi đến nhà ông ấy chơi, bạn đi không?"},{"n":9,"start":33.31,"end":36.04,"parts":[{"zh":"去！这正是我想要的。"}],"pinyin":"qù! zhè zhèng shì wǒ xiǎng yào de.","vi":"Đi! Đó chính là điều tôi mong muốn."},{"n":10,"start":36.04,"end":40.089999999999996,"parts":[{"zh":"那七点老地方见，我们保持联系。"}],"pinyin":"nà qī diǎn lǎo dìfang jiàn, wǒmen bǎochí liánxì.","vi":"Vậy bảy giờ gặp chỗ cũ, giữ liên lạc nhé."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-31';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-31', 0, '[{"n":1,"start":0,"end":5.05,"parts":[{"zh":"这个公司很有创新精神，产品一共有五十多种。"}],"pinyin":"zhège gōngsī hěn yǒu chuàngxīn jīngshén, chǎnpǐn yígòng yǒu wǔshí duō zhǒng.","vi":"Công ty này rất có tinh thần sáng tạo, sản phẩm có hơn năm mươi loại."},{"n":2,"start":5.05,"end":8.25,"parts":[{"zh":"他们是怎么分配工作的？"}],"pinyin":"tāmen shì zěnme fēnpèi gōngzuò de?","vi":"Họ phân công công việc thế nào?"},{"n":3,"start":8.25,"end":12.95,"parts":[{"zh":"每个小组负责一部分，初步的计划已经做好了。"}],"pinyin":"měi ge xiǎozǔ fùzé yí bùfen, chūbù de jìhuà yǐjīng zuò hǎo le.","vi":"Mỗi nhóm phụ trách một phần, kế hoạch ban đầu đã làm xong."},{"n":4,"start":12.95,"end":16.78,"parts":[{"zh":"那制度呢？他们的管理方法怎么样？"}],"pinyin":"nà zhìdù ne? tāmen de guǎnlǐ fāngfǎ zěnmeyàng?","vi":"Còn chế độ thì sao? Cách quản lý của họ ra sao?"},{"n":5,"start":16.78,"end":21.900000000000002,"parts":[{"zh":"制度很清楚，谁的责任就是谁的，前后都分得明白。"}],"pinyin":"zhìdù hěn qīngchu, shéi de zérèn jiù shì shéi de, qiánhòu dōu fēn de míngbai.","vi":"Chế độ rất rõ ràng, trách nhiệm của ai là của người đó, trước sau phân biệt rõ ràng."},{"n":6,"start":21.900000000000002,"end":27.1,"parts":[{"zh":"真不错。听说他们还利用新的技术来加快生产。"}],"pinyin":"zhēn búcuò. tīngshuō tāmen hái lìyòng xīn de jìshù lái jiākuài shēngchǎn.","vi":"Hay thật. Nghe nói họ còn tận dụng công nghệ mới để đẩy nhanh sản xuất."},{"n":7,"start":27.1,"end":31.950000000000003,"parts":[{"zh":"对，他们北部的工厂力量最强，生产速度最快。"}],"pinyin":"duì, tāmen běibù de gōngchǎng lìliàng zuì qiáng, shēngchǎn sùdù zuì kuài.","vi":"Đúng, nhà máy ở miền Bắc của họ có lực mạnh nhất, tốc độ sản xuất nhanh nhất."},{"n":8,"start":31.950000000000003,"end":35.980000000000004,"parts":[{"zh":"那我们向他们学习吧，千万不能落后。"}],"pinyin":"nà wǒmen xiàng tāmen xuéxí ba, qiānwàn bù néng luòhòu.","vi":"Thế mình học hỏi họ nhé, nhất định không được tụt lại."},{"n":9,"start":35.980000000000004,"end":40.260000000000005,"parts":[{"zh":"好，回去以后我们一起讨论，看怎么改进。"}],"pinyin":"hǎo, huíqù yǐhòu wǒmen yìqǐ tǎolùn, kàn zěnme gǎijìn.","vi":"Được, về sau mình cùng bàn bạc, xem cải tiến thế nào."},{"n":10,"start":40.260000000000005,"end":44.11000000000001,"parts":[{"zh":"一言为定。今天的收获真不少！"}],"pinyin":"yìyán wéi dìng. jīntiān de shōuhuò zhēn bù shǎo!","vi":"Nhất trí. Hôm nay thu được nhiều thứ thật!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-32';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-32', 0, '[{"n":1,"start":0,"end":3.58,"parts":[{"zh":"咱们公司打算取消这个项目吗？"}],"pinyin":"zánmen gōngsī dǎsuàn qǔxiāo zhège xiàngmù ma?","vi":"Công ty mình định hủy dự án này à?"},{"n":2,"start":3.58,"end":7.68,"parts":[{"zh":"不管怎样，先听听大家的反应再说。"}],"pinyin":"bùguǎn zěnyàng, xiān tīngting dàjiā de fǎnyìng zài shuō.","vi":"Dù thế nào, cứ nghe phản ứng của mọi người đã rồi tính."},{"n":3,"start":7.68,"end":12.46,"parts":[{"zh":"我觉得项目有很大变化，员工们都有点担心。"}],"pinyin":"wǒ juéde xiàngmù yǒu hěn dà biànhuà, yuángōngmen dōu yǒudiǎn dānxīn.","vi":"Tôi thấy dự án có biến động lớn, nhân viên ai cũng hơi lo."},{"n":4,"start":12.46,"end":17.86,"parts":[{"zh":"因此，我们应该召开一次会议，让双方都说说想法。"}],"pinyin":"yīncǐ, wǒmen yīnggāi zhàokāi yí cì huìyì, ràng shuāngfāng dōu shuōshuo xiǎngfǎ.","vi":"Vì vậy, chúng ta nên họp một buổi, để cả hai bên trình bày ý kiến."},{"n":5,"start":17.86,"end":22.31,"parts":[{"zh":"对。各家有各家的困难，互相理解最重要。"}],"pinyin":"duì. gè jiā yǒu gè jiā de kùnnán, hùxiāng lǐjiě zuì zhòngyào.","vi":"Đúng. Nhà nào cũng có khó riêng, hiểu nhau là quan trọng nhất."},{"n":6,"start":22.31,"end":26.54,"parts":[{"zh":"只有大家团结起来，问题才能解决。"}],"pinyin":"zhǐyǒu dàjiā tuánjié qǐlái, wèntí cái néng jiějué.","vi":"Chỉ khi mọi người đoàn kết, vấn đề mới giải quyết được."},{"n":7,"start":26.54,"end":31.04,"parts":[{"zh":"说得好。会议开完，我们再把文件整理一下。"}],"pinyin":"shuō de hǎo. huìyì kāi wán, wǒmen zài bǎ wénjiàn zhěnglǐ yíxià.","vi":"Nói hay. Họp xong, mình lại sắp xếp lại hồ sơ."},{"n":8,"start":31.04,"end":35.089999999999996,"parts":[{"zh":"好。你负责复印，我负责处理合同。"}],"pinyin":"hǎo. nǐ fùzé fùyìn, wǒ fùzé chǔlǐ hétong.","vi":"Được. Bạn phụ trách photo, tôi phụ trách xử lý hợp đồng."},{"n":9,"start":35.089999999999996,"end":40.01,"parts":[{"zh":"行。对了，这个会议室的窗户得开一开，外面太闷了。"}],"pinyin":"xíng. duìle, zhège huìyìshì de chuānghu děi kāi yi kāi, wàimiàn tài mèn le.","vi":"Được. À, cửa sổ phòng họp phải mở ra, ngoài kia ngột ngạt quá."},{"n":10,"start":40.01,"end":44.73,"parts":[{"zh":"好，我现在就去开。反正大家马上就到了。"}],"pinyin":"hǎo, wǒ xiànzài jiù qù kāi. fǎnzhèng dàjiā mǎshàng jiù dào le.","vi":"Được, tôi đi mở ngay. Dù sao mọi người cũng sắp đến rồi."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-33';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-33', 0, '[{"n":1,"start":0,"end":3.12,"parts":[{"zh":"你子女的学习情况怎么样？"}],"pinyin":"nǐ zǐnǚ de xuéxí qíngkuàng zěnmeyàng?","vi":"Tình hình học hành của con bạn thế nào?"},{"n":2,"start":3.12,"end":7.82,"parts":[{"zh":"女儿很努力，儿子就差一些，总是不想预习。"}],"pinyin":"nǚ''ér hěn nǔlì, érzi jiù chà yìxiē, zǒngshì bù xiǎng yùxí.","vi":"Con gái rất cố gắng, con trai kém hơn, lúc nào cũng không muốn ôn trước."},{"n":3,"start":7.82,"end":10.870000000000001,"parts":[{"zh":"那你怎么对待这个问题呢？"}],"pinyin":"nà nǐ zěnme duìdài zhège wèntí ne?","vi":"Vậy bạn đối xử với vấn đề này thế nào?"},{"n":4,"start":10.870000000000001,"end":16.04,"parts":[{"zh":"我带领他们一起学习，也告诉他们学习的重要意义。"}],"pinyin":"wǒ dàilǐng tāmen yìqǐ xuéxí, yě gàosu tāmen xuéxí de zhòngyào yìyì.","vi":"Tôi dẫn dắt các con cùng học, cũng nói cho chúng ý nghĩa quan trọng của việc học."},{"n":5,"start":16.04,"end":19.119999999999997,"parts":[{"zh":"学费贵吗？要不要请老师？"}],"pinyin":"xuéfèi guì ma? yào bu yào qǐng lǎoshī?","vi":"Học phí đắt không? Có cần thuê gia sư không?"},{"n":6,"start":19.119999999999997,"end":23.29,"parts":[{"zh":"不便宜，不过只要孩子们学得好，就值得。"}],"pinyin":"bù piányi, búguò zhǐyào háizimen xué de hǎo, jiù zhídé.","vi":"Không rẻ, nhưng miễn là các con học tốt là đáng."},{"n":7,"start":23.29,"end":27.869999999999997,"parts":[{"zh":"你说得对。孩子们将来幸福，比什么都重要。"}],"pinyin":"nǐ shuō de duì. háizimen jiānglái xìngfú, bǐ shénme dōu zhòngyào.","vi":"Bạn nói đúng. Tương lai hạnh phúc của các con quan trọng hơn mọi thứ."},{"n":8,"start":27.869999999999997,"end":31.79,"parts":[{"zh":"是啊。为了这个，我们再辛苦也应该。"}],"pinyin":"shì a. wèile zhège, wǒmen zài xīnkǔ yě yīnggāi.","vi":"Ừ. Vì điều đó, chúng tôi mệt đến đâu cũng đáng."},{"n":9,"start":31.79,"end":35.67,"parts":[{"zh":"那就好。要是需要帮忙，随时找我。"}],"pinyin":"nà jiù hǎo. yàoshi xūyào bāngmáng, suíshí zhǎo wǒ.","vi":"Vậy tốt. Nếu cần giúp đỡ, cứ tìm tôi bất cứ lúc nào."},{"n":10,"start":35.67,"end":38.25,"parts":[{"zh":"谢谢，我记住了。"}],"pinyin":"xièxie, wǒ jìzhù le.","vi":"Cảm ơn, tôi nhớ rồi."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-34';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-34', 0, '[{"n":1,"start":0,"end":2.83,"parts":[{"zh":"听说你当志愿者了？"}],"pinyin":"tīngshuō nǐ dāng zhìyuànzhě le?","vi":"Nghe nói bạn làm tình nguyện viên?"},{"n":2,"start":2.83,"end":6.71,"parts":[{"zh":"对，在社区帮忙，教孩子们画画。"}],"pinyin":"duì, zài shèqū bāngmáng, jiāo háizimen huà huà.","vi":"Đúng, giúp việc ở khu dân cư, dạy trẻ em vẽ."},{"n":3,"start":6.71,"end":9.83,"parts":[{"zh":"太有意义了！那怎么报名呢？"}],"pinyin":"tài yǒu yìyì le! nà zěnme bàomíng ne?","vi":"Ý nghĩa quá! Vậy làm thế nào để đăng ký?"},{"n":4,"start":9.83,"end":13.98,"parts":[{"zh":"先填个表格，再办一些手续，很快的。"}],"pinyin":"xiān tián ge biǎogé, zài bàn yìxiē shǒuxù, hěn kuài de.","vi":"Trước tiên điền đơn, rồi làm vài thủ tục, nhanh lắm."},{"n":5,"start":13.98,"end":18.73,"parts":[{"zh":"好，我也要参加。可是我怕自己表达得不够清楚。"}],"pinyin":"hǎo, wǒ yě yào cānjiā. kěshì wǒ pà zìjǐ biǎodá de bú gòu qīngchu.","vi":"Được, tôi cũng muốn tham gia. Nhưng tôi sợ diễn đạt không đủ rõ ràng."},{"n":6,"start":18.73,"end":24.51,"parts":[{"zh":"别怕，慢慢练习就好了。你可以先录录音，听听自己怎么说。"}],"pinyin":"bié pà, mànmàn liànxí jiù hǎo le. nǐ kěyǐ xiān lù lùyīn, tīngting zìjǐ zěnme shuō.","vi":"Đừng sợ, luyện tập từ từ là được. Bạn có thể thu âm trước, nghe xem mình nói thế nào."},{"n":7,"start":24.51,"end":28.790000000000003,"parts":[{"zh":"好主意！对了，教画画的时候要注意什么？"}],"pinyin":"hǎo zhǔyi! duìle, jiāo huà huà de shíhou yào zhùyì shénme?","vi":"Ý hay! À, khi dạy vẽ phải chú ý gì?"},{"n":8,"start":28.790000000000003,"end":33.74,"parts":[{"zh":"要有耐心，多鼓励他们。孩子的想象力很丰富。"}],"pinyin":"yào yǒu nàixīn, duō gǔlì tāmen. háizi de xiǎngxiànglì hěn fēngfù.","vi":"Phải kiên nhẫn, nhiều khích lệ các con. Trí tưởng tượng của trẻ rất phong phú."},{"n":9,"start":33.74,"end":37.690000000000005,"parts":[{"zh":"明白了。有什么情况我随时联系你。"}],"pinyin":"míngbai le. yǒu shénme qíngkuàng wǒ suíshí liánxì nǐ.","vi":"Hiểu rồi. Có tình huống gì tôi sẽ liên hệ bạn ngay."},{"n":10,"start":37.690000000000005,"end":40.99,"parts":[{"zh":"好。周末大家一起加油！"}],"pinyin":"hǎo. zhōumò dàjiā yìqǐ jiāyóu!","vi":"Được. Cuối tuần cả nhóm cùng cố gắng nhé!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-35';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-35', 0, '[{"n":1,"start":0,"end":3.42,"parts":[{"zh":"听说村里那条老路要改造了？"}],"pinyin":"tīngshuō cūn lǐ nà tiáo lǎolù yào gǎizào le?","vi":"Nghe nói con đường cũ trong làng sắp được cải tạo?"},{"n":2,"start":3.42,"end":7.67,"parts":[{"zh":"对，整个工程下个月开始，数量很大。"}],"pinyin":"duì, zhěng ge gōngchéng xià ge yuè kāishǐ, shùliàng hěn dà.","vi":"Đúng, toàn bộ công trình bắt đầu tháng sau, khối lượng lớn."},{"n":3,"start":7.67,"end":10.7,"parts":[{"zh":"那太好了！我们一定支持。"}],"pinyin":"nà tài hǎo le! wǒmen yídìng zhīchí.","vi":"Tốt quá! Chúng tôi nhất định ủng hộ."},{"n":4,"start":10.7,"end":15.6,"parts":[{"zh":"大家都很欢迎，有人说这是全村最大的好事。"}],"pinyin":"dàjiā dōu hěn huānyíng, yǒurén shuō zhè shì quān cūn zuì dà de hǎoshì.","vi":"Ai cũng hoan nghênh, có người nói đây là việc tốt lớn nhất cả làng."},{"n":5,"start":15.6,"end":20.32,"parts":[{"zh":"路修好了，卡车也能进来了，农产品好卖多了。"}],"pinyin":"lù xiū hǎo le, kǎchē yě néng jìn lái le, nóngchǎnpǐn hǎo mài duō le.","vi":"Đường sửa xong, xe tải cũng vào được, nông sản dễ bán hơn nhiều."},{"n":6,"start":20.32,"end":24.47,"parts":[{"zh":"是的。附近的人也都关心这个工程。"}],"pinyin":"shì de. fùjìn de rén yě dōu guānxīn zhège gōngchéng.","vi":"Đúng vậy. Người lân cận cũng đều quan tâm công trình này."},{"n":7,"start":24.47,"end":28.72,"parts":[{"zh":"对了，工地上用的木头和机器准备好了吗？"}],"pinyin":"duìle, gōngdì shàng yòng de mùtou hé jīqì zhǔnbèi hǎo le ma?","vi":"À, gỗ và máy móc dùng ở công trường chuẩn bị xong chưa?"},{"n":8,"start":28.72,"end":33.62,"parts":[{"zh":"都准备好了，标准很高，显然要建一条好路。"}],"pinyin":"dōu zhǔnbèi hǎo le, biāozhǔn hěn gāo, xiǎnrán yào jiàn yì tiáo hǎo lù.","vi":"Chuẩn bị xong hết rồi, tiêu chuẩn cao, rõ ràng là muốn xây một con đường tốt."},{"n":9,"start":33.62,"end":38.07,"parts":[{"zh":"那我们就等着吧，比原来暖和的日子也快来了。"}],"pinyin":"nà wǒmen jiù děngzhe ba, bǐ yuánlái nuǎnhuo de rìzi yě kuài lái le.","vi":"Thế mình chờ vậy, ngày tháng ấm hơn trước cũng sắp đến."},{"n":10,"start":38.07,"end":42.15,"parts":[{"zh":"好日子越来越普遍，谁都会高兴的。"}],"pinyin":"hǎo rìzi yuèláiyuè pǔbiàn, shéi dōu huì gāoxìng de.","vi":"Ngày tốt lành ngày càng phổ biến, ai cũng sẽ vui."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-36';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-36', 0, '[{"n":1,"start":0,"end":3.88,"parts":[{"zh":"周末去看那场演出吗？票你买好了吗？"}],"pinyin":"zhōumò qù kàn nà chǎng yǎnchū ma? piào nǐ mǎi hǎo le ma?","vi":"Cuối tuần đi xem buổi diễn đó không? Bạn mua vé chưa?"},{"n":2,"start":3.88,"end":8.879999999999999,"parts":[{"zh":"买好了。听说演员都是高手，演出一定精彩。"}],"pinyin":"mǎi hǎo le. tīngshuō yǎnyuán dōu shì gāoshǒu, yǎnchū yídìng jīngcǎi.","vi":"Mua rồi. Nghe nói diễn viên đều là tay nghề cao, biểu diễn chắc chắn xuất sắc."},{"n":3,"start":8.879999999999999,"end":12.629999999999999,"parts":[{"zh":"太好了！我还听说有个武术表演呢。"}],"pinyin":"tài hǎo le! wǒ hái tīngshuō yǒu ge wǔshù biǎoyǎn ne.","vi":"Tốt quá! Tôi còn nghe nói có màn biểu diễn võ thuật."},{"n":4,"start":12.629999999999999,"end":17.049999999999997,"parts":[{"zh":"对，他们的动作又快又美，观众都说好。"}],"pinyin":"duì, tāmen de dòngzuò yòu kuài yòu měi, guānzhòng dōu shuō hǎo.","vi":"Đúng, động tác của họ vừa nhanh vừa đẹp, khán giả ai cũng khen."},{"n":5,"start":17.049999999999997,"end":20.799999999999997,"parts":[{"zh":"那歌声呢？听说还有位著名的歌手。"}],"pinyin":"nà gēshēng ne? tīngshuō hái yǒu wèi zhùmíng de gēshǒu.","vi":"Còn tiếng hát thì sao? Nghe nói còn có một ca sĩ nổi tiếng."},{"n":6,"start":20.799999999999997,"end":25.769999999999996,"parts":[{"zh":"有，他的歌声很温暖，每次演唱会都坐满了人。"}],"pinyin":"yǒu, tā de gēshēng hěn wēnnuǎn, měi cì yǎnchànghuì dōu zuò mǎn le rén.","vi":"Có, giọng hát của anh ấy rất ấm áp, mỗi buổi hòa nhạc khán giả đều chật chỗ."},{"n":7,"start":25.769999999999996,"end":29.749999999999996,"parts":[{"zh":"怪不得票这么难买。对了，孩子们喜欢吗？"}],"pinyin":"guàibudé piào zhème nán mǎi. duìle, háizimen xǐhuan ma?","vi":"Chả vậy mà vé khó mua thế. À, bọn trẻ thích không?"},{"n":8,"start":29.749999999999996,"end":35.08,"parts":[{"zh":"喜欢极了。不过看完演出，我们得提醒他们早点睡觉。"}],"pinyin":"xǐhuan jí le. búguò kàn wán yǎnchū, wǒmen děi tíxǐng tāmen zǎodiǎn shuìjiào.","vi":"Thích lắm. Nhưng xem biểu diễn xong, chúng ta phải nhắc tụi nó ngủ sớm."},{"n":9,"start":35.08,"end":37.93,"parts":[{"zh":"对，别让孩子们太兴奋。"}],"pinyin":"duì, bié ràng háizimen tài xīngfèn.","vi":"Đúng, đừng để tụi nhỏ quá hào hứng."},{"n":10,"start":37.93,"end":41.93,"parts":[{"zh":"好，那就这样说定了，周六下午见！"}],"pinyin":"hǎo, nà jiù zhèyàng shuōdìng le, zhōuliù xiàwǔ jiàn!","vi":"Được, vậy quyết định như thế, chiều thứ Bảy gặp nhau!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-37';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-37', 0, '[{"n":1,"start":0,"end":4.33,"parts":[{"zh":"现在现场的球迷太多了，挤都挤不进去。"}],"pinyin":"xiànzài xiànchǎng de qiúmí tài duō le, jǐ dōu jǐ bu jìnqù.","vi":"Bây giờ fan bóng đá ở hiện trường đông quá, chen cũng không chen vào nổi."},{"n":2,"start":4.33,"end":7.85,"parts":[{"zh":"没关系，我们在外面看直播吧。"}],"pinyin":"méi guānxì, wǒmen zài wàimiàn kàn zhíbò ba.","vi":"Không sao, mình ra ngoài xem phát trực tiếp nhé."},{"n":3,"start":7.85,"end":12,"parts":[{"zh":"好啊。不过我担心网络会不会出问题。"}],"pinyin":"hǎo a. búguò wǒ dānxīn wǎngluò huì bú huì chū wèntí.","vi":"Được. Nhưng tôi lo mạng có trục trặc không."},{"n":4,"start":12,"end":16.88,"parts":[{"zh":"应该没问题。由于人太多，信号可能会慢一些。"}],"pinyin":"yīnggāi méi wèntí. yóuyú rén tài duō, xìnhào kěnéng huì màn yìxiē.","vi":"Chắc không sao. Do người quá đông, tín hiệu có thể chậm một chút."},{"n":5,"start":16.88,"end":21.58,"parts":[{"zh":"那也能理解。今天的比赛对两队都太重要了。"}],"pinyin":"nà yě néng lǐjiě. jīntiān de bǐsài duì liǎng duì dōu tài zhòngyào le.","vi":"Vậy cũng hiểu được. Trận đấu hôm nay với cả hai đội đều quá quan trọng."},{"n":6,"start":21.58,"end":25.229999999999997,"parts":[{"zh":"是啊。谁输了，谁就会被淘汰。"}],"pinyin":"shì a. shéi shū le, shéi jiù huì bèi táotài.","vi":"Ừ. Đội nào thua, đội đó bị loại."},{"n":7,"start":25.229999999999997,"end":28.58,"parts":[{"zh":"这么说，双方的压力都很大。"}],"pinyin":"zhème shuō, shuāngfāng de yālì dōu hěn dà.","vi":"Nói vậy, áp lực của cả hai bên đều lớn."},{"n":8,"start":28.58,"end":33.91,"parts":[{"zh":"对。不过这正是比赛的乐趣，不知道结果才精彩。"}],"pinyin":"duì. búguò zhè zhèng shì bǐsài de lèqù, bù zhīdào jiéguǒ cái jīngcǎi.","vi":"Đúng. Nhưng đây chính là thú vui của trận đấu, không biết kết quả mới thú vị."},{"n":9,"start":33.91,"end":37.79,"parts":[{"zh":"有道理。走吧，找个安静的地方看球。"}],"pinyin":"yǒu dàolǐ. zǒu ba, zhǎo ge ānjìng de dìfang kàn qiú.","vi":"Có lý. Đi thôi, tìm chỗ yên tĩnh xem bóng đá."},{"n":10,"start":37.79,"end":41.12,"parts":[{"zh":"好，比赛马上就要开始了！"}],"pinyin":"hǎo, bǐsài mǎshàng jiù yào kāishǐ le!","vi":"Được, trận đấu sắp bắt đầu rồi!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-38';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-38', 0, '[{"n":1,"start":0,"end":3.2,"parts":[{"zh":"这份工作什么时候结束？"}],"pinyin":"zhè fèn gōngzuò shénme shíhou jiéshù?","vi":"Công việc này khi nào kết thúc?"},{"n":2,"start":3.2,"end":8.2,"parts":[{"zh":"下个月。做完以后，我想继续学习，考个证书。"}],"pinyin":"xià ge yuè. zuò wán yǐhòu, wǒ xiǎng jìxù xuéxí, kǎo ge zhèngshū.","vi":"Tháng sau. Làm xong, tôi muốn tiếp tục học, thi lấy chứng chỉ."},{"n":3,"start":8.2,"end":11.87,"parts":[{"zh":"好主意！你想考哪个方面的证书？"}],"pinyin":"hǎo zhǔyi! nǐ xiǎng kǎo nǎge fāngmiàn de zhèngshū?","vi":"Ý hay! Bạn định thi chứng chỉ ngành nào?"},{"n":4,"start":11.87,"end":17.669999999999998,"parts":[{"zh":"美术方面的。我从小就喜欢画画，这简直是我的梦想。"}],"pinyin":"měishù fāngmiàn de. wǒ cóngxiǎo jiù xǐhuan huà huà, zhè jiǎnzhí shì wǒ de mèngxiǎng.","vi":"Về mĩ thuật. Từ nhỏ tôi đã thích vẽ, đây gần như là giấc mơ của tôi."},{"n":5,"start":17.669999999999998,"end":23.29,"parts":[{"zh":"那太好了。不过考试的时候可能很紧急，你得做好准备。"}],"pinyin":"nà tài hǎo le. búguò kǎoshì de shíhou kěnéng hěn jǐnjí, nǐ děi zuò hǎo zhǔnbèi.","vi":"Tốt quá. Nhưng lúc thi có thể rất gấp, bạn phải chuẩn bị tốt."},{"n":6,"start":23.29,"end":28.119999999999997,"parts":[{"zh":"我会努力的。这个职业跟艺术有关，我很喜欢。"}],"pinyin":"wǒ huì nǔlì de. zhège zhíyè gēn yìshù yǒu guān, wǒ hěn xǐhuan.","vi":"Tôi sẽ cố gắng. Nghề này liên quan đến nghệ thuật, tôi rất thích."},{"n":7,"start":28.119999999999997,"end":32.739999999999995,"parts":[{"zh":"有梦想就要去实现。万一失败了，也没关系。"}],"pinyin":"yǒu mèngxiǎng jiù yào qù shíxiàn. wànyī shībài le, yě méi guānxì.","vi":"Có ước mơ thì phải thực hiện. Có lỡ thất bại cũng không sao."},{"n":8,"start":32.739999999999995,"end":37.019999999999996,"parts":[{"zh":"谢谢你。有了你的支持，我更有信心了。"}],"pinyin":"xièxie nǐ. yǒu le nǐ de zhīchí, wǒ gèng yǒu xìnxīn le.","vi":"Cảm ơn bạn. Có bạn ủng hộ, tôi càng tự tin hơn."},{"n":9,"start":37.019999999999996,"end":39.47,"parts":[{"zh":"那我们一起加油吧！"}],"pinyin":"nà wǒmen yìqǐ jiāyóu ba!","vi":"Vậy cùng cố gắng nhé!"},{"n":10,"start":39.47,"end":41.82,"parts":[{"zh":"好，一言为定！"}],"pinyin":"hǎo, yìyán wéi dìng!","vi":"Được, hẹn thế nhé!"}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-39';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-39', 0, '[{"n":1,"start":0,"end":3.55,"parts":[{"zh":"这份表格里需要填写什么内容？"}],"pinyin":"zhè fèn biǎogé lǐ xūyào tiánxiě shénme nèiróng?","vi":"Trong đơn này cần điền nội dung gì?"},{"n":2,"start":3.55,"end":7.8999999999999995,"parts":[{"zh":"先写你的基本信息，再写联系方式。"}],"pinyin":"xiān xiě nǐ de jīběn xìnxī, zài xiě liánxì fāngshì.","vi":"Trước viết thông tin cơ bản, sau đó viết cách liên hệ."},{"n":3,"start":7.8999999999999995,"end":9.92,"parts":[{"zh":"还有别的吗？"}],"pinyin":"hái yǒu biéde ma?","vi":"Còn gì nữa không?"},{"n":4,"start":9.92,"end":14.84,"parts":[{"zh":"要写清楚你的责任，比如你负责的范围是什么。"}],"pinyin":"yào xiě qīngchu nǐ de zérèn, bǐrú nǐ fùzé de fànwéi shì shénme.","vi":"Phải viết rõ trách nhiệm của bạn, ví dụ phạm vi bạn phụ trách là gì."},{"n":5,"start":14.84,"end":18.47,"parts":[{"zh":"明白了。那怎么证明我的身份呢？"}],"pinyin":"míngbai le. nà zěnme zhèngmíng wǒ de shēnfèn ne?","vi":"Hiểu rồi. Vậy làm sao chứng minh danh tính của tôi?"},{"n":6,"start":18.47,"end":22.22,"parts":[{"zh":"带上你的证件，复印件也可以。"}],"pinyin":"dài shàng nǐ de zhèngjiàn, fùyìnjiàn yě kěyǐ.","vi":"Mang theo giấy tờ của bạn, bản photo cũng được."},{"n":7,"start":22.22,"end":25.34,"parts":[{"zh":"好的。要是格式不对怎么办？"}],"pinyin":"hǎo de. yàoshi géshì bú duì zěnme bàn?","vi":"Được. Nếu định dạng không đúng thì sao?"},{"n":8,"start":25.34,"end":29.990000000000002,"parts":[{"zh":"那就重新规范一下，按照上面的要求来。"}],"pinyin":"nà jiù chóngxīn guīfàn yíxià, ànzhào shàngmiàn de yāoqiú lái.","vi":"Vậy chỉnh lại cho chuẩn, theo đúng yêu cầu ghi ở trên."},{"n":9,"start":29.990000000000002,"end":33.910000000000004,"parts":[{"zh":"谢谢你提醒。这次考试我一定要赢。"}],"pinyin":"xièxie nǐ tíxǐng. zhè cì kǎoshì wǒ yídìng yào yíng.","vi":"Cảm ơn bạn nhắc nhở. Kỳ thi này tôi nhất định phải thắng."},{"n":10,"start":33.910000000000004,"end":37.830000000000005,"parts":[{"zh":"你肯定没问题，好好准备就行。"}],"pinyin":"nǐ kěndìng méi wèntí, hǎohǎo zhǔnbèi jiù xíng.","vi":"Bạn chắc chắn không sao, chuẩn bị kỹ là được."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-40';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-40', 0, '[{"n":1,"start":0,"end":3.05,"parts":[{"zh":"周末的足球比赛你看了吗？"}],"pinyin":"zhōumò de zúqiú bǐsài nǐ kàn le ma?","vi":"Cuối tuần bạn xem trận bóng đá chưa?"},{"n":2,"start":3.05,"end":6.199999999999999,"parts":[{"zh":"看了，我们队输了，真可惜。"}],"pinyin":"kàn le, wǒmen duì shū le, zhēn kěxī.","vi":"Xem rồi, đội mình thua, tiếc thật."},{"n":3,"start":6.199999999999999,"end":10.7,"parts":[{"zh":"是啊。不过他们的进步很明显，比以前强多了。"}],"pinyin":"shì a. búguò tāmen de jìnbù hěn míngxiǎn, bǐ yǐqián qiáng duō le.","vi":"Ừ. Nhưng tiến bộ của họ rất rõ ràng, mạnh hơn trước nhiều."},{"n":4,"start":10.7,"end":15.45,"parts":[{"zh":"对，新教练来了以后，训练方法也适合队员了。"}],"pinyin":"duì, xīn jiàoliàn lái le yǐhòu, xùnliàn fāngfǎ yě shìhé duìyuán le.","vi":"Đúng, huấn luyện viên mới đến sau, phương pháp tập cũng hợp với các cầu thủ hơn."},{"n":5,"start":15.45,"end":19.75,"parts":[{"zh":"听说他们以前训练完了还要加班开会。"}],"pinyin":"tīngshuō tāmen yǐqián xùnliàn wán le hái yào jiābān kāihuì.","vi":"Nghe nói trước đây tập xong còn phải tăng ca họp."},{"n":6,"start":19.75,"end":25.25,"parts":[{"zh":"现在好了，采取新的办法以后，队员们的状态好多了。"}],"pinyin":"xiànzài hǎo le, cǎiqǔ xīn de bànfǎ yǐhòu, duìyuánmen de zhuàngtài hǎo duō le.","vi":"Giờ thì tốt rồi, sau khi áp dụng cách mới, trạng thái của các cầu thủ khá hơn nhiều."},{"n":7,"start":25.25,"end":28.58,"parts":[{"zh":"怪不得他们连赢了好几场。"}],"pinyin":"guàibudé tāmen lián yíng le hǎo jǐ chǎng.","vi":"Chả vậy mà họ thắng liên tiếp mấy trận."},{"n":8,"start":28.58,"end":33.379999999999995,"parts":[{"zh":"虽然这次输了，但是错误也能让队伍更集中。"}],"pinyin":"suīrán zhè cì shū le, dànshì cuòwù yě néng ràng duìwǔ gèng jízhōng.","vi":"Tuy lần này thua, nhưng sai lầm cũng giúp đội tập trung hơn."},{"n":9,"start":33.379999999999995,"end":37.26,"parts":[{"zh":"说得好。我们一起去看下一场比赛吧！"}],"pinyin":"shuō de hǎo. wǒmen yìqǐ qù kàn xià yì chǎng bǐsài ba!","vi":"Nói hay. Trận tới mình cùng đi xem nhé!"},{"n":10,"start":37.26,"end":40.66,"parts":[{"zh":"好，到时候我们提前买票。"}],"pinyin":"hǎo, dào shíhou wǒmen tíqián mǎi piào.","vi":"Được, đến lúc đó mua vé trước."}]');
DELETE FROM content_shadowing_subtitles WHERE video_id = 'hsk3/lesson-41';
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, chunk, sentences) VALUES ('hsk3/lesson-41', 0, '[{"n":1,"start":0,"end":3.73,"parts":[{"zh":"你觉得这份工作最需要什么能力？"}],"pinyin":"nǐ juéde zhè fèn gōngzuò zuì xūyào shénme nénglì?","vi":"Bạn thấy công việc này cần năng lực gì nhất?"},{"n":2,"start":3.73,"end":8.15,"parts":[{"zh":"首先要有耐心，其次要有好的沟通能力。"}],"pinyin":"shǒuxiān yào yǒu nàixīn, qícì yào yǒu hǎo de gōutōng nénglì.","vi":"Trước hết phải kiên nhẫn, sau đó phải có khả năng giao tiếp tốt."},{"n":3,"start":8.15,"end":11.98,"parts":[{"zh":"有道理。那你为什么喜欢当老师呢？"}],"pinyin":"yǒu dàolǐ. nà nǐ wèishénme xǐhuan dāng lǎoshī ne?","vi":"Có lý. Vậy sao bạn thích làm giáo viên?"},{"n":4,"start":11.98,"end":17.6,"parts":[{"zh":"因为能帮助孩子们，看到他们的进步，我心里特别高兴。"}],"pinyin":"yīnwèi néng bāngzhù háizimen, kàndào tāmen de jìnbù, wǒ xīnlǐ tèbié gāoxìng.","vi":"Vì giúp được các em, nhìn thấy các em tiến bộ, trong lòng tôi đặc biệt vui."},{"n":5,"start":17.6,"end":21.55,"parts":[{"zh":"现在当老师紧张吗？听说压力不小。"}],"pinyin":"xiànzài dāng lǎoshī jǐnzhāng ma? tīngshuō yālì bù xiǎo.","vi":"Giờ làm thầy giáo có căng thẳng không? Nghe nói áp lực không nhỏ."},{"n":6,"start":21.55,"end":27.97,"parts":[{"zh":"有点儿，不过习惯就好了。早上安静地喝杯奶茶，一天都有精神。"}],"pinyin":"yǒudiǎnr, búguò xíguàn jiù hǎo le. zǎoshang ānjìng de hē bēi nǎichá, yì tiān dōu yǒu jīngshén.","vi":"Hơi chút, nhưng quen rồi là ổn. Sáng uống yên tĩnh một ly trà sữa, cả ngày đều có tinh thần."},{"n":7,"start":27.97,"end":32.12,"parts":[{"zh":"哈哈，这个办法好。对了，你的办公面积大吗？"}],"pinyin":"hāhā, zhège bànfǎ hǎo. duìle, nǐ de bàngōng miànjī dà ma?","vi":"Haha, cách này hay. À, diện tích văn phòng của bạn rộng không?"},{"n":8,"start":32.12,"end":36.5,"parts":[{"zh":"不大，但是很安静，我喜欢安静的地方。"}],"pinyin":"bú dà, dànshì hěn ānjìng, wǒ xǐhuan ānjìng de dìfang.","vi":"Không rộng, nhưng rất yên tĩnh, tôi thích nơi yên tĩnh."},{"n":9,"start":36.5,"end":41.33,"parts":[{"zh":"那就好。以后有麻烦的事情，随时找我商量。"}],"pinyin":"nà jiù hǎo. yǐhòu yǒu máfan de shìqing, suíshí zhǎo wǒ shāngliang.","vi":"Vậy tốt. Sau này có chuyện rắc rối, cứ tìm tôi bàn bạc bất cứ lúc nào."},{"n":10,"start":41.33,"end":45.53,"parts":[{"zh":"谢谢！有你这样的朋友，真是我的幸运。"}],"pinyin":"xièxie! yǒu nǐ zhèyàng de péngyou, zhēn shì wǒ de xìngyùn.","vi":"Cảm ơn! Có người bạn như bạn thật là may mắn của tôi."}]');
